class LeakageType(Enum):
    """انواع مختلف نشتی داده که می‌تواند Edge کاذب ایجاد کند"""
    TEMPORAL_LEAKAGE = "temporal_leakage"  # اطلاعات آینده در گذشته
    LOOKAHEAD_BIAS = "lookahead_bias"  # استانداردسازی با داده آینده
    FEATURE_LEAKAGE = "feature_leakage"  # فیچرهایی که آینده را لو می‌دهند
    INDEX_LEAKAGE = "index_leakage"  # نشتی از طریق ایندکس
    RESAMPLING_LEAKAGE = "resampling_leakage"  # نشتی در بازنمونه‌برداری
    SCALING_LEAKAGE = "scaling_leakage"  # نشتی در اسکیل کردن


@dataclass
class StressTestResult:
    """
    نتیجه یک تست استرس.

    🔥 v14.2: فیلد `skipped` اضافه شد تا skip از pass تفکیک شود.
    - skipped=True  → تست اجرا نشد (داده کافی نبود، X_train داده نشد و ...)
    - passed=True   → تست واقعاً اجرا شد و پاس شد
    - passed=False  → تست اجرا شد و شکست خورد (leakage detected)
    """
    test_name: str
    passed: bool
    original_sharpe: float
    stress_sharpe: float
    degradation: float
    confidence: float
    details: str
    leakage_detected: Optional[LeakageType] = None
    skipped: bool = False

