class DirectionSignalBuilder:
    """
    DIRECTION_SIGNAL_BUILDER v1.0 — MOVEMENT-VS-COST AWARE SIGNAL GENERATOR.

    چرا این کلاس لازم است:
        پس از 2-class کردن price_direction، مفهوم NEUTRAL دیگر یک کلاس
        یادگرفته‌شده نیست. این کلاس آن را در لحظهٔ تصمیم‌گیری می‌سازد
        با ترکیب دو فیلتر:
            ۱. اطمینان (confidence) خروجی softmax مدل
            ۲. کفایت حرکت (expected move) نسبت به هزینهٔ معامله

    این معماری، Label Generator را از پارامترهای تجاری جدا نگه می‌دارد:
        - در تغییر بروکر / کارمزد / تایم‌فریم، فقط پارامترهای این کلاس
          را دوباره پیکربندی می‌کنید. نیازی به regenerate لیبل‌ها و
          retrain مدل نیست.
        - در ارزیابی، این کلاس را با سیگنال override صدا بزنید.
        - در ترید زنده، همین کلاس را با بروکر فعال پیکربندی کنید.

    پارامترها:
        confidence_threshold: θ روی max softmax. پیش‌فرض 0.55.
        cost_multiplier     : ضریب ایمنی روی هزینهٔ رفت-و-برگشت. پیش‌فرض 2.0.
        transaction_cost    : کارمزد هر طرف (0.0005 = 5bp).
        slippage            : لغزش هر طرف (0.0002 = 2bp).
        volatility_lookback : پنجرهٔ σ (تعداد کندل اخیر).
        horizon             : افق پیش‌بینی (هم‌راستا با LabelGenerator).
        safety_k            : ضریب محافظه‌کاری روی σ·√h. پیش‌فرض 1.0.
    """

    def __init__(
        self,
        confidence_threshold: float = 0.55,
        cost_multiplier: float = 2.0,
        transaction_cost: float = 0.0005,
        slippage: float = 0.0002,
        volatility_lookback: int = 20,
        horizon: int = 1,
        safety_k: float = 1.0,
    ):
        self.confidence_threshold = float(np.clip(confidence_threshold, 0.5, 0.95))
        self.cost_multiplier = float(max(1.0, cost_multiplier))
        self.round_trip_cost = 2.0 * (
            max(0.0, float(transaction_cost))
            + max(0.0, float(slippage))
        )
        self.volatility_lookback = int(max(5, volatility_lookback))
        self.horizon = int(max(1, horizon))
        self.safety_k = float(max(0.1, safety_k))

        logger.info(
            "DirectionSignalBuilder | θ_conf=%.3f | cost_mult=%.2f | "
            "round_trip_cost=%.5f (%.1f bp) | σ_win=%d | h=%d | k=%.2f",
            self.confidence_threshold, self.cost_multiplier,
            self.round_trip_cost, self.round_trip_cost * 1e4,
            self.volatility_lookback, self.horizon, self.safety_k,
        )

    def recent_volatility(self, prices: np.ndarray) -> float:
        """σ بازده‌های اخیر (کندل‌به‌کندل)."""
        p = np.asarray(prices, dtype=np.float64).reshape(-1)
        if p.size < 2:
            return 0.0
        rets = np.diff(p) / np.maximum(np.abs(p[:-1]), 1e-12)
        window = rets[-self.volatility_lookback:]
        window = window[np.isfinite(window)]
        if window.size < 5:
            return 0.0
        return float(np.std(window))

    def expected_move(self, prices: np.ndarray) -> float:
        """σ · √h · safety_k به‌عنوان برآورد حرکت در افق h."""
        sigma = self.recent_volatility(prices)
        return self.safety_k * sigma * float(np.sqrt(self.horizon))

    def build_signal(
        self,
        direction_probs: np.ndarray,
        recent_prices: np.ndarray,
        override_confidence: Optional[float] = None,
        override_expected_move: Optional[float] = None,
    ) -> np.ndarray:
        """
        ورودی:
            direction_probs: (N, 2) — softmax روی {0:SELL, 1:BUY}
            recent_prices  : (T,)  — قیمت‌های اخیر برای σ
        خروجی:
            np.ndarray[int64] با مقادیر {-1, 0, +1} در طول N.
        """
        P = np.asarray(direction_probs, dtype=np.float64)
        if P.ndim != 2 or P.shape[1] != 2:
            raise ValueError(
                f"DirectionSignalBuilder expects (N, 2) probs; got {P.shape}"
            )

        conf = (
            float(np.clip(override_confidence, 0.5, 0.95))
            if override_confidence is not None
            else self.confidence_threshold
        )
        emv = (
            float(max(0.0, override_expected_move))
            if override_expected_move is not None
            else self.expected_move(recent_prices)
        )
        cost_barrier = self.cost_multiplier * self.round_trip_cost

        max_p = P.max(axis=1)
        argmax = P.argmax(axis=1)          # 0 = SELL, 1 = BUY

        signal = np.zeros(P.shape[0], dtype=np.int64)

        passes_conf = max_p >= conf
        passes_move = emv >= cost_barrier

        if passes_move:
            signal[(argmax == 0) & passes_conf] = -1
            signal[(argmax == 1) & passes_conf] = +1

        n_traded = int(np.sum(signal != 0))
        n_sell = int(np.sum(signal == -1))
        n_buy = int(np.sum(signal == 1))
        logger.debug(
            "[DirectionSignalBuilder] N=%d | σ=%.6f | emv=%.6f | "
            "cost_barrier=%.6f | pass_move=%s | traded=%d (SELL=%d, BUY=%d)",
            P.shape[0], self.recent_volatility(recent_prices), emv,
            cost_barrier, bool(passes_move), n_traded, n_sell, n_buy,
        )

        return signal
        
@njit(cache=True)
def _simulate_trades_numba(
    true_ret,
    signal,
    stop_loss,
    take_profit,
    trailing_stop,
    tc,
    slp,
    min_interval,
):
    """
    شبیه‌ساز معاملات با PnL تجمعی + Trailing Stop + Mark-to-Market — v5.1.

    🔥 اصلاحات v5.1 (نسبت به v5.0):
      • حذف `fastmath=True` از decorator — دترمینیسم بیت‌به‌بیت با نسخهٔ
        NumPy تضمین می‌شود. در مرحلهٔ Stage-C ممیزی، نسخهٔ fastmath در مرز
        تصمیم trailing-stop واگرا می‌شد (۵ معاملهٔ واگرا در ۱۹۹ نوار).
        هزینهٔ حذف: ~۱۰٪ سرعت — که در بنچمارک عملاً صفر بود (0.024ms در برابر 0.022ms).

    🔥 حفظ‌شده از v5.0:
      1) اگر ضریب یک نوار (1±r) غیرمثبت شود، پوزیشن بلافاصله با ضرر ۱۰۰٪
         بسته می‌شود (reason=1) و حساب ruined می‌گردد؛ معاملات بعدی باز
         نمی‌شوند و equity روی همان مقدار باقی می‌ماند.
      2) بافر eq اندازهٔ n+2 دارد (رفع نوشتن خارج از محدوده در tail).
    """
    n = true_ret.shape[0]
    cap = 1.0
    pos = 0
    entry_cap = 1.0
    pos_cap = 1.0
    peak_cap = 1.0
    last_open = -1000000
    ruined = 0

    eq = np.empty(n + 2, dtype=np.float64)
    eq[0] = 1.0
    eq_n = 1

    pnls = np.empty(n, dtype=np.float64)
    reasons = np.empty(n, dtype=np.int64)
    n_tr = 0
    wins = 0

    for i in range(n):
        if ruined == 1:
            eq[eq_n] = cap
            eq_n += 1
            continue

        s = signal[i]

        if pos == 0:
            if s != 0 and (i - last_open) >= min_interval:
                pos = s
                entry_cap = cap * (1.0 - tc - slp)
                pos_cap = entry_cap
                peak_cap = entry_cap
                last_open = i
        else:
            r = true_ret[i]
            if pos == 1:
                factor = 1.0 + r
            else:
                factor = 1.0 - r

            if factor <= 1e-12:
                pnls[n_tr] = -1.0
                reasons[n_tr] = 1
                n_tr += 1
                cap = 0.0
                pos = 0
                pos_cap = 0.0
                peak_cap = 0.0
                ruined = 1
                eq[eq_n] = cap
                eq_n += 1
                continue

            pos_cap = pos_cap * factor

            if pos_cap > peak_cap:
                peak_cap = pos_cap

            pnl_cum = (pos_cap / entry_cap) - 1.0
            peak_pnl = (peak_cap / entry_cap) - 1.0
            draw_from_peak = (peak_cap - pos_cap) / (peak_cap + 1e-12)

            reason = 0
            if pnl_cum <= -stop_loss:
                reason = 1
            elif pnl_cum >= take_profit:
                reason = 2
            elif trailing_stop > 0.0 and peak_pnl > 0.0 and draw_from_peak >= trailing_stop:
                reason = 5
            elif s != 0 and s != pos:
                reason = 3

            if reason != 0:
                final_cap = pos_cap * (1.0 - tc - slp)
                pp = (final_cap / entry_cap) - 1.0 if entry_cap > 0 else 0.0
                pnls[n_tr] = pp
                reasons[n_tr] = reason
                n_tr += 1
                if pp > 0:
                    wins += 1
                cap = final_cap
                pos = 0
                pos_cap = cap
                peak_cap = cap
                if cap <= 1e-12:
                    cap = 0.0
                    pos_cap = 0.0
                    peak_cap = 0.0
                    ruined = 1

        eq[eq_n] = pos_cap if pos != 0 else cap
        eq_n += 1

    if pos != 0 and ruined == 0:
        final_cap = pos_cap * (1.0 - tc - slp)
        pp = (final_cap / entry_cap) - 1.0 if entry_cap > 0 else 0.0
        pnls[n_tr] = pp
        reasons[n_tr] = 4
        n_tr += 1
        if pp > 0:
            wins += 1
        cap = final_cap
        eq[eq_n] = cap
        eq_n += 1

    return eq[:eq_n], pnls[:n_tr], reasons[:n_tr], cap, wins

def _simulate_trades_numpy(
    true_ret,
    signal,
    stop_loss,
    take_profit,
    trailing_stop,
    tc,
    slp,
    min_interval,
):
    """نسخهٔ NumPy از `_simulate_trades_numba` v5.0 (منطق یکسان، بافر لیستی)."""
    n = len(true_ret)
    cap = 1.0
    pos = 0
    entry_cap = 1.0
    pos_cap = 1.0
    peak_cap = 1.0
    last_open = -10 ** 9
    ruined = False

    eq = [1.0]
    pnls = []
    reasons = []
    wins = 0

    for i in range(n):
        if ruined:
            eq.append(cap)
            continue

        s = int(signal[i])

        if pos == 0:
            if s != 0 and (i - last_open) >= min_interval:
                pos = s
                entry_cap = cap * (1.0 - tc - slp)
                pos_cap = entry_cap
                peak_cap = entry_cap
                last_open = i
        else:
            r = float(true_ret[i])
            if pos == 1:
                factor = 1.0 + r
            else:
                factor = 1.0 - r

            if factor <= 1e-12:
                # نابودی پوزیشن در یک نوار (defensive) ⇒ بستن فوری با -۱۰۰٪
                pnls.append(-1.0)
                reasons.append(1)
                cap = 0.0
                pos = 0
                pos_cap = 0.0
                peak_cap = 0.0
                ruined = True
                eq.append(cap)
                continue

            pos_cap = pos_cap * factor

            if pos_cap > peak_cap:
                peak_cap = pos_cap

            pnl_cum = (pos_cap / entry_cap) - 1.0
            peak_pnl = (peak_cap / entry_cap) - 1.0
            draw_from_peak = (peak_cap - pos_cap) / (peak_cap + 1e-12)

            reason = 0
            if pnl_cum <= -stop_loss:
                reason = 1
            elif pnl_cum >= take_profit:
                reason = 2
            elif trailing_stop > 0.0 and peak_pnl > 0.0 and draw_from_peak >= trailing_stop:
                reason = 5
            elif s != 0 and s != pos:
                reason = 3

            if reason:
                final_cap = pos_cap * (1.0 - tc - slp)
                pp = (final_cap / entry_cap) - 1.0 if entry_cap > 0 else 0.0
                pnls.append(pp)
                reasons.append(reason)
                if pp > 0:
                    wins += 1
                cap = final_cap
                pos = 0
                pos_cap = cap
                peak_cap = cap
                if cap <= 1e-12:
                    cap = 0.0
                    pos_cap = 0.0
                    peak_cap = 0.0
                    ruined = True

        eq.append(pos_cap if pos != 0 else cap)

    if pos != 0 and not ruined:
        final_cap = pos_cap * (1.0 - tc - slp)
        pp = (final_cap / entry_cap) - 1.0 if entry_cap > 0 else 0.0
        pnls.append(pp)
        reasons.append(4)
        if pp > 0:
            wins += 1
        cap = final_cap
        eq.append(cap)

    return (
        np.asarray(eq, dtype=np.float64),
        np.asarray(pnls, dtype=np.float64),
        np.asarray(reasons, dtype=np.int64),
        cap,
        wins,
    )


@njit(cache=True)
def _simulate_trades_numba_ohlc(
    true_ret,
    bar_high_ret,
    bar_low_ret,
    signal,
    stop_loss,
    take_profit,
    trailing_stop,
    tc,
    slp,
    min_interval,
):
    """
    شبیه‌ساز OHLC/intrabar با Mark-to-Market — v2.1.

    🔥 اصلاحات v2.1:
      • حذف `fastmath=True` — همان دلیل UNIT 2. واگرایی numba↔numpy در
        شرط `draw_from_peak >= trailing_stop` با fastmath اثبات شده است.

    🔥 حفظ‌شده از v2.0:
      • اگر ضریبِ بدترین‌حرکتِ نوار غیرمثبت شود، پوزیشن بلافاصله با ضرر
        ۱۰۰٪ بسته و حساب ruined می‌شود. بافر eq = n+2.
      • قرارداد OHLC: bar_high_ret[i]=(high[i]-close[i-1])/close[i-1]
        برای پوزیشن long، بدترین=low و بهترین=high (و برای short برعکس).
      • اگر SL و TP هر دو داخل یک نوار بخورند، محافظه‌کارانه SL اول.
    """
    n = true_ret.shape[0]
    cap = 1.0
    pos = 0
    entry_cap = 1.0
    pos_cap = 1.0
    peak_cap = 1.0
    last_open = -1000000
    ruined = 0

    eq = np.empty(n + 2, dtype=np.float64)
    eq[0] = 1.0
    eq_n = 1

    pnls = np.empty(n, dtype=np.float64)
    reasons = np.empty(n, dtype=np.int64)
    n_tr = 0
    wins = 0

    for i in range(n):
        if ruined == 1:
            eq[eq_n] = cap
            eq_n += 1
            continue

        s = signal[i]

        if pos == 0:
            if s != 0 and (i - last_open) >= min_interval:
                pos = s
                entry_cap = cap * (1.0 - tc - slp)
                pos_cap = entry_cap
                peak_cap = entry_cap
                last_open = i
        else:
            if pos == 1:
                f_best = 1.0 + bar_high_ret[i]
                f_worst = 1.0 + bar_low_ret[i]
                f_close = 1.0 + true_ret[i]
            else:
                f_best = 1.0 - bar_low_ret[i]
                f_worst = 1.0 - bar_high_ret[i]
                f_close = 1.0 - true_ret[i]

            if f_worst <= 1e-12 or f_close <= 1e-12:
                pnls[n_tr] = -1.0
                reasons[n_tr] = 1
                n_tr += 1
                cap = 0.0
                pos = 0
                pos_cap = 0.0
                peak_cap = 0.0
                ruined = 1
                eq[eq_n] = cap
                eq_n += 1
                continue

            pos_cap_best = pos_cap * f_best
            pos_cap_worst = pos_cap * f_worst
            pos_cap_close = pos_cap * f_close

            sl_level = entry_cap * (1.0 - stop_loss)
            tp_level = entry_cap * (1.0 + take_profit)

            hit_sl = pos_cap_worst <= sl_level
            hit_tp = pos_cap_best >= tp_level

            reason = 0
            exit_value = pos_cap_close

            if hit_sl and hit_tp:
                reason = 1
                exit_value = sl_level
            elif hit_sl:
                reason = 1
                exit_value = sl_level
            elif hit_tp:
                reason = 2
                exit_value = tp_level
            else:
                if pos_cap_best > peak_cap:
                    peak_cap = pos_cap_best

                peak_pnl = (peak_cap / entry_cap) - 1.0
                draw_from_peak = (peak_cap - pos_cap_worst) / (peak_cap + 1e-12)

                if trailing_stop > 0.0 and peak_pnl > 0.0 and draw_from_peak >= trailing_stop:
                    reason = 5
                    exit_value = peak_cap * (1.0 - trailing_stop)
                elif s != 0 and s != pos:
                    reason = 3
                    exit_value = pos_cap_close

            if reason != 0:
                final_cap = exit_value * (1.0 - tc - slp)
                pp = (final_cap / entry_cap) - 1.0 if entry_cap > 0 else 0.0
                pnls[n_tr] = pp
                reasons[n_tr] = reason
                n_tr += 1
                if pp > 0:
                    wins += 1
                cap = final_cap
                pos = 0
                pos_cap = cap
                peak_cap = cap
                if cap <= 1e-12:
                    cap = 0.0
                    pos_cap = 0.0
                    peak_cap = 0.0
                    ruined = 1
            else:
                pos_cap = pos_cap_close
                if pos_cap > peak_cap:
                    peak_cap = pos_cap

        eq[eq_n] = pos_cap if pos != 0 else cap
        eq_n += 1

    if pos != 0 and ruined == 0:
        final_cap = pos_cap * (1.0 - tc - slp)
        pp = (final_cap / entry_cap) - 1.0 if entry_cap > 0 else 0.0
        pnls[n_tr] = pp
        reasons[n_tr] = 4
        n_tr += 1
        if pp > 0:
            wins += 1
        cap = final_cap
        eq[eq_n] = cap
        eq_n += 1

    return eq[:eq_n], pnls[:n_tr], reasons[:n_tr], cap, wins

def _simulate_trades_numpy_ohlc(
    true_ret,
    bar_high_ret,
    bar_low_ret,
    signal,
    stop_loss,
    take_profit,
    trailing_stop,
    tc,
    slp,
    min_interval,
):
    """نسخهٔ NumPy از `_simulate_trades_numba_ohlc` v2.0."""
    n = len(true_ret)
    cap = 1.0
    pos = 0
    entry_cap = 1.0
    pos_cap = 1.0
    peak_cap = 1.0
    last_open = -10 ** 9
    ruined = False

    eq = [1.0]
    pnls = []
    reasons = []
    wins = 0

    for i in range(n):
        if ruined:
            eq.append(cap)
            continue

        s = int(signal[i])

        if pos == 0:
            if s != 0 and (i - last_open) >= min_interval:
                pos = s
                entry_cap = cap * (1.0 - tc - slp)
                pos_cap = entry_cap
                peak_cap = entry_cap
                last_open = i
        else:
            hi_r = float(bar_high_ret[i])
            lo_r = float(bar_low_ret[i])
            cl_r = float(true_ret[i])

            if pos == 1:
                f_best = 1.0 + hi_r
                f_worst = 1.0 + lo_r
                f_close = 1.0 + cl_r
            else:
                f_best = 1.0 - lo_r
                f_worst = 1.0 - hi_r
                f_close = 1.0 - cl_r

            if f_worst <= 1e-12 or f_close <= 1e-12:
                pnls.append(-1.0)
                reasons.append(1)
                cap = 0.0
                pos = 0
                pos_cap = 0.0
                peak_cap = 0.0
                ruined = True
                eq.append(cap)
                continue

            pos_cap_best = pos_cap * f_best
            pos_cap_worst = pos_cap * f_worst
            pos_cap_close = pos_cap * f_close

            sl_level = entry_cap * (1.0 - stop_loss)
            tp_level = entry_cap * (1.0 + take_profit)

            hit_sl = pos_cap_worst <= sl_level
            hit_tp = pos_cap_best >= tp_level

            reason = 0
            exit_value = pos_cap_close

            if hit_sl and hit_tp:
                reason = 1
                exit_value = sl_level
            elif hit_sl:
                reason = 1
                exit_value = sl_level
            elif hit_tp:
                reason = 2
                exit_value = tp_level
            else:
                if pos_cap_best > peak_cap:
                    peak_cap = pos_cap_best

                peak_pnl = (peak_cap / entry_cap) - 1.0
                draw_from_peak = (peak_cap - pos_cap_worst) / (peak_cap + 1e-12)

                if trailing_stop > 0.0 and peak_pnl > 0.0 and draw_from_peak >= trailing_stop:
                    reason = 5
                    exit_value = peak_cap * (1.0 - trailing_stop)
                elif s != 0 and s != pos:
                    reason = 3
                    exit_value = pos_cap_close

            if reason != 0:
                final_cap = exit_value * (1.0 - tc - slp)
                pp = (final_cap / entry_cap) - 1.0 if entry_cap > 0 else 0.0
                pnls.append(pp)
                reasons.append(reason)
                if pp > 0:
                    wins += 1
                cap = final_cap
                pos = 0
                pos_cap = cap
                peak_cap = cap
                if cap <= 1e-12:
                    cap = 0.0
                    pos_cap = 0.0
                    peak_cap = 0.0
                    ruined = True
            else:
                pos_cap = pos_cap_close
                if pos_cap > peak_cap:
                    peak_cap = pos_cap

        eq.append(pos_cap if pos != 0 else cap)

    if pos != 0 and not ruined:
        final_cap = pos_cap * (1.0 - tc - slp)
        pp = (final_cap / entry_cap) - 1.0 if entry_cap > 0 else 0.0
        pnls.append(pp)
        reasons.append(4)
        if pp > 0:
            wins += 1
        cap = final_cap
        eq.append(cap)

    return (
        np.asarray(eq, dtype=np.float64),
        np.asarray(pnls, dtype=np.float64),
        np.asarray(reasons, dtype=np.int64),
        cap,
        wins,
    )


def _simulate_linear_sigma_numpy(
    true_ret,
    signal,
    stop_units,
    take_units,
):
    """
    GLOBAL FUNCTION (NEW) — شبیه‌ساز خطی در فضای σ (fallback).

    چرا لازم است:
        وقتی scaler قیمت (mean/std) در دسترس نیست، دادهٔ z-scored را نمی‌توان
        به بازدهٔ واقعی تبدیل کرد. شبیه‌سازیِ ضربی روی مقادیر σ (که |r|>1
        دارند) به‌صورت ریاضی ناپایدار است (نابودی پوزیشن، کفِ کاذب، Sharpeٔ
        منفجرشده). این شبیه‌ساز PnL را **جمعی** در واحد σ می‌سنجد:
            cum += pos * r
        بنابراین هیچ نابودی/کفی وجود ندارد و اعداد، خوانش صادقانه‌ای از
        کیفیت سیگنال‌اند (نه پول واقعی).

    خروجی:
        (eq, pnls, reasons, cum_total, wins, strat)
        eq   : بازدهٔ تجمعی استراتژی در واحد σ (طول n+1، از 0).
        strat: سهم هر نوار در واحد σ (0 در نوارهای بدون پوزیشن).
    """
    n = len(true_ret)
    eq = np.zeros(n + 1, dtype=np.float64)
    strat = np.zeros(n, dtype=np.float64)
    pnls = []
    reasons = []
    pos = 0
    cum = 0.0
    peak = 0.0
    wins = 0

    for i in range(n):
        s = int(signal[i])
        if pos == 0:
            if s != 0:
                pos = s
                cum = 0.0
                peak = 0.0
            eq[i + 1] = eq[i]
            continue

        r = float(true_ret[i])
        bar = pos * r
        cum += bar
        strat[i] = bar
        eq[i + 1] = eq[i] + bar

        if cum > peak:
            peak = cum

        reason = 0
        if cum <= -stop_units:
            reason = 1
        elif cum >= take_units:
            reason = 2
        elif s != 0 and s != pos:
            reason = 3

        if reason != 0:
            pnls.append(cum)
            reasons.append(reason)
            if cum > 0:
                wins += 1
            pos = 0
            cum = 0.0
            peak = 0.0

    if pos != 0:
        pnls.append(cum)
        reasons.append(4)
        if cum > 0:
            wins += 1

    return (
        eq,
        np.asarray(pnls, dtype=np.float64),
        np.asarray(reasons, dtype=np.int64),
        float(eq[-1]) if n > 0 else 0.0,
        wins,
        strat,
    )


    
def calculate_financial_metrics_with_stop_loss(
    y_true,
    y_pred,
    price_mean: float = 0.0,
    price_std: float = 0.01,
    stop_loss: float = 0.015,
    take_profit: float = 0.03,
    trailing_stop: float = 0.0,
    transaction_cost: float = 0.0005,
    slippage: float = 0.0002,
    already_denormalized: bool = False,
    return_full_details: bool = False,
    is_normalized_data: bool = True,
    min_signal_threshold: float = 0.0005,
    timeframe: str = "1H",
    signal_override: Optional[np.ndarray] = None,
    auto_threshold: bool = True,
    auto_risk_levels: bool = True,
    risk_sigma_stop: float = 2.5,
    risk_sigma_target: float = 4.0,
    bar_high_ret: Optional[np.ndarray] = None,
    bar_low_ret: Optional[np.ndarray] = None,
    return_space: str = "real",
) -> Dict:
    """
    CALCULATE_FINANCIAL_METRICS_WITH_STOP_LOSS v9.0
    ==================================================
    🔥 v9.0 (نسبت به v8.1):

      (1) SIGNAL_OVERRIDE VALIDATION:
          - طول بررسی می‌شود: اگر با yt بعد از mask-filter یا قبل از آن
            منطبق باشد، به‌درستی اعمال می‌شود؛ در غیر این صورت
            WARNING + override نادیده گرفته می‌شود.
          - NaN/Inf در override به 0.0، سپس clip به {-1, 0, +1}.
          - metadata کامل از منبع override در خروجی
            (`signal_override_meta`).

      (2) NO-FALLBACK CONTRACT (حفظ از v8.1 با تقویت):
          - وقتی signal_override معتبر داده شده و n_signals == 0،
            **هیچ fallback به رگرسیون اعمال نمی‌شود**. این یک نتیجهٔ
            معتبر است: سیگنال خواستهٔ شما «هیچ معامله‌ای نکن» است
            (شاید به‌خاطر فلتر cost/σ در DirectionSignalBuilder).
          - اما اگر signal_override داده نشده باشد و n_signals < 10،
            fallback رگرسیون اعمال می‌شود (v8.1 حفظ شده).
          - لاگ INFO صریح در حالت override + صفر معامله.

      (3) NO BEHAVioral CHANGE in other paths:
          - sigma_linear fallback، OHLC، numba/numpy، Sharpe computation،
            warning ها و schema خروجی همه دست‌نخورده.
          - فقط یک کلید جدید `signal_override_meta` به خروجی اضافه شده.
    """
    phase = "FIN_METRICS v9.0"

    # ═══════════════════════════════════════════════════════════════════
    # ۱) نرمال‌سازی ورودی‌ها
    # ═══════════════════════════════════════════════════════════════════
    yt = np.asarray(y_true, dtype=np.float64).reshape(-1)
    yp = np.asarray(y_pred, dtype=np.float64).reshape(-1)

    m = np.isfinite(yt) & np.isfinite(yp)
    yt, yp = yt[m], yp[m]

    # ── 🔥 v9.0: signal_override validation ──
    so = None
    override_meta: Dict[str, Any] = {
        "provided": signal_override is not None,
        "reason": "not_provided" if signal_override is None else "unknown",
    }

    if signal_override is not None:
        so_raw = np.asarray(signal_override).reshape(-1)
        raw_len = int(so_raw.size)
        n_finite = int(np.isfinite(so_raw).sum())
        n_nonfinite = int(raw_len - n_finite)

        # sanitize: NaN/Inf → 0, clip → {-1, 0, +1}
        so_raw = np.where(np.isfinite(so_raw), so_raw, 0.0)
        so_raw = np.clip(so_raw, -1.0, 1.0)
        so_raw = np.sign(so_raw).astype(np.int64)

        if raw_len == int(m.size):
            # override قبل از NaN-filter ساخته شده
            so = so_raw[m]
            override_meta = {
                "provided": True,
                "reason": "masked_to_alignment",
                "raw_len": raw_len,
                "post_mask_len": int(so.size),
                "n_nonfinite": n_nonfinite,
            }
        elif raw_len == int(yt.size):
            # override بعد از NaN-filter ساخته شده
            so = so_raw
            override_meta = {
                "provided": True,
                "reason": "pre_aligned",
                "raw_len": raw_len,
                "n_nonfinite": n_nonfinite,
            }
        else:
            # طول نامطابق — قابل استفاده نیست
            override_meta = {
                "provided": True,
                "reason": "length_mismatch",
                "raw_len": raw_len,
                "yt_prefilter_len": int(m.size),
                "yt_postfilter_len": int(yt.size),
                "n_nonfinite": n_nonfinite,
            }
            so = None
            logger.warning(
                f"[{phase}] signal_override rejected: length {raw_len} "
                f"≠ yt_prefilter {int(m.size)} and ≠ yt_postfilter "
                f"{int(yt.size)}. Falling back to regression signal."
            )

    if len(yt) < 50:
        out = _empty_financial_metrics(True)
        out["n_samples"] = int(len(yt))
        out["signal_override_meta"] = override_meta
        logger.warning(
            f"[{phase}] insufficient samples (n={len(yt)}<50) → empty metrics"
        )
        return out

    # ═══════════════════════════════════════════════════════════════════
    # ۲) denormalize (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    if not already_denormalized:
        if not (0 < price_std <= 0.5):
            price_std = 0.01
        yt = yt * price_std + price_mean
        yp = yp * price_std + price_mean

    rs = str(return_space or "real").strip().lower()
    if rs not in ("real", "sigma"):
        logger.warning(
            f"[{phase}] return_space={return_space!r} invalid ⇒ 'real'"
        )
        rs = "real"

    # ═══════════════════════════════════════════════════════════════════
    # ۳) Clipping (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    pre_clip_std = float(np.std(yt))
    if not np.isfinite(pre_clip_std) or pre_clip_std < 1e-9:
        pre_clip_std = 0.01
    if rs == "real":
        clip_limit = float(np.clip(20.0 * pre_clip_std, 0.02, 0.5))
    else:
        clip_limit = float(max(20.0 * pre_clip_std, 5.0))
    yt = np.clip(yt, -clip_limit, clip_limit)
    yp = np.clip(yp, -clip_limit, clip_limit)
    sigma_bar = float(np.std(yt))

    logger.debug(
        f"[{phase}] clipping: pre_std={pre_clip_std:.6g}, "
        f"clip_limit={clip_limit:.6g}, post_std={sigma_bar:.6g}, space={rs}"
    )

    # ═══════════════════════════════════════════════════════════════════
    # ۴) سطوح ریسک (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    sl_used = float(stop_loss)
    tp_used = float(take_profit)
    ts_used = float(max(0.0, trailing_stop))
    tc_f = float(transaction_cost)
    slp_f = float(slippage)
    round_trip_cost = 2.0 * (tc_f + slp_f)
    rescaled = False

    if rs == "sigma":
        sl_used = float(max(0.25, float(risk_sigma_stop)))
        tp_used = float(max(0.5, float(risk_sigma_target)))
        ts_used = 0.0
        tc_f = 0.0
        slp_f = 0.0
        rescaled = True
        logger.warning(
            f"[{phase}] SIGMA-LINEAR fallback: SL={sl_used:.2f}σ, "
            f"TP={tp_used:.2f}σ, trailing=OFF, costs=0 — "
            f"metrics are in σ units, not real money."
        )
    else:
        if auto_risk_levels and sigma_bar > 1e-9:
            sl_sigma = sl_used / sigma_bar
            tp_sigma = tp_used / sigma_bar
            needs_rescale = (
                (sl_used <= 0.0)
                or (tp_used <= 0.0)
                or (sl_sigma > 4.0)
                or (tp_sigma > 6.0)
                or (sl_sigma < 0.5)
                or (sl_used >= 0.95)
            )
            if needs_rescale:
                new_sl = float(max(
                    risk_sigma_stop * sigma_bar,
                    4.0 * round_trip_cost,
                    1e-6,
                ))
                new_tp = float(max(
                    risk_sigma_target * sigma_bar,
                    1.5 * new_sl,
                    2e-6,
                ))
                logger.warning(
                    f"[{phase}] risk levels rescaled: "
                    f"SL {sl_used:.6g}→{new_sl:.6g} "
                    f"({new_sl / sigma_bar:.2f}σ), "
                    f"TP {tp_used:.6g}→{new_tp:.6g} "
                    f"({new_tp / sigma_bar:.2f}σ), "
                    f"RR={new_tp / max(new_sl, 1e-12):.2f}"
                )
                sl_used, tp_used = new_sl, new_tp
                rescaled = True

        if sl_used >= 0.95:
            forced = (
                float(max(2.5 * sigma_bar, 1e-6))
                if sigma_bar > 1e-9 else 0.02
            )
            logger.error(
                f"[{phase}] 🚨 SL={sl_used:.6g} ≥ 0.95 "
                f"(unreachable in multiplicative simulator) ⇒ "
                f"forced to {forced:.6g} (2.5σ)"
            )
            sl_used = forced
            rescaled = True
        if tp_used <= 0.0:
            tp_used = float(max(1.5 * sl_used, 2e-6))
            rescaled = True

    # ═══════════════════════════════════════════════════════════════════
    # ۵) تولید سیگنال — 🔥 v9.0: EXPLICIT OVERRIDE, NO SILENT FALLBACK
    # ═══════════════════════════════════════════════════════════════════
    explicit_signal_provided = (
        so is not None and len(so) == len(yt)
    )

    if explicit_signal_provided:
        sig = np.asarray(so, dtype=np.int64)
        used_threshold = 0.0
        signal_source = "direction_head"
    else:
        thr = float(min_signal_threshold)
        if auto_threshold:
            abs_yp = np.abs(yp)
            pred_std = float(np.std(yp))
            q60 = float(np.quantile(abs_yp, 0.60)) if abs_yp.size else 0.0
            candidate = max(0.15 * pred_std, q60)
            if not np.isfinite(candidate) or candidate <= 0:
                candidate = max(1e-6, 0.10 * sigma_bar)
            cap = (
                float(np.quantile(abs_yp, 0.90))
                if abs_yp.size else candidate
            )
            thr = float(min(max(candidate, 1e-7), max(cap, 1e-7)))
        used_threshold = thr
        sig = np.zeros(len(yp), dtype=np.int64)
        sig[yp > thr] = 1
        sig[yp < -thr] = -1
        signal_source = "regression_adaptive"

    n_signals = int(np.count_nonzero(sig))

    # ── 🔥 v9.0: fallback فقط در نبود override ──
    if (not explicit_signal_provided) and n_signals < 10:
        abs_yp = np.abs(yp)
        fallback_thr = (
            float(np.quantile(abs_yp, 0.50)) if abs_yp.size else 0.0
        )
        sig = np.zeros(len(yp), dtype=np.int64)
        sig[yp > fallback_thr] = 1
        sig[yp < -fallback_thr] = -1
        used_threshold = fallback_thr
        signal_source = signal_source + "+q50_fallback"
        n_signals = int(np.count_nonzero(sig))
        logger.warning(
            f"[{phase}] signal fallback applied (no override): "
            f"n_signals={n_signals}, threshold={fallback_thr:.6g}"
        )

    # ── 🔥 v9.0: لاگ INFO صریح برای override + صفر معامله ──
    if explicit_signal_provided and n_signals == 0:
        logger.info(
            f"[{phase}] ℹ️ signal_override provided but all-zero "
            f"(N={len(sig)}, meta={override_meta}). "
            f"این نتیجهٔ معتبر است — DirectionSignalBuilder احتمالاً "
            f"فلتر cost/σ را رد کرده. هیچ fallback اعمال نمی‌شود."
        )

    # ═══════════════════════════════════════════════════════════════════
    # ۶) شبیه‌سازی (بدون تغییر ساختاری)
    # ═══════════════════════════════════════════════════════════════════
    strat = None
    if rs == "sigma":
        sim_mode = "sigma_linear_fallback"
        eq, pnls, reasons, cap_final, wins, strat = _simulate_linear_sigma_numpy(
            yt, sig, sl_used, tp_used
        )
    else:
        use_ohlc = False
        hi_arr = None
        lo_arr = None
        if bar_high_ret is not None and bar_low_ret is not None:
            hi_arr = np.asarray(bar_high_ret, dtype=np.float64).reshape(-1)
            lo_arr = np.asarray(bar_low_ret, dtype=np.float64).reshape(-1)
            if hi_arr.shape[0] == m.shape[0]:
                hi_arr = hi_arr[m]
            if lo_arr.shape[0] == m.shape[0]:
                lo_arr = lo_arr[m]
            if hi_arr.shape[0] == len(yt) and lo_arr.shape[0] == len(yt):
                hi_arr = np.clip(hi_arr, -clip_limit, clip_limit)
                lo_arr = np.clip(lo_arr, -clip_limit, clip_limit)
                use_ohlc = True
            else:
                logger.warning(
                    f"[{phase}] OHLC arrays length mismatch "
                    f"(hi={hi_arr.shape[0]}, lo={lo_arr.shape[0]}, "
                    f"n={len(yt)}) — falling back to close-only"
                )

        if use_ohlc:
            signal_source = signal_source + "+ohlc_intrabar"
            sim_mode = "ohlc_intrabar"
            sim_ohlc = (
                _simulate_trades_numba_ohlc
                if HAS_NUMBA else _simulate_trades_numpy_ohlc
            )
            try:
                eq, pnls, reasons, cap_final, wins = sim_ohlc(
                    yt.astype(np.float64),
                    hi_arr.astype(np.float64),
                    lo_arr.astype(np.float64),
                    sig,
                    float(sl_used), float(tp_used), float(ts_used),
                    tc_f, slp_f, 1,
                )
            except Exception as e:
                logger.warning(
                    f"[{phase}] OHLC numba failed ({e}) — numpy fallback"
                )
                eq, pnls, reasons, cap_final, wins = \
                    _simulate_trades_numpy_ohlc(
                        yt, hi_arr, lo_arr, sig,
                        sl_used, tp_used, ts_used,
                        tc_f, slp_f, 1,
                    )
        else:
            sim_mode = "close_only"
            sim = (
                _simulate_trades_numba
                if HAS_NUMBA else _simulate_trades_numpy
            )
            try:
                eq, pnls, reasons, cap_final, wins = sim(
                    yt.astype(np.float64), sig,
                    float(sl_used), float(tp_used), float(ts_used),
                    tc_f, slp_f, 1,
                )
            except Exception as e:
                logger.warning(
                    f"[{phase}] close-only numba failed ({e}) — numpy fallback"
                )
                eq, pnls, reasons, cap_final, wins = \
                    _simulate_trades_numpy(
                        yt, sig, sl_used, tp_used, ts_used,
                        tc_f, slp_f, 1,
                    )

    eq = np.asarray(eq, dtype=np.float64)
    pnls = np.asarray(pnls, dtype=np.float64)
    reasons = np.asarray(reasons, dtype=np.int64)
    AF = _annual_factor_for(timeframe)

    # ═══════════════════════════════════════════════════════════════════
    # ۷) Exit reason rates (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    n_tr = len(pnls)
    sl_rate = float((reasons == 1).mean()) if n_tr else 0.0
    tp_rate = float((reasons == 2).mean()) if n_tr else 0.0
    flip_rate = float((reasons == 3).mean()) if n_tr else 0.0
    ts_rate = float((reasons == 5).mean()) if n_tr else 0.0

    ruined = bool(rs == "real" and float(cap_final) <= 1e-12 and n_tr > 0)

    # ═══════════════════════════════════════════════════════════════════
    # ۸) Sharpe واقعی — بدون clip، با محافظ عددی (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    if n_tr >= 3:
        mu_pnls = float(np.mean(pnls))
        sd_pnls = float(np.std(pnls))
        if np.isfinite(mu_pnls) and np.isfinite(sd_pnls) and sd_pnls > 1e-9:
            sh_trade_raw = float((mu_pnls / sd_pnls) * AF)
        else:
            sh_trade_raw = 0.0
    else:
        sh_trade_raw = 0.0

    if rs == "sigma":
        s_stream = np.asarray(strat, dtype=np.float64)
        if s_stream.size > 10:
            mu_s = float(np.mean(s_stream))
            sd_s = float(np.std(s_stream))
            if np.isfinite(mu_s) and np.isfinite(sd_s) and sd_s > 1e-12:
                sh_equity_raw = float((mu_s / sd_s) * AF)
            else:
                sh_equity_raw = 0.0
        else:
            sh_equity_raw = 0.0
        sharpe = sh_equity_raw

        rm = np.maximum.accumulate(eq)
        dd_sigma = rm - eq
        mdd = float(dd_sigma.max()) if len(dd_sigma) else 0.0
        tot_ret = float(eq[-1]) if len(eq) else 0.0
    else:
        eq_prev = eq[:-1]
        eq_safe = np.maximum(eq_prev, 1e-9)
        eq_diff = (eq[1:] - eq_prev) / eq_safe
        if len(eq_diff) > 10:
            mu_eq = float(np.mean(eq_diff))
            sd_eq = float(np.std(eq_diff))
            if np.isfinite(mu_eq) and np.isfinite(sd_eq) and sd_eq > 1e-12:
                sh_equity_raw = float((mu_eq / sd_eq) * AF)
            else:
                sh_equity_raw = 0.0
        else:
            sh_equity_raw = 0.0
        sharpe = sh_equity_raw

        rm = np.maximum.accumulate(eq)
        dd = (eq - rm) / (rm + 1e-10)
        mdd = float(abs(dd.min())) if len(dd) else 0.0
        mdd = float(min(mdd, 1.0))
        tot_ret = (
            float(eq[-1] / eq[0] - 1)
            if len(eq) and eq[0] > 0 else 0.0
        )

    # ═══════════════════════════════════════════════════════════════════
    # ۹) Suspect-sharpe detection (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    sharpe_suspect = bool(
        (not np.isfinite(sh_equity_raw))
        or (not np.isfinite(sh_trade_raw))
        or (abs(sh_equity_raw) > SHARPE_BREAKDOWN_ABS)
        or (abs(sh_trade_raw) > SHARPE_BREAKDOWN_ABS)
    )
    sharpe_warn = bool(abs(sh_equity_raw) > 8.0)

    if sharpe_suspect:
        logger.error(
            f"[{phase}] 🚨 SUSPECT SHARPE: raw_equity={sh_equity_raw:.4f}, "
            f"raw_trade={sh_trade_raw:.4f} "
            f"(|raw|>{SHARPE_BREAKDOWN_ABS:.0f}) — "
            f"simulator output is untrustworthy. Value reported as-is."
        )
    elif sharpe_warn:
        logger.warning(
            f"[{phase}] ⚠️ HIGH SHARPE: raw_equity={sh_equity_raw:.4f}, "
            f"raw_trade={sh_trade_raw:.4f} "
            f"(|raw|>8) — verify no leakage or simulator artifact."
        )

    # ═══════════════════════════════════════════════════════════════════
    # ۱۰) Sortino, win-rate, PF (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    neg = pnls[pnls < 0] if n_tr else np.array([])
    if n_tr >= 3 and len(neg) >= 2:
        sd_neg = float(np.std(neg))
        mu_neg = float(np.mean(pnls))
        if np.isfinite(sd_neg) and sd_neg > 1e-9 and np.isfinite(mu_neg):
            sortino = float((mu_neg / sd_neg) * AF)
        else:
            sortino = 0.0
    else:
        sortino = 0.0

    wr = float(wins / n_tr) if n_tr else 0.0
    gp = float(pnls[pnls > 0].sum()) if n_tr else 0.0
    gl = float(abs(pnls[pnls <= 0].sum())) if n_tr else 0.0
    pf = float(gp / (gl + 1e-8)) if n_tr else 0.0

    # ═══════════════════════════════════════════════════════════════════
    # ۱۱) Sanity warnings (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    if wr > 0.90 and n_tr >= 10:
        logger.warning(
            f"[{phase}] ⚠️ HIGH WIN RATE: {wr:.2%} over {n_tr} trades "
            f"(>90%) — check for leakage or trivially predictable pattern."
        )
    if pf > 10.0 and n_tr >= 10:
        logger.warning(
            f"[{phase}] ⚠️ HIGH PROFIT FACTOR: {pf:.2f} (>10) — "
            f"check for leakage or exceptional regime."
        )
    if mdd > 0.90:
        logger.warning(
            f"[{phase}] ⚠️ HIGH MAX DRAWDOWN: {mdd:.2%} (>90%) — "
            f"simulator may be compounding losses unrealistically."
        )
    if tot_ret < -0.99 and not ruined:
        logger.warning(
            f"[{phase}] ⚠️ TOTAL RETURN near −100%: {tot_ret:.2%} — "
            f"check for signal inversion or extreme costs."
        )
    if 0 < n_tr < 5:
        logger.warning(
            f"[{phase}] ⚠️ VERY FEW TRADES: n={n_tr} (<5) — "
            f"metrics unreliable."
        )
    if np.isfinite(cap_final) and cap_final <= 0.0:
        logger.warning(
            f"[{phase}] ⚠️ ACCOUNT CAPITAL <= 0: cap_final={cap_final:.6g} — "
            f"position was wiped."
        )

    # ═══════════════════════════════════════════════════════════════════
    # ۱۲) annualized volatility (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    if rs == "sigma":
        if strat is not None and len(strat) >= 5:
            sd_strat = float(np.std(np.asarray(strat, dtype=np.float64)))
            annual_vol = float(sd_strat * AF) if np.isfinite(sd_strat) else 0.0
        else:
            annual_vol = 0.0
    else:
        if n_tr >= 5:
            sd_p = float(np.std(pnls))
            annual_vol = float(sd_p * AF) if np.isfinite(sd_p) else 0.0
        else:
            annual_vol = 0.0

    # ═══════════════════════════════════════════════════════════════════
    # ۱۳) metrics_reliable (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    if rs == "real":
        metrics_reliable = bool(
            n_tr >= 30
            and sl_rate < 0.999
            and not sharpe_suspect
            and not ruined
        )
    else:
        metrics_reliable = bool(n_tr >= 30 and not sharpe_suspect)

    # ═══════════════════════════════════════════════════════════════════
    # ۱۴) خروجی نهایی — v9.0: +signal_override_meta
    # ═══════════════════════════════════════════════════════════════════
    out = {
        "sharpe_ratio": float(sharpe),
        "sharpe_trade_based": float(sh_trade_raw),
        "sharpe_equity_based": float(sh_equity_raw),
        "sharpe_equity_raw_sim": float(sh_equity_raw),
        "sharpe_trade_raw_sim": float(sh_trade_raw),
        "sharpe_suspect": bool(sharpe_suspect),
        "sharpe_hit_clip_cap": bool(sharpe_suspect),

        "sortino_ratio": float(sortino),
        "total_return": float(tot_ret),
        "win_rate": float(wr),
        "profit_factor": float(pf),
        "max_drawdown": float(mdd),
        "max_drawdown_duration": 0,
        "calmar_ratio": (
            float(tot_ret / (mdd + 1e-8)) if mdd > 0.01 else 0.0
        ),
        "recovery_factor": (
            float(tot_ret / (mdd + 1e-8)) if mdd > 0.01 else 0.0
        ),
        "expectancy": float(np.mean(pnls)) if n_tr else 0.0,
        "total_trades": int(n_tr),
        "avg_win": (
            float(pnls[pnls > 0].mean())
            if n_tr and (pnls > 0).any() else 0.0
        ),
        "avg_loss": (
            float(abs(pnls[pnls <= 0].mean()))
            if n_tr and (pnls <= 0).any() else 0.0
        ),
        "max_consecutive_losses": 0,
        "stop_loss_rate": float(sl_rate),
        "take_profit_rate": float(tp_rate),
        "signal_flip_rate": float(flip_rate),
        "trailing_stop_rate": float(ts_rate),
        "equity_final": float(eq[-1]) if len(eq) else 1.0,
        "equity_peak": float(eq.max()) if len(eq) else 1.0,
        "equity_trough": float(eq.min()) if len(eq) else 1.0,
        "annual_volatility": float(annual_vol),
        "n_samples": int(len(yt)),
        "annualization_factor": float(AF),
        "signal_source": str(signal_source),
        "signal_threshold_used": float(used_threshold),
        "n_signals": int(n_signals),
        "bar_return_sigma": float(sigma_bar),
        "stop_loss_used": float(sl_used),
        "take_profit_used": float(tp_used),
        "trailing_stop_used": float(ts_used),
        "stop_loss_sigma": (
            float(sl_used / sigma_bar) if sigma_bar > 1e-9 else 0.0
        ),
        "take_profit_sigma": (
            float(tp_used / sigma_bar) if sigma_bar > 1e-9 else 0.0
        ),
        "reward_risk_ratio": float(tp_used / max(sl_used, 1e-12)),
        "risk_levels_rescaled": bool(rescaled),
        "metrics_reliable": bool(metrics_reliable),
        "simulator_mode": str(sim_mode),
        "directional_accuracy": 0.0,
        "model_collapsed": False,

        "return_space": rs,
        "metrics_unit": ("sigma" if rs == "sigma" else "percent"),
        "ruined": bool(ruined),
        "clip_limit_used": float(clip_limit),

        # 🔥 v9.0 NEW
        "signal_override_meta": dict(override_meta),
    }

    if return_full_details:
        out["trades"] = [
            {"pnl_percent": float(v), "exit_reason": int(r)}
            for v, r in zip(pnls.tolist(), reasons.tolist())
        ]
        out["equity_curve"] = eq.tolist()

    out["signal_source_explicit"] = bool(explicit_signal_provided)
    out["metrics_reliable"] = bool(
        metrics_reliable
        and (n_tr >= 30)
        and (explicit_signal_provided or n_signals >= 10)
    )

    logger.info(
        f"[{phase}] done | space={rs} | mode={sim_mode} | "
        f"trades={n_tr} | Sharpe={sharpe:.4f} "
        f"(raw_eq={sh_equity_raw:.4f}, raw_tr={sh_trade_raw:.4f}) | "
        f"WR={wr:.2%} | PF={pf:.3f} | MaxDD={mdd:.2%} | "
        f"TotalRet={tot_ret:.2%} | suspect={sharpe_suspect} | "
        f"override={override_meta.get('reason')}"
    )

    return out
    
def _extract_return_scaler(scaler_params) -> Tuple[Optional[float], Optional[float]]:
    """
    GLOBAL FUNCTION (NEW) — استخراج امن (mean, std) تارگت price_return.

    برخلاف `get_scaler_params` که در نبودِ پروفایل، مقدار جعلی
    (0.0, 0.01) برمی‌گرداند، این تابع فقط وقتی مقدار برمی‌گرداند که
    پروفایلِ regression معتبر واقعاً موجود باشد؛ وگرنه (None, None).

    خروجی: (mean, std) یا (None, None)
    """
    if not isinstance(scaler_params, dict):
        return None, None

    candidates = ['price_return'] + list(TARGET_ALIASES.get('price_return', []))

    for key in candidates:
        info = scaler_params.get(key)
        if not isinstance(info, dict):
            continue
        tt = str(info.get('target_type', '')).lower()
        if tt not in ('regression', 'reg'):
            continue
        m_raw, s_raw = info.get('mean'), info.get('std')
        try:
            m_f, s_f = float(m_raw), float(s_raw)
        except (TypeError, ValueError):
            continue
        if np.isfinite(m_f) and np.isfinite(s_f) and 1e-12 < s_f <= 0.5:
            return m_f, s_f

    # ساختار feature_profiles (خروجی load_scalers_from_path)
    fp = scaler_params.get('feature_profiles')
    if isinstance(fp, dict):
        prof = fp.get('price_return')
        if isinstance(prof, dict):
            tt = str(prof.get('target_type', '')).lower()
            if tt in ('regression', 'reg'):
                pr = prof.get('params', {}) or {}
                m_raw, s_raw = pr.get('mean'), pr.get('std')
                try:
                    m_f, s_f = float(m_raw), float(s_raw)
                except (TypeError, ValueError):
                    return None, None
                if np.isfinite(m_f) and np.isfinite(s_f) and 1e-12 < s_f <= 0.5:
                    return m_f, s_f

    return None, None


def _extract_base_model(model):
    m = model
    for attr in ("base_model", "model", "inner_model"):
        try:
            v = getattr(m, attr, None)
            if v is not None and hasattr(v, "predict"): return v
        except Exception: pass
    return m

def _safe_symbol_timeframe() -> Tuple[str, str]:
    try:
        from core.global_method import get_active_symbol_timeframe
        s, t = get_active_symbol_timeframe()
        if s and t: return str(s), str(t)
    except Exception: pass
    return "BTCUSD", "30M"

def _safe_fold(default: int = 5) -> int:
    try:
        from main import sum_folds as f
        return int(f)
    except Exception: return default

def _sanitize_path_part(s: str) -> str:
    return re.sub(r"[^A-Za-z0-9_.\-]+", "_", str(s))[:64]


def _pearson_corr(a, b):
    a = np.asarray(a, dtype=np.float64).reshape(-1)
    b = np.asarray(b, dtype=np.float64).reshape(-1)
    n = int(min(a.size, b.size))
    if n < 3:
        return None
    a, b = a[:n] - np.mean(a[:n]), b[:n] - np.mean(b[:n])
    denom = float(np.sqrt((a ** 2).sum() * (b ** 2).sum()))
    if denom <= 1e-12:
        return None
    return float((a * b).sum() / denom)


def _spearman_corr(a, b):
    a = np.asarray(a, dtype=np.float64).reshape(-1)
    b = np.asarray(b, dtype=np.float64).reshape(-1)
    n = int(min(a.size, b.size))
    if n < 3:
        return None

    def _rank(v):
        order = np.argsort(v, kind='mergesort')
        ranks = np.empty(v.size, dtype=np.float64)
        ranks[order] = np.arange(v.size, dtype=np.float64)
        _, inv, counts = np.unique(v, return_inverse=True, return_counts=True)
        if np.any(counts > 1):
            for gi in np.where(counts > 1)[0]:
                m_ = inv == gi
                ranks[m_] = ranks[m_].mean()
        return ranks

    return _pearson_corr(_rank(a[:n]), _rank(b[:n]))


def resolve_head_outputs(model, raw_preds, task_order=None):
    """
    resolve_head_outputs v3.0 — dict/list/array safe.

    سه حالت خروجی مدل:
      1) dict: {name: tensor}  → نام‌ها حفظ می‌شوند (پسوند _logits حذف)
      2) list/tuple: به ترتیب model.output_names
      3) tensor تکی: به task_order[0]

    هرگز استثنا نمی‌دهد؛ در بدترین حالت dict خالی.
    """
    if raw_preds is None:
        return {}

    def _strip(name: str) -> str:
        s = str(name)
        if s.endswith("_logits"):
            s = s[:-7]
        if ":" in s:
            s = s.split(":")[0]
        if "/" in s:
            s = s.split("/")[0]
        return s.strip()

    try:
        # ── Case 1: dict ──
        if isinstance(raw_preds, dict):
            out = {}
            for k, v in raw_preds.items():
                if v is None:
                    continue
                arr = v.numpy() if hasattr(v, "numpy") else np.asarray(v)
                out[_strip(k)] = arr
            return out

        # ── Case 2: list/tuple ──
        if isinstance(raw_preds, (list, tuple)):
            names = None
            for holder in (
                model,
                getattr(model, "base_model", None) if model is not None else None,
            ):
                if holder is None:
                    continue
                n = getattr(holder, "output_names", None)
                if n and len(n) == len(raw_preds):
                    names = [_strip(x) for x in n]
                    break
                outs = getattr(holder, "outputs", None)
                if outs and len(outs) == len(raw_preds):
                    tmp = []
                    ok = True
                    for t in outs:
                        layer = getattr(
                            getattr(t, "_keras_history", None), "layer", None
                        )
                        nm = getattr(layer, "name", None)
                        if not nm:
                            ok = False
                            break
                        tmp.append(_strip(nm))
                    if ok:
                        names = tmp
                        break
            if names is None:
                fallback = (
                    list(task_order)
                    if task_order
                    else list(OUTPUT_ORDER_FALLBACK)
                )
                names = (fallback + [f"out_{i}" for i in range(len(raw_preds))])[
                    : len(raw_preds)
                ]
            return {
                names[i]: np.asarray(v)
                for i, v in enumerate(raw_preds)
                if v is not None
            }

        # ── Case 3: single tensor ──
        arr = raw_preds.numpy() if hasattr(raw_preds, "numpy") else np.asarray(raw_preds)
        key = (task_order[0] if task_order else "price_return")
        return {key: arr}

    except Exception as e:
        logger.warning(f"[resolve_head_outputs] failed: {e}")
        return {}
        

def evaluate_model_financial_sync(
    model=None,
    X=None,
    y=None,
    X_test=None,
    y_test_dict=None,
    task_names=None,
    output_order=None,
    risk_levels=None,
    train_reference_std=None,
    bars_per_year: float = 252.0 * 48.0,
    batch_size: int = 1024,
    allow_auto_rescale: bool = False,
    scale_mismatch_tolerance: float = 50.0,
    sl_sigma: float = 2.5,
    tp_sigma: float = 4.0,
    max_eval_samples: int = 200000,
    verbose: bool = True,
    data_is_normalized: bool = True,
    scaler_params: Optional[Dict] = None,
    replacement_predictions: Optional[Dict[str, np.ndarray]] = None,
    **kwargs,
):
    """
    GLOBAL FUNCTION — ارزیابی مالی سنکرون با شبیه‌سازی معاملات واقعی (v11.0).

    ╔══════════════════════════════════════════════════════════════════════════╗
    ║  v11.0 — REAL-SPACE SIMULATION FIX (RCA از لاگ اجرای 2026-10-06)         ║
    ║  ========================================================================║
    ║  🔥 باگ اثبات‌شده:                                                      ║
    ║    y/p هر دو z-scored بودند (σ≈0.85) اما با already_denormalized=True    ║
    ║    مستقیم به شبیه‌سازِ ضربی داده می‌شدند و SL/TP بر حسب σ ساخته می‌شد     ║
    ║    (SL=-2.129 یعنی −213٪!). نتیجه در لاگ:                                ║
    ║      Sharpe=10.0000 (کلاهک)، MaxDD=95٪، TotalRet=−100٪، PF≈4.2           ║
    ║      ⇒ «IMPOSSIBLE SHARPE > 8 (leakage)» کاذب روی همهٔ مدل‌ها.           ║
    ║                                                                          ║
    ║  🔥 اصلاح v11.0:                                                         ║
    ║    • با scaler موجود (mean/std قیمت) y و p به بازدهٔ واقعی denormalize     ║
    ║      می‌شوند؛ سطوح ریسک در فضای واقعی ساخته می‌شوند؛ شبیه‌سازی ضربی      ║
    ║      معنا پیدا می‌کند.                                                    ║
    ║    • اگر scaler نبود: fallback خطی در فضای σ (بدون compounding) با       ║
    ║      return_space='sigma' و پرچم هشدار.                                  ║
    ║    • کلید جدید balanced_directional_accuracy (قبلاً در COMPOSITE-SELECT  ║
    ║      همیشه 0 خوانده می‌شد).                                              ║
    ╚══════════════════════════════════════════════════════════════════════════╝
    """
    # ── ۱) Alias resolution ──
    if X is None and X_test is not None:
        X = X_test
    if y is None and y_test_dict is not None:
        y = y_test_dict

    # ── ۲) پارامترهای اختیاری ──
    stop_loss = float(kwargs.pop('stop_loss', 0.03))
    take_profit = float(kwargs.pop('take_profit', 0.06))
    trailing_stop = float(kwargs.pop('trailing_stop', 0.008))
    transaction_cost = float(kwargs.pop('transaction_cost', 0.0005))
    slippage = float(kwargs.pop('slippage', 0.0002))
    timeframe = str(kwargs.pop('timeframe', '30M'))
    signal_override = kwargs.pop('signal_override', None)
    bar_high_ret = kwargs.pop('bar_high_ret', None)
    bar_low_ret = kwargs.pop('bar_low_ret', None)
    return_scale_factor_override = kwargs.pop('return_scale_factor', None)
    if scaler_params is None:
        scaler_params = kwargs.pop('scaler_params', None)

    _ignored = sorted(kwargs.keys())
    if _ignored:
        logger.debug(
            f"[EVAL v11.0] پارامترهای ناشناخته نادیده گرفته شد: {_ignored}"
        )

    out = {
        'sharpe': 0.0, 'sharpe_raw': 0.0, 'win_rate': 0.0, 'dir_acc': 0.0,
        'mae': None, 'rmse': None, 'ic_pearson': None, 'ic_spearman': None,
        'max_drawdown': 0.0, 'n_samples': 0, 'scale_mismatch': False,
        'applied_scale': 1.0, 'risk_levels': dict(risk_levels or {}),
        'head_found': False, 'notes': [],
        'sharpe_ratio': 0.0, 'sharpe_trade_based': 0.0, 'sharpe_equity_based': 0.0,
        'sortino_ratio': 0.0, 'calmar_ratio': 0.0, 'recovery_factor': 0.0,
        'total_return': 0.0, 'profit_factor': 0.0, 'expectancy': 0.0,
        'total_trades': 0, 'win_rate_trades': 0.0, 'avg_win': 0.0, 'avg_loss': 0.0,
        'max_consecutive_losses': 0, 'stop_loss_rate': 0.0, 'take_profit_rate': 0.0,
        'signal_flip_rate': 0.0, 'trailing_stop_rate': 0.0,
        'equity_final': 1.0, 'equity_peak': 1.0, 'equity_trough': 1.0,
        'annual_volatility': 0.0,
        'directional_accuracy': 0.0, 'directional_accuracy_overall': 0.0,
        'balanced_directional_accuracy': 0.0,
        'non_hold_samples': 0,
        'trend_accuracy': 0.0, 'volatility_accuracy': 0.0, 'market_accuracy': 0.0,
        'model_collapsed': False,
        'signal_source': 'none', 'signal_threshold_used': 0.0, 'n_signals': 0,
        'bar_return_sigma': 0.0, 'stop_loss_used': 0.0, 'take_profit_used': 0.0,
        'reward_risk_ratio': 0.0, 'risk_levels_rescaled': False,
        'simulator_mode': 'none', 'metrics_reliable': False,
        'scale_factor_applied': 1.0, 'return_unit_hint': 'unknown',
        'sharpe_hit_clip_cap': False,
        'data_was_normalized': bool(data_is_normalized),
        # ── فیلدهای جدید v11.0 ──
        'return_space': 'unknown',
        'metrics_unit': 'unknown',
        'ruined': False,
        'denormalization': None,
    }

    if model is None or X is None:
        out['notes'].append('model/X غایب است ⇒ ارزیابی ممکن نیست')
        logger.error(
            f"[EVAL v11.0] model یا X موجود نیست "
            f"(model={'✅' if model is not None else '❌'}, "
            f"X={'✅' if X is not None else '❌'})"
        )
        return out

    # ── ۳) پیش‌بینی ──
    try:
        try:
            raw = model.predict(X, batch_size=batch_size, verbose=1)
        except TypeError:
            raw = model.predict(X, verbose=1)
    except Exception as e:
        out['notes'].append(f'predict failed: {e}')
        logger.error(f'[EVAL v11.0] predict ناکام: {e}')
        return out

    heads = resolve_head_outputs(model, raw, output_order or task_names)
    # ── ۳.۵) ادغام پیش‌بینی مدل‌های جایگزین ──
    if replacement_predictions:
        for tgt, preds in replacement_predictions.items():
            if preds is None:
                continue
            try:
                heads[tgt] = np.asarray(preds)
                logger.info(
                    f"[EVAL v11.1] 🔁 replaced head '{tgt}' with "
                    f"replacement-model predictions "
                    f"(shape={heads[tgt].shape})"
                )
            except Exception as e:
                logger.warning(
                    f"[EVAL v11.1] could not inject replacement preds "
                    f"for '{tgt}': {e}"
                )
    # ── ۴) هد price_return ──
    pred = heads.get('price_return')
    if pred is None:
        for k in heads:
            if 'return' in str(k):
                pred = heads[k]
                break
    if pred is None and heads:
        order = output_order or OUTPUT_ORDER_FALLBACK
        keys = list(heads.keys())
        if len(keys) == len(order) and 'price_return' in order:
            pred = heads[keys[order.index('price_return')]]
    if pred is None:
        out['notes'].append(
            f"هد price_return حل نشد (heads={sorted(heads.keys())})"
        )
        logger.error(
            f"[EVAL v11.0] هد price_return در خروجی مدل نیست ⇒ "
            f"موجود: {sorted(heads.keys())}"
        )
        return out

    p = np.asarray(pred, dtype=np.float64)
    if p.ndim > 1 and p.shape[-1] == 1:
        p = p.reshape(-1)
    if p.ndim > 1 and p.shape[-1] > 1:
        out['notes'].append(
            'هد price_return چندکلاسه است ⇒ ارزیابی مالی معتبر نیست'
        )
        logger.error(
            '[EVAL v11.0] هد price_return چندکلاسه است؛ ارزیابی مالی روی این هد '
            'معنا ندارد (احتمالاً نگاشت هدها جابه‌جا است).'
        )
        return out
    p = np.nan_to_num(p.reshape(-1), nan=0.0, posinf=0.0, neginf=0.0)

    # ── ۵) برچسب ──
    y_ret = None
    if isinstance(y, dict):
        y_ret = y.get('price_return')
        if y_ret is None:
            for k in y:
                if 'return' in str(k):
                    y_ret = y[k]
                    break
    elif isinstance(y, (list, tuple)):
        order = output_order or task_names or OUTPUT_ORDER_FALLBACK
        if 'price_return' in list(order):
            pos = list(order).index('price_return')
            if pos < len(y):
                y_ret = y[pos]
    elif y is not None:
        y_ret = y

    if y_ret is None:
        out['notes'].append('برچسب price_return برای مقایسه موجود نیست')
        logger.error('[EVAL v11.0] برچسب price_return موجود نیست.')
        y_true = np.zeros_like(p)
    else:
        y_true = np.asarray(y_ret, dtype=np.float64).reshape(-1)

    n = int(min(p.size, y_true.size, int(max_eval_samples)))
    if n < 2:
        out['notes'].append(f'تعداد نمونهٔ معتبر کافی نیست (n={n})')
        logger.error(f'[EVAL v11.0] n={n} برای ارزیابی کافی نیست.')
        return out
    p, y_true = p[:n], y_true[:n]

    # ═══════════════════════════════════════════════════════════════════
    # 🔥 ۶) SCALE-FACTOR DETECTION — همان semantics v10 (بدون تغییر)
    # ═══════════════════════════════════════════════════════════════════
    std_true_original = float(np.std(y_true))
    std_pred_original = float(np.std(p))

    scale_factor = 1.0
    return_unit_hint = 'raw_return'

    # ── حالت ۱: override صریح کاربر ──
    if return_scale_factor_override is not None:
        try:
            sf = float(return_scale_factor_override)
            if sf > 0 and np.isfinite(sf):
                scale_factor = sf
                return_unit_hint = f'explicit_override(×{sf:g})'
                logger.warning(
                    f"[EVAL v11.0] 🔧 صریح scale_factor={sf:g} از کاربر "
                    f"(بدون auto-detection)"
                )
        except (TypeError, ValueError):
            logger.warning(
                f"[EVAL v11.0] return_scale_factor="
                f"{return_scale_factor_override!r} نامعتبر ⇒ auto-detection "
                f"ادامه می‌یابد"
            )

    # ── حالت ۲: مقایسه با σ مرجع ──
    if scale_factor == 1.0 and isinstance(train_reference_std, (int, float)):
        try:
            ref_std = float(train_reference_std)
            if ref_std > 1e-12 and std_true_original > 1e-12:
                ratio_to_ref = std_true_original / ref_std
                if ratio_to_ref > 10.0:
                    candidate = ratio_to_ref
                    exp = round(np.log10(candidate))
                    candidate = 10.0 ** exp
                    if 10.0 <= candidate <= 10000.0:
                        scale_factor = candidate
                        return_unit_hint = (
                            f'scaler_compare(σ_true={std_true_original:.4g} '
                            f'/ σ_ref={ref_std:.4g} ≈ {candidate:.0f})'
                        )
                        logger.warning(
                            f"[EVAL v11.0] 🔧 SCALE DETECTED از مقایسهٔ σ مرجع: "
                            f"scale_factor={scale_factor:.0f}"
                        )
        except (TypeError, ValueError):
            pass

    # ── حالت ۳: heuristic با گیتِ data_is_normalized (رفتار v10 حفظ شد) ──
    if scale_factor == 1.0:
        if data_is_normalized:
            if std_true_original > 20.0:
                exp = round(np.log10(std_true_original / 0.005))
                if exp >= 1 and exp <= 6:
                    scale_factor = 10.0 ** exp
                    return_unit_hint = (
                        f'normalized_flag_but_sigma={std_true_original:.4g}'
                        f'_suggests_raw_data → divided by {scale_factor:.0f}'
                    )
                    logger.warning(
                        f"[EVAL v11.0] ⚠️ data_is_normalized=True اما "
                        f"σ_true={std_true_original:.4g} > 20 ⇒ فرض می‌شود "
                        f"داده خام است؛ scale_factor={scale_factor:.0f}"
                    )
            else:
                logger.info(
                    f"[EVAL v11.0] ✅ data_is_normalized=True و "
                    f"σ_true={std_true_original:.4g} در بازهٔ نرمال‌شدهٔ معتبر ⇒ "
                    f"scale_factor=1 (بدون rescaling). "
                    f"این تصمیم از روی دادهٔ z-scored گرفته شد، نه heuristic."
                )
        else:
            if std_true_original > 0.10:
                exp = round(np.log10(std_true_original / 0.005))
                if exp >= 1 and exp <= 4:
                    scale_factor = 10.0 ** exp
                    return_unit_hint = (
                        f'raw_heuristic(σ_true={std_true_original:.4g} → '
                        f'divided by {scale_factor:.0f})'
                    )
                    logger.warning(
                        f"[EVAL v11.0] 🔧 SCALE HEURISTIC (raw mode): "
                        f"σ_true={std_true_original:.4g} "
                        f"⇒ scale_factor={scale_factor:.0f}"
                    )

    # ── اعمال scale factor ──
    if scale_factor != 1.0:
        y_true = y_true / scale_factor
        p = p / scale_factor
        out['scale_factor_applied'] = float(scale_factor)
        out['return_unit_hint'] = return_unit_hint
        logger.warning(
            f"[EVAL v11.0] ✅ scale_factor={scale_factor:.0f} اعمال شد — "
            f"σ_true جدید={np.std(y_true):.6g}, σ_pred جدید={np.std(p):.6g}"
        )
    else:
        out['return_unit_hint'] = (
            'raw_return (no scale adjustment needed)'
            if not data_is_normalized
            else 'normalized_return (σ≈1.0, no scale adjustment)'
        )

    std_true = float(np.std(y_true))
    std_pred = float(np.std(p))
    ratio = (std_pred / std_true) if std_true > 1e-12 else np.inf

    # ── ۷) تشخیص scale mismatch بین pred و true (جدا از scale_factor) ──
    if not np.isfinite(ratio) or ratio > float(scale_mismatch_tolerance) \
            or ratio < 1.0 / float(max(scale_mismatch_tolerance, 1e-9)):
        out['scale_mismatch'] = True
        ref_std = (
            float(train_reference_std)
            if isinstance(train_reference_std, (int, float))
            and np.isfinite(float(train_reference_std))
            and float(train_reference_std) > 1e-12
            else None
        )
        out['notes'].append(
            f'SCALE MISMATCH (pred vs true): σ_pred={std_pred:.6g} vs '
            f'σ_true={std_true:.6g} (ratio={ratio:.4g})'
        )
        if allow_auto_rescale and ref_std is not None:
            ref_std_scaled = ref_std / scale_factor
            factor = ref_std_scaled / max(std_pred, 1e-12)
            p = p * factor
            out['applied_scale'] = float(factor)
            std_pred = float(np.std(p))
            logger.warning(
                f'[EVAL v11.0] 🔧 اصلاح صریح pred-scale با مرجع train: '
                f'factor={factor:.6g}. σ_pred جدید={std_pred:.6g}'
            )
        else:
            logger.error(
                f'[EVAL v11.0] 🚨 PRED vs TRUE SCALE MISMATCH: '
                f'σ_pred={std_pred:.6g}, σ_true={std_true:.6g}, ratio={ratio:.4g}. '
                f'مدل عملاً روی میانگین پیش‌بینی می‌کند.'
            )

    # ── ۸) متریک‌های آماری (در فضای z — برای پیوستگی با FastVal) ──
    p_f = np.nan_to_num(p, nan=0.0, posinf=0.0, neginf=0.0)
    y_f = np.nan_to_num(y_true, nan=0.0, posinf=0.0, neginf=0.0)

    sd = float(np.std(p_f, ddof=1)) if p_f.size > 1 else 0.0
    mean_p = float(np.mean(p_f))
    sharpe_raw = (mean_p / sd * float(np.sqrt(bars_per_year))) if sd > 1e-12 else 0.0
    out['sharpe_raw'] = float(sharpe_raw)

    mask = np.abs(y_f) > 1e-12
    if int(mask.sum()) > 0:
        out['win_rate'] = float(
            np.mean(np.sign(p_f[mask]) == np.sign(y_f[mask]))
        )
    out['dir_acc'] = float(out['win_rate'])

    out['mae'] = float(np.mean(np.abs(y_f - p_f)))
    out['rmse'] = float(np.sqrt(np.mean((y_f - p_f) ** 2)))

    for name, fn in (('ic_pearson', _pearson_corr), ('ic_spearman', _spearman_corr)):
        try:
            out[name] = fn(y_f, p_f)
        except Exception as e:
            out['notes'].append(f'{name} failed: {e}')

    # ═══════════════════════════════════════════════════════════════════
    # 🔥 ۹) NEW — REAL-SPACE RESOLUTION + DENORMALIZATION (v11.0)
    # ═══════════════════════════════════════════════════════════════════
    ret_mean, ret_std = _extract_return_scaler(scaler_params)
    denorm_applied = False

    if ret_std is not None and ret_mean is not None:
        if std_true > 4.0 * ret_std:
            # داده z-scored است (σ داده صدها برابر σ واقعی) ⇒ تبدیل به بازدهٔ واقعی
            y_sim = y_f * ret_std + ret_mean
            p_sim = p_f * ret_std + ret_mean
            denorm_applied = True
            return_space = 'real'
            out['denormalization'] = {'mean': ret_mean, 'std': ret_std}
            logger.info(
                f"[EVAL v11.0] ✅ denormalize به بازدهٔ واقعی: "
                f"mean={ret_mean:.3e}, std={ret_std:.3e} ⇒ "
                f"σ_sim={float(np.std(y_sim)):.3e}"
            )
        else:
            # σ داده با σ scaler هم‌مرتبه است ⇒ داده از قبل واقعی است
            y_sim = np.array(y_f, copy=True)
            p_sim = np.array(p_f, copy=True)
            return_space = 'real'
            out['denormalization'] = {
                'skipped': 'data_sigma_matches_scaler_std (already real)'
            }
            logger.info(
                f"[EVAL v11.0] ℹ️ σ داده ({std_true:.3e}) هم‌مرتبهٔ σ scaler "
                f"({ret_std:.3e}) ⇒ داده از قبل واقعی است؛ denorm انجام نشد."
            )
    else:
        y_sim = np.array(y_f, copy=True)
        p_sim = np.array(p_f, copy=True)
        return_space = 'sigma'
        logger.warning(
            f"[EVAL v11.0] ⚠️ scaler قیمت (mean/std) در scaler_params نیست ⇒ "
            f"شبیه‌سازی خطی در فضای σ (fallback). متریک‌ها در واحد σ هستند، "
            f"نه پول واقعی؛ برای مقایسه با آستانه‌های edge قابل‌استفاده نیستند."
        )
    out['return_space'] = return_space

    # ── ۱۰) سطوح ریسک در فضای شبیه‌سازی ──
    sigma_sim = float(np.std(y_sim)) if len(y_sim) > 1 else 0.0

    if not risk_levels:
        if return_space == 'real':
            base_sigma = sigma_sim
            source = 'σ آزمون (بازدهٔ واقعی)'
            if isinstance(train_reference_std, (int, float)) \
                    and np.isfinite(float(train_reference_std)) \
                    and float(train_reference_std) > 1e-12 \
                    and ret_std is not None:
                base_sigma = float(train_reference_std) * ret_std
                source = 'σ مرجع train × scaler_std'
            auto_sl = float(max(sl_sigma * base_sigma, 1e-6))
            auto_tp = float(max(tp_sigma * base_sigma, 1.5 * auto_sl, 2e-6))
            out['risk_levels'] = {
                'sl': -auto_sl, 'tp': auto_tp,
                'sigma': base_sigma, 'source': source,
            }
        else:
            auto_sl = float(sl_sigma)
            auto_tp = float(tp_sigma)
            out['risk_levels'] = {
                'sl': -auto_sl, 'tp': auto_tp,
                'sigma': 1.0, 'source': 'sigma_units_fallback',
            }
        logger.info(
            f"[FIN_METRICS v11.0] سطوح ریسک: SL={out['risk_levels']['sl']:.6f} "
            f"({sl_sigma}σ), TP={out['risk_levels']['tp']:.6f} ({tp_sigma}σ), "
            f"σ={out['risk_levels']['sigma']:.6f} | space={return_space}"
        )
    else:
        rl = dict(risk_levels)
        if scale_factor != 1.0 and 'sl' in rl and abs(rl['sl']) > 1.0:
            rl['sl'] = rl['sl'] / scale_factor
            rl['tp'] = rl['tp'] / scale_factor
            if 'sigma' in rl:
                rl['sigma'] = rl['sigma'] / scale_factor
        out['risk_levels'] = rl
        auto_sl = float(abs(rl.get('sl', 2.5 * sigma_sim)))
        auto_tp = float(abs(rl.get('tp', 4.0 * sigma_sim)))

    if not np.isfinite(auto_sl) or auto_sl <= 0:
        auto_sl = max(
            float(stop_loss),
            2.5 * sigma_sim if sigma_sim > 1e-9 else float(stop_loss),
        )
    if not np.isfinite(auto_tp) or auto_tp <= 0:
        auto_tp = max(
            float(take_profit),
            4.0 * sigma_sim if sigma_sim > 1e-9 else float(take_profit),
        )

    # ── ۱۱) شبیه‌سازی معاملات ──
    fin = {}
    try:
        fin = calculate_financial_metrics_with_stop_loss(
            y_true=y_sim,
            y_pred=p_sim,
            stop_loss=float(auto_sl),
            take_profit=float(auto_tp),
            trailing_stop=float(trailing_stop),
            transaction_cost=float(transaction_cost),
            slippage=float(slippage),
            already_denormalized=True,
            is_normalized_data=True,
            min_signal_threshold=0.0005,
            timeframe=timeframe,
            signal_override=signal_override,
            auto_threshold=True,
            auto_risk_levels=True,
            risk_sigma_stop=sl_sigma,
            risk_sigma_target=tp_sigma,
            bar_high_ret=bar_high_ret,
            bar_low_ret=bar_low_ret,
            return_space=return_space,
        )
    except Exception as fin_err:
        logger.error(
            f"[EVAL v11.0] calculate_financial_metrics_with_stop_loss ناکام: "
            f"{fin_err}"
        )
        logger.error(traceback.format_exc())
        fin = {}

    # ── ۱۲) ادغام متریک‌های مالی ──
    if fin:
        fin_sharpe = float(fin.get('sharpe_ratio', 0.0) or 0.0)
        fin_trades = int(fin.get('total_trades', 0) or 0)

        hit_clip = bool(fin.get('sharpe_hit_clip_cap', False))
        if not hit_clip and fin_trades > 0 and abs(abs(fin_sharpe) - 10.0) < 1e-6:
            hit_clip = True
        out['sharpe_hit_clip_cap'] = hit_clip
        if hit_clip:
            logger.error(
                f"[EVAL v11.0] 🚨 SHARPE HIT CLIP CAP: {fin_sharpe:.4f}. "
                f"شبیه‌ساز عددی ناپایدار است."
            )
            out['notes'].append(
                f'sharpe_hit_clip_cap (raw>{abs(fin_sharpe):.2f})'
            )

        out['sharpe_ratio'] = fin_sharpe
        out['sharpe'] = fin_sharpe
        out['sharpe_trade_based'] = float(fin.get('sharpe_trade_based', 0.0) or 0.0)
