        if HAS_LGBM:
            estimators.append(("lgbm", self._make_lgbm_classifier()))
        estimators.append(("rf", self._make_rf_classifier()))
        estimators = [e for e in estimators if e[1] is not None]
        if len(estimators) < 2:
            return None
        return VotingClassifier(
            estimators=estimators, voting="soft", n_jobs=self.hw.n_jobs_cpu
        )

