class WorkflowStatePersistenceCallback(tf.keras.callbacks.Callback):
    """
    WORKFLOW STATE PERSISTENCE v2.0 — FULL RESUME (audit #13).

    در پایان هر epoch می‌نویسد:
      • _WORKFLOW_STATE.json       — state همهٔ callbackهای stateful
      • _TRAINER_STATE.json        — log_vars, class_weights, paused_heads, ...
      • _OPTIMIZER_STATE.npz       — Adam/AdamW slots (m, v)

    trainer از `self.model` خوانده می‌شود (Keras این را خودکار به
    Keras Model که در حال آموزش است تنظیم می‌کند). این callback باید
    LAST در لیست callbacks باشد.
    """

    def __init__(
        self,
        checkpoint_dir: str,
        stateful_callbacks: List[tf.keras.callbacks.Callback],
        save_every_n_epochs: int = 1,
        save_optimizer_every_n_epochs: int = 1,
        verbose: int = 1,
    ):
        super().__init__()
        self.checkpoint_dir = str(checkpoint_dir)
        self.stateful_callbacks = list(stateful_callbacks or [])
        self.save_every_n_epochs = max(1, int(save_every_n_epochs))
        self.save_optimizer_every_n_epochs = max(
            1, int(save_optimizer_every_n_epochs)
        )
        self.verbose = int(verbose)

        self._global_epoch = 0
        self._last_save_epoch = -1
        self._last_save_ok = False

        try:
            os.makedirs(self.checkpoint_dir, exist_ok=True)
        except Exception as e:
            logger.warning(
                f"[WorkflowStatePersistence v2.0] mkdir failed: {e}"
            )

    # ------------------------------------------------------------------
    def _collect_state(self, current_epoch: int) -> Dict:
        state = {
            'state_version': '1.0',
            'saved_at': datetime.now().isoformat(),
            'current_epoch': int(current_epoch),
        }
        for cb in self.stateful_callbacks:
            key = type(cb).__name__
            if hasattr(cb, 'to_state'):
                try:
                    cb_state = cb.to_state()
                    if isinstance(cb_state, dict):
                        state[key] = cb_state
                except Exception as e:
                    logger.warning(
                        f"[WorkflowStatePersistence v2.0] to_state on "
                        f"{key} failed: {e}"
                    )
            else:
                logger.debug(
                    f"[WorkflowStatePersistence v2.0] {key} has no to_state — skip"
                )
        return state

    def _dump_state(self, current_epoch: int) -> bool:
        state = self._collect_state(current_epoch)
        json_path = os.path.join(
            self.checkpoint_dir, '_WORKFLOW_STATE.json'
        )
        try:
            json_ready = _to_jsonable(state)
            tmp = json_path + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(json_ready, f, indent=2, ensure_ascii=False)
            os.replace(tmp, json_path)
            self._last_save_epoch = int(current_epoch)
            self._last_save_ok = True
            if self.verbose >= 1:
                n_keys = len(state) - 3
                logger.info(
                    f"[WorkflowStatePersistence v2.0] 💾 workflow saved "
                    f"at epoch {current_epoch}: {n_keys} callbacks, "
                    f"path={json_path}"
                )
        except Exception as e:
            logger.error(
                f"[WorkflowStatePersistence v2.0] dump failed: {e}",
                exc_info=True,
            )
            self._last_save_ok = False
            return False

        # NEW v2.0: trainer + optimizer state
        self._save_trainer_state(current_epoch)
        return True

    def _save_trainer_state(self, current_epoch: int) -> None:
        """ذخیرهٔ state trainer + optimizer slots."""
        try:
            trainer = getattr(self, 'model', None)
            if trainer is None:
                return
            if not hasattr(trainer, 'to_training_state'):
                return

            trainer_state = trainer.to_training_state()
            json_path = os.path.join(
                self.checkpoint_dir, '_TRAINER_STATE.json'
            )
            tmp = json_path + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(_to_jsonable(trainer_state), f, indent=2,
                          ensure_ascii=False)
            os.replace(tmp, json_path)

            if current_epoch % self.save_optimizer_every_n_epochs == 0:
                if hasattr(trainer, 'save_optimizer_state'):
                    opt_path = os.path.join(
                        self.checkpoint_dir, '_OPTIMIZER_STATE.npz'
                    )
                    trainer.save_optimizer_state(opt_path)

            if self.verbose >= 1:
                logger.info(
                    f"[WorkflowStatePersistence v2.0] 💾 trainer state saved "
                    f"at epoch {current_epoch}"
                )
        except Exception as e:
            logger.warning(
                f"[WorkflowStatePersistence v2.0] trainer state save "
                f"failed (non-fatal): {e}"
            )

    # ------------------------------------------------------------------
    def on_train_begin(self, logs=None):
        pass  # عمداً counter را ریست نمی‌کنیم تا healing rounds پیوسته باشد

    def on_epoch_end(self, epoch, logs=None):
        try:
            ep = int(epoch) + 1
        except (TypeError, ValueError):
            return
        self._global_epoch = ep

        if self.save_every_n_epochs <= 1 or (ep % self.save_every_n_epochs == 0):
            self._dump_state(ep)

    def on_train_end(self, logs=None):
        if self._global_epoch > 0 and self._last_save_epoch != self._global_epoch:
            self._dump_state(self._global_epoch)

    def reset_for_healing(self, new_dynamic_params=None) -> None:
        if self._global_epoch > 0:
            self._dump_state(self._global_epoch)
        logger.info(
            "[WorkflowStatePersistence v2.0] 🔄 state flushed for healing"
        )
        

# ═══════════════════════════════════════════════════════════════════════════
# Workflow state loader — module-level helper
# ═══════════════════════════════════════════════════════════════════════════

def _load_workflow_state_file(
    checkpoint_dir: str,
    tracker_epoch: Optional[int] = None,
    max_stale_epochs: int = 50,
    max_age_hours: float = 72.0,
) -> Optional[Dict]:
    """
    _LOAD_WORKFLOW_STATE_FILE v2.0 — FRESHNESS-GATED.

    🔥 v2.0 (RCA از state stale اثبات‌شده در لاگ شما):
        فایل _WORKFLOW_STATE.json حاوی مقادیر best_val_loss=3.108 و
        best=3.643 از یک ران بسیار قدیمی‌تر بود. ران جدید به آن مقادیر
        نمی‌رسید، پس save_best_only=True هیچ مدل جدیدی ذخیره نمی‌کرد.
        نتیجه: هر resume به همان state کهنه برمی‌گشت.

    گیت‌های v2.0 (به ترتیب):
      1) env OMNI_FRESH_RUN=1 → رد کامل (بدون اسکن).
      2) فایل وجود ندارد → رد.
      3) JSON نامعتبر / غیر dict → رد.
      4) age check: فایل قدیمی‌تر از max_age_hours ساعت → رد.
         (max_age_hours از env OMNI_STATE_MAX_AGE_HOURS قابل override)
      5) epoch check: |workflow_epoch − tracker_epoch| > max_stale_epochs
         → رد. (tracker از last_epoch.txt در همان checkpoint_dir)
      6) در غیر این صورت → state معتبر برگردانده می‌شود.

    Args:
        checkpoint_dir   : پوشهٔ حاوی _WORKFLOW_STATE.json.
        tracker_epoch    : اگر None باشد، از last_epoch.txt خوانده می‌شود.
        max_stale_epochs : حداکثر اختلاف مجاز بین workflow_epoch و tracker_epoch.
        max_age_hours    : حداکثر سن فایل state.

    Returns:
        dict اگر state معتبر باشد، در غیر این صورت None.
    """
    phase = "WORKFLOW_STATE_LOADER_V2"

    # ── ۱) env check ──
    fresh_env = (
        os.environ.get("OMNI_FRESH_RUN", "").strip().lower()
        in ("1", "true", "yes", "on")
    )
    if fresh_env:
        logger.warning(
            f"[{phase}] 🧹 OMNI_FRESH_RUN=1 → state file IGNORED "
            f"(fresh start requested by env)"
        )
        return None

    # ── ۲) فایل وجود دارد؟ ──
    if not checkpoint_dir:
        return None

    path = os.path.join(str(checkpoint_dir), "_WORKFLOW_STATE.json")
    if not os.path.exists(path):
        logger.info(
            f"[{phase}] _WORKFLOW_STATE.json not found at {path} — "
            f"fresh restart will use defaults"
        )
        return None

    # ── ۳) خواندن + parse ──
    try:
        with open(path, "r", encoding="utf-8") as f:
            state = json.load(f)
    except Exception as e:
        logger.error(f"[{phase}] load failed: {e}", exc_info=True)
        return None

    if not isinstance(state, dict):
        logger.warning(f"[{phase}] state file is not a dict — ignored")
        return None

    # ── ۴) age check ──
    try:
        env_age = os.environ.get("OMNI_STATE_MAX_AGE_HOURS", "").strip()
        if env_age:
            max_age_hours = float(env_age)
        if not (np.isfinite(max_age_hours) and max_age_hours > 0.0):
            max_age_hours = 72.0
    except (TypeError, ValueError):
        max_age_hours = 72.0

    try:
        file_mtime = os.path.getmtime(path)
        file_age_seconds = max(0.0, time.time() - file_mtime)
        file_age_hours = file_age_seconds / 3600.0
    except OSError:
        file_age_hours = 0.0

    if file_age_hours > max_age_hours:
        logger.warning(
            f"[{phase}] ⏰ state file is STALE: age={file_age_hours:.1f}h "
            f"> max_age_hours={max_age_hours:.1f}h → REJECTED."
        )
        return None

    # ── ۵) epoch check ──
    if tracker_epoch is None:
        tracker_path = os.path.join(str(checkpoint_dir), "last_epoch.txt")
        if os.path.exists(tracker_path):
            try:
                with open(tracker_path, "r", encoding="utf-8") as f:
                    tracker_epoch = int(
                        json.load(f).get("last_epoch", 0)
                    )
            except Exception as e:
                logger.debug(
                    f"[{phase}] tracker read failed: {e} — "
                    f"skipping epoch check"
                )
                tracker_epoch = None

    wf_epoch_raw = state.get("current_epoch")
    try:
        wf_epoch = int(wf_epoch_raw) if wf_epoch_raw is not None else None
    except (TypeError, ValueError):
        wf_epoch = None

    if (
        tracker_epoch is not None
        and wf_epoch is not None
        and int(max_stale_epochs) > 0
    ):
        try:
            epoch_diff = abs(int(wf_epoch) - int(tracker_epoch))
        except (TypeError, ValueError):
            epoch_diff = None

        if epoch_diff is not None and epoch_diff > int(max_stale_epochs):
            logger.warning(
                f"[{phase}] ⏰ state EPOCH MISMATCH: "
                f"workflow_epoch={wf_epoch}, tracker_epoch={tracker_epoch}, "
                f"diff={epoch_diff} > max_stale_epochs={max_stale_epochs} "
                f"→ REJECTED."
            )
            return None

    # ── ۶) پذیرش ──
    logger.info(
        f"[{phase}] ✅ ACCEPTED state — epoch={wf_epoch}, "
        f"age={file_age_hours:.1f}h, "
        f"keys={sorted(k for k in state.keys() if k != 'saved_at')}"
    )
    return state

def _load_trainer_state_and_optimizer(
    checkpoint_dir: str,
    trainer: Any,
    force_fresh: bool = False,
    max_age_hours: float = 72.0,
) -> bool:
    """
    _LOAD_TRAINER_STATE_AND_OPTIMIZER v1.0 — RESUME-SAFE.

    از checkpoint_dir، فایل‌های `_TRAINER_STATE.json` و
    `_OPTIMIZER_STATE.npz` را می‌خواند و روی trainer اعمال می‌کند.

    گیت‌های ایمنی:
      • force_fresh=True یا env OMNI_FRESH_RUN=1 → هیچ state‌ای لود نمی‌شود.
      • فایل قدیمی‌تر از max_age_hours → رد می‌شود (env
        OMNI_STATE_MAX_AGE_HOURS قابل override).
      • trainer فاقد `restore_training_state` → skip (backward compat).

    Returns:
        True اگر حداقل یکی از دو فایل با موفقیت بازگردانده شد.
    """
    phase = "LOAD_TRAINER_STATE_V1"

    if force_fresh:
        logger.info(f"[{phase}] skip (force_fresh=True)")
        return False
    if os.environ.get("OMNI_FRESH_RUN", "").strip().lower() in (
        "1", "true", "yes", "on"
    ):
        logger.warning(
            f"[{phase}] 🧹 OMNI_FRESH_RUN=1 → trainer state IGNORED"
        )
        return False
    if trainer is None:
        return False
    if not hasattr(trainer, 'restore_training_state'):
        logger.debug(
            f"[{phase}] trainer lacks restore_training_state — skip"
        )
        return False
    if not checkpoint_dir:
        return False

    try:
        env_age = os.environ.get("OMNI_STATE_MAX_AGE_HOURS", "").strip()
        if env_age:
            max_age_hours = float(env_age)
        if not (np.isfinite(max_age_hours) and max_age_hours > 0.0):
            max_age_hours = 72.0
    except (TypeError, ValueError):
        max_age_hours = 72.0

    def _fresh_enough(path: str) -> bool:
        try:
            age_h = (time.time() - os.path.getmtime(path)) / 3600.0
        except OSError:
            return False
        if age_h > max_age_hours:
            logger.warning(
                f"[{phase}] {os.path.basename(path)} STALE "
                f"(age={age_h:.1f}h > {max_age_hours:.1f}h) — rejected"
            )
            return False
        return True

    loaded_any = False

    # ── Trainer state (JSON) ──
    json_path = os.path.join(str(checkpoint_dir), '_TRAINER_STATE.json')
    if os.path.exists(json_path) and _fresh_enough(json_path):
        try:
            with open(json_path, 'r', encoding='utf-8') as f:
                state = json.load(f)
            if trainer.restore_training_state(state):
                loaded_any = True
                logger.info(
                    f"[{phase}] ✅ trainer state restored from "
                    f"{os.path.basename(json_path)}"
                )
        except Exception as e:
            logger.warning(f"[{phase}] JSON restore failed: {e}")

    # ── Optimizer state (NPZ) ──
    opt_path = os.path.join(str(checkpoint_dir), '_OPTIMIZER_STATE.npz')
    if os.path.exists(opt_path) and _fresh_enough(opt_path):
        try:
            if hasattr(trainer, 'load_optimizer_state'):
                if trainer.load_optimizer_state(opt_path):
                    loaded_any = True
                    logger.info(
                        f"[{phase}] ✅ optimizer state restored from "
                        f"{os.path.basename(opt_path)}"
                    )
        except Exception as e:
            logger.warning(f"[{phase}] optimizer restore failed: {e}")

    if not loaded_any:
        logger.info(
            f"[{phase}] no compatible trainer/optimizer state found — "
            f"resuming with weights only (fresh optimizer/momentum)"
        )
    return loaded_any
    
def _inject_workflow_state(
    callbacks: List[tf.keras.callbacks.Callback],
    workflow_state: Dict,
    force_fresh: Optional[bool] = None,
) -> int:
    """
    _INJECT_WORKFLOW_STATE v2.0 — FRESH-SAFE + ROOT-TIMESTAMP INJECTION.

    🔥 v2.0 (نسبت به v1.0):
        • اگر force_fresh True باشد (یا env OMNI_FRESH_RUN=1)، هیچ state
          تزریق نمی‌شود؛ صریحاً صفر برگردانده می‌شود.
        • saved_at سطح-ریشه به هر callback با نام _root_saved_at تزریق
          می‌شود تا callbackها در restore_state خودشان freshness را چک
          کنند (defense-in-depth).
        • رد شدن state با پیام WARNING صریح لاگ می‌شود (نه فقط debug).

    Args:
        callbacks        : لیست callbackها.
        workflow_state   : دیکشنری state از _load_workflow_state_file.
        force_fresh      : اگر None باشد، از env خوانده می‌شود.

    Returns:
        تعداد callbackهایی که restore موفق شدند.
    """
    phase = "WORKFLOW_STATE_INJECTOR_V2"

    # ── ۱) تعیین force_fresh ──
    if force_fresh is None:
        force_fresh = (
            os.environ.get("OMNI_FRESH_RUN", "").strip().lower()
            in ("1", "true", "yes", "on")
        )

    if force_fresh:
        logger.warning(
            f"[{phase}] 🧹 force_fresh=True → NO callback state restored "
            f"(fresh start enforced)"
        )
        return 0

    if not isinstance(workflow_state, dict) or not callbacks:
        return 0

    root_saved_at = workflow_state.get("saved_at")
    restored = 0

    for cb in callbacks:
        key = type(cb).__name__
        cb_state = workflow_state.get(key)
        if cb_state is None:
            continue
        if not hasattr(cb, "restore_state"):
            logger.debug(
                f"[{phase}] {key} has no restore_state — skip"
            )
            continue
        if not isinstance(cb_state, dict):
            logger.warning(
                f"[{phase}] {key} state is not a dict "
                f"({type(cb_state).__name__}) — skip"
            )
            continue

        # 🔥 v2.0: propagate root timestamp into cb_state
        try:
            cb_state_with_meta = dict(cb_state)
            cb_state_with_meta["_root_saved_at"] = root_saved_at
        except Exception:
            cb_state_with_meta = cb_state

        try:
            ok = bool(cb.restore_state(cb_state_with_meta))
            if ok:
                restored += 1
            else:
                logger.warning(
                    f"[{phase}] {key}.restore_state returned False "
                    f"(state rejected by callback itself)"
                )
        except Exception as e:
            logger.error(
                f"[{phase}] {key}.restore_state raised: {e}",
                exc_info=True,
            )

    logger.info(
        f"[{phase}] ✅ restored {restored}/{len(callbacks)} callbacks "
        f"(fresh={force_fresh}, root_saved_at={root_saved_at})"
    )
    return restored
    
def compute_logical_epoch_budget(
    ladder_size: int = 22,
    stall_window: int = 5,
    eval_margin_per_rung: int = 3,
    warmup_epochs: int = 15,
    focus_reserve: int = 120,
    focus_decision_epoch: int = 100,
    max_healing_attempts: int = 29,
    healing_epochs_per_round: int = 40,
) -> int:
    """
    COMPUTE_LOGICAL_EPOCH_BUDGET v2.0 — HARDWARE-INDEPENDENT + FOCUS-AWARE.

    🔥 v2.0 (نسبت به v1.0):
      • ladder_size پیش‌فرض از 31 (اشتباه) به 22 (تعداد واقعی
        CLASSIFICATION_LADDER منهای ردیف DL) اصلاح شد.
      • eval_margin_per_rung از 2 به 3 افزایش یافت — فاصلهٔ ارزیابی
        برای هر پله کافی باشد.
      • focus_reserve از 30 به 120 افزایش یافت تا بودجهٔ کافی برای
        FOCUS MODE (حداقل 100 epoch) تضمین شود.
      • محاسبهٔ نهایی به‌صورت مجموع «پله‌های نردبان + warmup +
        focus reserve» است، نه ضرب صرف.

    ساختار بودجه:
      was:    ladder × (stall + margin) + warmup + 30  → 199
      now:    ladder × (stall + margin) + warmup + 120 → 286

    علاوه بر این، healing loop می‌تواند با 29 دور × 40 epoch
    بودجه را تا 286 + 1160 = 1446 epoch گسترش دهد.

    اگر `OMNI_LOGICAL_EPOCHS` تعریف شده باشد، مقدار آن (بین
    30 تا 5000) به‌عنوان override استفاده می‌شود.

    Args:
        ladder_size            : تعداد کل پله‌های نردبان (پیش‌فرض 22).
        stall_window           : پنجرهٔ رکود (پیش‌فرض 5).
        eval_margin_per_rung   : margin ارزیابی هر پله (پیش‌فرض 3).
        warmup_epochs          : دورهٔ warmup (پیش‌فرض 15 — منطبق با
                                 خواستهٔ «تشخیص ضعیف‌ترین بعد از 15 ایپوک»).
        focus_reserve          : ذخیرهٔ بودجه برای FOCUS MODE (پیش‌فرض 120).
        focus_decision_epoch   : آستانهٔ «تصمیم بنیادین» (پیش‌فرض 100).
        max_healing_attempts   : حداکثر دورهای healing (پیش‌فرض 29).
        healing_epochs_per_round: epoch در هر دور healing (پیش‌فرض 40).

    Returns:
        بودجهٔ نهایی epoch (int)، حداقل 30.
    """
    import os as _os_local

    try:
        _ladder_size = int(max(1, ladder_size))
        _stall = int(max(1, stall_window))
        _margin = int(max(1, eval_margin_per_rung))
        _warmup = int(max(0, warmup_epochs))
        _focus_reserve = int(max(0, focus_reserve))
    except (TypeError, ValueError) as _e:
        logger.error(
            f"[LOGICAL_EPOCH_BUDGET v2.0] invalid arguments ({_e}) — "
            f"falling back to safe defaults"
        )
        _ladder_size, _stall, _margin = 22, 5, 3
        _warmup, _focus_reserve = 15, 120

    base = (
        _ladder_size * (_stall + _margin)
        + _warmup
        + _focus_reserve
    )

    env_val = _os_local.environ.get("OMNI_LOGICAL_EPOCHS", "").strip()
    if env_val:
        try:
            v = int(env_val)
            if 30 <= v <= 5000:
                logger.info(
                    f"[LOGICAL_EPOCH_BUDGET v2.0] 🌐 env override: {v} "
                    f"(structural default was {base})"
                )
                return v
            logger.warning(
                f"[LOGICAL_EPOCH_BUDGET v2.0] env OMNI_LOGICAL_EPOCHS={v} "
                f"out of [30, 5000]; using structural budget {base}"
            )
        except (TypeError, ValueError):
            logger.warning(
                f"[LOGICAL_EPOCH_BUDGET v2.0] env OMNI_LOGICAL_EPOCHS="
                f"{env_val!r} not an int; using structural budget {base}"
            )

    logger.info(
        f"[LOGICAL_EPOCH_BUDGET v2.0] 🌐 structural budget = {base} "
        f"(ladder={_ladder_size} × (stall={_stall} + margin={_margin}) "
        f"+ warmup={_warmup} + focus_reserve={_focus_reserve}) — "
        f"hardware-independent"
    )
    logger.info(
        f"[LOGICAL_EPOCH_BUDGET v2.0] 🌐 healing capacity: "
        f"{base} + {max_healing_attempts}×{healing_epochs_per_round} = "
        f"{base + max_healing_attempts * healing_epochs_per_round} epochs "
        f"(≥1000 epoch achievable with this budget)"
    )
    logger.info(
        f"[LOGICAL_EPOCH_BUDGET v2.0] 🌐 focus_decision_epoch={focus_decision_epoch} "
        f"— at this point a fundamental decision will be logged (not enforced)"
    )
    logger.info(
        f"[LOGICAL_EPOCH_BUDGET v2.0] 🌐 identical budget on CPU and GPU "
        f"by design"
    )
    return max(30, base)
    
def extract_target_with_validity_mask(
    arr,
    n_samples: int,
    is_cls: bool,
    n_cls: Optional[int] = None,
    name: str = "",
) -> Tuple[Optional[np.ndarray], Optional[np.ndarray], int]:
    """
    EXTRACT_TARGET_WITH_VALIDITY_MASK v1.0 — INVALID-AWARE EXTRACTION.

    برای تارگت‌های classification:
        • برچسب‌های INVALID (سنتینل -1 یا هر مقدار خارج از [0, n_cls-1])
          را **قبل از clip** تشخیص می‌دهد.
        • برچسب را به بازهٔ معتبر [0, n_cls-1] clip می‌کند (تا loss function
          بتواند کار کند).
        • یک ماسک بولی برمی‌گرداند: True = نمونهٔ معتبر، False = INVALID.

    برای تارگت regression:
        • ماسک None برمی‌گرداند (همه معتبر).

    Args:
        arr        : آرایهٔ خام تارگت (1D یا 2D one-hot یا None)
        n_samples  : تعداد نمونه‌های مورد انتظار (X.shape[0])
        is_cls     : True برای classification، False برای regression
        n_cls      : تعداد کلاس‌ها (برای classification الزامی است)
        name       : نام تارگت (برای لاگ)

    Returns:
        (target_array, valid_mask, n_invalid)
        - valid_mask = None برای regression
        - valid_mask = bool array (True = valid) برای classification
    """
    if arr is None:
        return None, None, 0

    a = np.asarray(arr, dtype=np.float32)
    a = np.nan_to_num(a, nan=0.0, posinf=0.0, neginf=0.0)

    if len(a) > n_samples:
        a = a[:n_samples]

    if not is_cls:
        if a.ndim == 1:
            a = a.reshape(-1, 1)
        return a.astype(np.float32), None, 0

    if n_cls is None or int(n_cls) < 2:
        raise ValueError(
            f"[EXTRACT_TARGET_MASK] classification target '{name}' "
            f"requires n_cls>=2, got {n_cls!r}"
        )
    n_cls = int(n_cls)

    # ── حالت one-hot: INVALID ممکن نیست ──
    if a.ndim == 2 and a.shape[1] > 1:
        idx = np.argmax(a, axis=1).astype(np.int32)
        valid_mask = np.ones(len(idx), dtype=bool)
        n_invalid = 0
    else:
        # ── حالت 1D: تشخیص INVALID قبل از clip ──
        idx_raw = a.reshape(-1).astype(np.float64)
        valid_mask = (
            np.isfinite(idx_raw)
            & (idx_raw >= 0.0)
            & (idx_raw < float(n_cls))
        )
        idx = np.clip(idx_raw, 0, n_cls - 1).astype(np.int32)
        n_invalid = int((~valid_mask).sum())

        if n_invalid > 0:
            invalid_values = idx_raw[~valid_mask]
            unique_bad = np.unique(invalid_values)[:5]
            logger.warning(
                f"[EXTRACT_TARGET_MASK] ⚠️ '{name}': {n_invalid}/"
                f"{len(idx)} ({100.0 * n_invalid / max(len(idx), 1):.2f}%) "
                f"INVALID labels detected (sample values: "
                f"{unique_bad.tolist()}). These samples will receive "
                f"sample_weight=0.0 for THIS head only; other heads still "
                f"learn from them."
            )

    return idx, valid_mask, n_invalid
    
class DynamicLearnabilitySuite:


    def __init__(self):
        """
        DYNAMIC LEARNABILITY SUITE v20.0 — RESUME-SAFE INITIALIZATION.

        Resume precedence: when OMNI_RESUME=1, checkpoint resume always wins over
        OMNI_FRESH_RUN, even if both variables were accidentally left enabled.
        This makes workflow state, ladders, focus, optimizer slots and fitted
        alternative models load instead of being silently ignored.
        """
        phase = "DYNAMIC_SUITE_INIT_V20"

        try:
            truthy = ("1", "true", "yes", "on")
            resume_requested = (
                os.environ.get("OMNI_RESUME", "").strip().lower() in truthy
            )
            fresh_requested = (
                os.environ.get("OMNI_FRESH_RUN", "").strip().lower() in truthy
            )

            if resume_requested:
                if fresh_requested:
                    logger.warning(
                        f"[{phase}] ⚠️ OMNI_FRESH_RUN and OMNI_RESUME are both set. "
                        f"OMNI_RESUME takes precedence: full checkpoint state "
                        f"will be restored."
                    )
                os.environ["OMNI_FRESH_RUN"] = "0"
            else:
                if not fresh_requested:
                    os.environ.setdefault("OMNI_FRESH_RUN", "1")

            self.hw_profile = HWPROFILE
            self.gpu_config = GPU_CONFIG
            logger.info(
                f"[{phase}] 🖥️ Hardware: {self.hw_profile.cpu_name} | "
                f"{'✅ GPU' if self.hw_profile.has_gpu else '💻 CPU-only'}"
            )

            dynamic_params = DynamicHyperparameters()
            self.dynamic_params = dynamic_params

            self.epochs = dynamic_params.base_epochs
            self.learning_rate = dynamic_params.base_learning_rate
            self.focal_gamma = dynamic_params.focal_gamma
            self.temperature_init = dynamic_params.temperature_init
            self.diversity_weight = dynamic_params.diversity_weight
            self.augment_factor = dynamic_params.augment_factor
            self.patience = int(
                dynamic_params.base_epochs * dynamic_params.patience_ratio
            )
            self.batch_size = dynamic_params.optimal_batch_size
            self.num_workers = self.hw_profile.optimal_workers
            self._USER_MIN_EPOCH_BEFORE_REPLACE = 15
            self._USER_REPLACEMENT_INTERVAL_EPOCHS = 5

            self.IncrementalPCA = dynamic_params.enable_ipca
            self.ipca_n_components = int(
                dynamic_params.n_features
                * dynamic_params.ipca_n_components_ratio
            )
            self.ipca_feature_groups = dynamic_params.ipca_feature_groups
            self.ipca_variance_ratio = dynamic_params.ipca_variance_ratio
            self.ipca_min_components = dynamic_params.ipca_min_components
            self.ipca_use_mi_ranking = False

            self.sharpe_threshold = dynamic_params.min_sharpe_for_edge
            self.win_rate_threshold = dynamic_params.min_win_rate_for_edge
            self.dir_acc_threshold = dynamic_params.min_dir_acc_for_edge
            self.max_drawdown_threshold = dynamic_params.max_drawdown_for_edge
            self.min_trades_threshold = dynamic_params.min_trades_for_edge

            self.scalers_loaded = False
            self.scaler_params = None
            self.class_frequencies = {}
            self.train_class_counts = {}
            self._targets_cache = {}
            self.regime_signal = None

            self.enable_data_augmentation = True
            self.verbose = 1

            self.cache_limit_mb = self.hw_profile.cache_size_limit_mb
            self.prefetch_buffer_size = self.hw_profile.prefetch_buffer_size

            logger.info("")
            logger.info("=" * 80)
            logger.info(
                f"[{phase}] ✅ DYNAMIC LEARNABILITY SUITE v20.0 INITIALIZED"
            )
            logger.info("=" * 80)
            logger.info(f"[{phase}]    • Epochs: {self.epochs}")
            logger.info(
                f"[{phase}]    • Learning Rate: {self.learning_rate:.2e}"
            )
            logger.info(f"[{phase}]    • Batch Size: {self.batch_size}")
            logger.info(f"[{phase}]    • Focal Gamma: {self.focal_gamma}")
            logger.info(
                f"[{phase}]    • Temperature: {self.temperature_init}"
            )
            logger.info(f"[{phase}]    • Augment Factor: {self.augment_factor}")
            logger.info(f"[{phase}]    • IPCA Enabled: {self.IncrementalPCA}")
            logger.info(
                f"[{phase}]    • IPCA Components: {self.ipca_n_components}"
            )
            logger.info(
                f"[{phase}]    • Edge Sharpe Threshold: {self.sharpe_threshold}"
            )
            logger.info(
                f"[{phase}]    • Edge Win Rate Threshold: "
                f"{self.win_rate_threshold:.1%}"
            )
            logger.info(
                f"[{phase}]    • Edge Dir Acc Threshold: "
                f"{self.dir_acc_threshold:.1%}"
            )
            logger.info("=" * 80)
            logger.info("")

        except Exception as exc:
            logger.error(f"[{phase}] ❌ CRITICAL INITIALIZATION FAILED: {exc}")
            logger.error(traceback.format_exc())
            raise
           
    def _get_class_weights(self, y_train_dict: dict) -> dict:
        """
        CLASS WEIGHTS v19.4 — FIXED: adaptive_max_weight always defined
        ✅ FIX: adaptive_max_weight defined before use in all code paths
        ✅ FIX: Missing classes handling with safe fallback
        """
        import numpy as np
        from datetime import datetime
        from collections import Counter

        phase = "GET_CLASS_WEIGHTS_v19_4"
        CLASSIFICATION_TARGETS = list(CLASS_TARGETS)            # ← از globals
        N_CLASSES_PER_TARGET   = dict(N_CLASSES_DEFAULT)        # ← از globals

        SQRT_SCALE_FACTOR = 0.5
        MIN_WEIGHT = 0.4
        MAX_WEIGHT_BASE = 4.0

        logger.info(f"\n{'═' * 80}")
        logger.info(f"[{phase}] 📊 CLASS WEIGHTS CALCULATION v19.4")
        logger.info(f"{'═' * 80}")
        logger.info(f"   پارامترها:")
        logger.info(f"      • فرمول: weight = {SQRT_SCALE_FACTOR} × √(max_freq / cls_freq)")
        logger.info(f"      • محدوده وزن: [{MIN_WEIGHT}, {MAX_WEIGHT_BASE}] قبل از نرمالایز")
        logger.info(f"      • نرمالایز: میانگین weights = 1.0")
        logger.info(f"{'═' * 80}")

        class_weights = {}
        overall_stats  = {}

        for target_name in CLASSIFICATION_TARGETS:
            try:
                # ── STEP 1: LOAD AND VALIDATE DATA ──────────────────────
                if target_name not in y_train_dict or y_train_dict[target_name] is None:
                    logger.warning(f"[{phase}] ⚠️ '{target_name}' not found → skipping")
                    continue

                y_raw     = y_train_dict[target_name]
                n_classes = N_CLASSES_PER_TARGET.get(target_name, 5)

                if len(y_raw.shape) > 1 and y_raw.shape[1] > 1:
                    y = np.argmax(y_raw, axis=1).astype(np.int64)
                    logger.info(f"[{phase}] 📊 '{target_name}': from one-hot (shape={y_raw.shape})")
                else:
                    y = y_raw.flatten()
                    y = y[~np.isnan(y.astype(float))]
                    y = y.astype(np.int64)
                    logger.info(f"[{phase}] 📊 '{target_name}': class indices (shape={y.shape})")

                if len(y) == 0:
                    logger.error(f"[{phase}] ❌ '{target_name}': empty after cleaning")
                    continue

                n_samples                    = len(y)
                unique_classes, counts       = np.unique(y, return_counts=True)
                freqs                        = counts / n_samples

                original_counts: dict = {int(cls): int(cnt)
                                         for cls, cnt in zip(unique_classes, counts)}

                all_possible_classes = set(range(n_classes))
                observed_classes     = set(unique_classes.tolist())
                missing_classes      = all_possible_classes - observed_classes

                max_freq        = freqs.max()
                min_freq        = max(freqs.min(), 1e-6)
                imbalance_ratio = max_freq / min_freq

                # 🔥 FIX: adaptive_max_weight defined BEFORE any use
                adaptive_max_weight = min(MAX_WEIGHT_BASE, np.sqrt(imbalance_ratio) * 1.5)
                if target_name == "trend_strength":
                    adaptive_max_weight = min(adaptive_max_weight, 2.5)
                    logger.warning(f"[{phase}] 🔥 trend_strength detected → adaptive_max_weight capped at 2.5")

                logger.info(f"\n{'─' * 70}")
                logger.info(f"[{phase}] 🎯 TARGET: {target_name.upper()}")
                logger.info(f"{'─' * 70}")
                logger.info(f"   آمار کلی:")
                logger.info(f"      • تعداد نمونه‌ها          : {n_samples:,}")
                logger.info(f"      • کلاس‌های موجود          : {len(observed_classes)}/{n_classes}")
                logger.info(f"      • کلاس‌های missing         : {list(missing_classes) if missing_classes else 'هیچ'}")
                logger.info(f"      • max_freq                 : {max_freq:.2%}")
                logger.info(f"      • min_freq                 : {min_freq:.2%}")
                logger.info(f"      • نسبت عدم توازن           : {imbalance_ratio:.2f}x")
                logger.info(f"      • adaptive max weight      : {adaptive_max_weight:.3f}")

                # ── STEP 2: WEIGHT PER CLASS ─────────────────────────────
                target_weights = {}
                logger.info(f"\n   {'─' * 65}")
                logger.info(f"   {'Class':^8} {'Count':^12} {'Frequency':^12} "
                            f"{'Raw Weight':^14} {'Clipped':^14} {'Status':^12}")
                logger.info(f"   {'─' * 65}")

                for cls_id, cnt, freq in zip(unique_classes, counts, freqs):
                    try:
                        raw_weight = (
                            n_samples /
                            (n_classes * max(cnt, 1))
                        ) ** SQRT_SCALE_FACTOR

                        # 🔥 FIX: adaptive_max_weight is DEFINED here
                        clipped_weight = np.clip(
                            raw_weight,
                            MIN_WEIGHT,
                            adaptive_max_weight
                        )

                        if freq < 0.05:
                            status = "🔴 VERY RARE"
                        elif freq < 0.10:
                            status = "🟡 RARE"
                        elif freq > 0.40:
                            status = "🟠 MAJORITY"
                        else:
                            status = "✅ BALANCED"

                        logger.info(
                            f"   │ {cls_id:^6d} │ "
                            f"{cnt:>10,d} │ "
                            f"{freq:>10.2%} │ "
                            f"{raw_weight:>12.4f} │ "
                            f"{clipped_weight:>12.4f} │ "
                            f"{status:^12} │"
                        )

                        target_weights[int(cls_id)] = float(clipped_weight)

                    except Exception as cls_err:
                        logger.error(f"[{phase}] ❌ Weight calculation failed for class {cls_id}: {cls_err}")
                        target_weights[int(cls_id)] = 1.0

                # ── STEP 3: MISSING CLASSES ──────────────────────────────
                # 🔥 FIX: adaptive_max_weight is DEFINED here
                for missing_cls in missing_classes:
                    missing_weight = adaptive_max_weight * 0.8
                    target_weights[int(missing_cls)] = float(missing_weight)
                    logger.info(
                        f"   │ {missing_cls:^6d} │ {'N/A':>10} │ {'0.00%':>10} │ "
                        f"{'N/A':>12} │ {missing_weight:>12.4f} │ 🔴 MISSING │"
                    )

                logger.info(f"   {'─' * 65}")

                # ── STEP 4: NORMALIZE (mean = 1.0) ───────────────────────
                w_values       = list(target_weights.values())
                n_classes_total = len(target_weights)
                total_weight   = sum(w_values)

                if total_weight > 0:
                    target_mean          = total_weight / n_classes_total
                    normalization_factor = 1.0 / target_mean

                    logger.info(f"\n   📊 نرمالایز:")
                    logger.info(f"      • میانگین قبل: {target_mean:.4f}")
                    logger.info(f"      • فاکتور    : {normalization_factor:.4f}")

                    for cls in target_weights:
                        target_weights[cls] = float(
                            np.clip(
                                target_weights[cls] * normalization_factor,
                                MIN_WEIGHT,
                                adaptive_max_weight * 1.2
                            )
                        )

                # ── STEP 5: FINAL SUMMARY ────────────────────────────────
                final_weights_list = list(target_weights.values())
                final_mean         = float(np.mean(final_weights_list))
                final_min          = float(min(final_weights_list))
                final_max          = float(max(final_weights_list))
                weight_ratio       = final_max / max(final_min, 1e-6)

                logger.info(f"\n   {'─' * 65}")
                logger.info(f"   {'Class':^8} {'Weight':^14} {'Original Count':^20} {'Effective Count':^16}")
                logger.info(f"   {'─' * 65}")

                effective_samples_dict = {}
                for cls_id, weight in sorted(target_weights.items()):
                    orig_cnt     = original_counts.get(cls_id, 0)
                    effective_cnt = int(orig_cnt * weight)
                    effective_samples_dict[int(cls_id)] = effective_cnt
                    logger.info(
                        f"   │ {cls_id:^6d} │ {weight:>12.4f} │ "
                        f"{orig_cnt:>18,d} │ {effective_cnt:>14,d} │"
                    )

                logger.info(f"   {'─' * 65}")

                is_balanced    = weight_ratio < 5.0
                balance_status = "✅ BALANCED" if is_balanced else "⚠️ STILL IMBALANCED"

                logger.info(f"\n   📊 خلاصه نهایی برای {target_name}:")
                logger.info(f"      • وزن‌های نهایی  : {target_weights}")
                logger.info(f"      • میانگین وزن   : {final_mean:.4f}")
                logger.info(f"      • محدوده        : [{final_min:.4f}, {final_max:.4f}]")
                logger.info(f"      • نسبت max/min  : {weight_ratio:.2f}x")
                logger.info(f"      • وضعیت         : {balance_status}")
                logger.info(f"      • Effective      : {effective_samples_dict}")

                class_weights[target_name] = target_weights
                overall_stats[target_name] = {
                    'n_samples'           : n_samples,
                    'n_classes_observed'  : len(observed_classes),
                    'n_classes_total'     : n_classes,
                    'missing_classes'     : list(missing_classes),
                    'imbalance_ratio'     : float(imbalance_ratio),
                    'weight_ratio'        : float(weight_ratio),
                    'min_weight'          : final_min,
                    'max_weight'          : final_max,
                    'mean_weight'         : final_mean,
                    'is_balanced'         : is_balanced,
                    'effective_samples'   : effective_samples_dict,
                    'class_weights'       : target_weights.copy(),
                    'original_counts'     : original_counts,
                }

            except Exception as e:
                logger.error(f"[{phase}] ❌ Failed for '{target_name}': {e}", exc_info=True)
                continue

        # ── STEP 6: FINAL REPORT ─────────────────────────────────────────
        logger.info(f"\n{'═' * 80}")
        logger.info(f"[{phase}] 📊 FINAL CLASS WEIGHTS SUMMARY")
        logger.info(f"{'═' * 80}")

        for target_name, weights in class_weights.items():
            logger.info(f"\n   🎯 {target_name.upper()}:")
            logger.info(f"      ┌─────────┬──────────┬──────────┬────────────┐")
            logger.info(f"      │  Class  │  Weight  │ Original │ Effective  │")
            logger.info(f"      ├─────────┼──────────┼──────────┼────────────┤")

            stats        = overall_stats.get(target_name, {})
            eff_samples  = stats.get('effective_samples', {})
            orig_counts  = stats.get('original_counts', {})

            for cls, weight in sorted(weights.items()):
                orig_cnt = orig_counts.get(cls, 0)
                eff_cnt  = eff_samples.get(cls, 0)
                logger.info(
                    f"      │   {cls:3d}   │  {weight:6.3f}  │  {orig_cnt:6,d}  │  {eff_cnt:6,d}   │"
                )

            logger.info(f"      └─────────┴──────────┴──────────┴────────────┘")

        # 🔥 FIX: Use adaptive_max_weight from last processed target or fallback
        last_target_stats = overall_stats.get(list(overall_stats.keys())[-1], {}) if overall_stats else {}
        fallback_weight = last_target_stats.get('max_weight', MAX_WEIGHT_BASE) * 0.8

        all_missing = []
        for target_name, stats in overall_stats.items():
            if stats.get('missing_classes'):
                all_missing.append(f"{target_name}: {stats['missing_classes']}")

        if all_missing:
            logger.warning(f"\n{'⚠️' * 40}")
            logger.warning(f"[{phase}] ⚠️ کلاس‌های زیر در training data وجود ندارند:")
            for info in all_missing:
                logger.warning(f"   • {info}")
            logger.warning(f"   weight پیش‌فرض: {fallback_weight:.3f}")
            logger.warning(f"{'⚠️' * 40}")

        logger.info(f"\n{'═' * 80}")
        logger.info(f"[{phase}] ✅ محاسبه weights برای {len(class_weights)} تارگت")
        logger.info(f"{'═' * 80}\n")

        return class_weights
        
    def _load_scalers(self) -> bool:
        """
        ✅ FIXED VERSION v2.0 - Load ONLY target scalers for evaluation
        ✅ Feature scalers are NOT needed for target denormalization
        ✅ Prevents mixing features with targets
        """
        if self.scalers_loaded:
            return True

        try:
            from core.global_method import get_active_symbol_timeframe
            from main import sum_folds as fold
            symbol, timeframe = get_active_symbol_timeframe()

            # ============================================================
            # 🔥 CRITICAL FIX: Load ONLY TARGET SCALERS
            # We don't need feature scalers for target denormalization!
            # ============================================================
            target_scalers = load_scalers_from_path(
                scaler_type='target',
                auto_detect=True,
                verbose=True
            )

            # Initialize scaler_params with ONLY target scalers
            self.scaler_params = {}

            # Add target scalers only
            if target_scalers:
                for key, value in target_scalers.items():
                    if not key.startswith('_'):
                        self.scaler_params[key] = value

                # Preserve metadata for compatibility
                if '_metadata' in target_scalers:
                    self.scaler_params['_metadata'] = target_scalers['_metadata']

            # Log what we loaded (should be ONLY 5 targets)
            regression_targets = [k for k, v in self.scaler_params.items()
                                  if isinstance(v, dict) and v.get('target_type') == 'regression']
            classification_targets = [k for k, v in self.scaler_params.items()
                                      if isinstance(v, dict) and v.get('target_type') == 'classification']

            logger.info(f"📊 Loaded target scalers: {len(self.scaler_params)} total")
            logger.info(f"   • Regression targets: {regression_targets}")
            logger.info(f"   • Classification targets: {classification_targets}")

            # Validation: Should have exactly 1 regression and 4 classification targets
            # 🔥 FIX: از globals — تعداد تارگت‌ها هرگز hardcode نمی‌شود
            expected_regression     = list(REGRESSION_TARGETS)   # ← از globals
            expected_classification = list(CLASS_TARGETS)        # ← از globals

            missing_regression     = [t for t in expected_regression if t not in regression_targets]
            missing_classification = [t for t in expected_classification if t not in classification_targets]

            if missing_regression or missing_classification:
                logger.warning(
                    f"⚠️ Missing targets - Regression: {missing_regression}, Classification: {missing_classification}")
                # Don't fail, but log warning

            self.scalers_loaded = True
            return True

        except Exception as e:
            logger.error(f"❌ Failed to load target scalers: {e}")
            import traceback
            logger.error(traceback.format_exc())
            return False

    async def _load_all_targets_from_source(
        self, split_type: str, fold: int
    ) -> Dict[str, np.ndarray]:
        """
        🔥 لود ALL 5 TARGETS از فایل‌های اصلی sequenced.

        🔥 v1.1 (FIX BUG-03): حذف وابستگی به pandas — استفاده از duck-typing
                             (`hasattr(arr, 'values')`) به‌جای `isinstance(arr, pd.Series)`.
        ✅ بدون placeholder — اگر فایل نباشد، خطای روشن می‌دهد.
        ✅ با کش برای جلوگیری از لود مکرر.
        """
        from core.global_method import (
            get_active_symbol_timeframe,
            universal_load,
        )

        phase = f"LOAD_TARGETS_{split_type}"
        cache_key = f"{split_type}_{fold}"

        # بررسی کش
        if cache_key in self._targets_cache:
            logger.info(f"[{phase}] ✅ Using cached targets")
            return self._targets_cache[cache_key].copy()

        try:
            symbol, timeframe = get_active_symbol_timeframe()

            # ── STEP 1: لود داده sequenced ──
            logger.info(
                f"[{phase}] 📥 Loading sequenced data for {split_type}..."
            )
            X_data, y_data = await universal_load(
                data_type="sequenced",
                symbol=symbol,
                timeframe=timeframe,
                fold=fold,
                split_type=split_type,
                lookback=200,
                multi_output=True,
            )

            if X_data is None or y_data is None:
                error_msg = (
                    f"[{phase}] ❌ Failed to load sequenced data for "
                    f"{split_type}"
                )
                logger.error(error_msg)
                raise RuntimeError(error_msg)

            logger.info(f"[{phase}] ✅ Loaded X shape: {X_data.shape}")
            logger.info(
                f"[{phase}] ✅ Loaded y keys: "
                f"{list(y_data.keys()) if y_data else 'None'}"
            )

            # ── STEP 2: استخراج همه تارگت‌ها ──
            REQUIRED_TARGETS = list(OUTPUT_ORDER)
            result: Dict[str, np.ndarray] = {}

            for target in REQUIRED_TARGETS:
                arr = None

                if y_data and target in y_data:
                    arr = y_data[target]
                    logger.info(f"[{phase}] ✅ Found '{target}' directly")
                else:
                    for alias in TARGET_ALIASES.get(target, []):
                        if y_data and alias in y_data:
                            arr = y_data[alias]
                            logger.info(
                                f"[{phase}] ✅ Found '{target}' via alias "
                                f"'{alias}'"
                            )
                            break

                if arr is None:
                    error_msg = (
                        f"[{phase}] ❌ CRITICAL: Target '{target}' not found "
                        f"in {split_type} data!\n"
                        f"   Available keys: "
                        f"{list(y_data.keys()) if y_data else 'None'}\n"
                        f"   This indicates corrupted or incomplete "
                        f"sequenced files."
                    )
                    logger.error(error_msg)
                    raise KeyError(error_msg)

                # ── تبدیل به numpy با duck-typing ──
                # 🔥 FIX BUG-03: از hasattr استفاده می‌کنیم نه isinstance(pd.Series)
                if isinstance(arr, (np.ndarray, list)):
                    arr = np.array(arr, dtype=np.float32)
                elif hasattr(arr, "values") and hasattr(arr.values, "astype"):
                    # شبیه pandas.Series (یا هر آبجکت با .values)
                    arr = np.asarray(arr.values, dtype=np.float32)
                else:
                    arr = np.asarray(arr, dtype=np.float32)

                arr = np.nan_to_num(
                    arr, nan=0.0, posinf=0.0, neginf=0.0
                )
                result[target] = arr
                logger.info(
                    f"[{phase}] 📊 '{target}': shape={arr.shape}, "
                    f"dtype={arr.dtype}"
                )

            # ── STEP 3: همترازی طول همه تارگت‌ها با X ──
            n_samples_X = X_data.shape[0]

            for target in REQUIRED_TARGETS:
                arr = result[target]
                if arr.shape[0] > n_samples_X:
                    result[target] = arr[:n_samples_X]
                    logger.info(
                        f"[{phase}] 📊 Trimmed '{target}' to "
                        f"{n_samples_X} samples"
                    )
                elif arr.shape[0] < n_samples_X:
                    error_msg = (
                        f"[{phase}] ❌ Target '{target}' has "
                        f"{arr.shape[0]} samples, X has {n_samples_X}"
                    )
                    logger.error(error_msg)
                    raise ValueError(error_msg)

            # ذخیره در کش
            self._targets_cache[cache_key] = result.copy()

            logger.info(
                f"[{phase}] ✅ All {len(REQUIRED_TARGETS)} targets loaded "
                f"successfully"
            )
            return result

        except Exception as e:
            logger.error(
                f"[{phase}] ❌ Failed to load targets: {e}"
            )
            logger.error(traceback.format_exc())
            raise
            
    async def _prepare_train_targets(self, fold: int) -> Dict[str, np.ndarray]:
        """
        🔥 بارگذاری تارگت‌های TRAIN - با class frequencies برای هر کلاس
        ✅ class indices (NOT one-hot) برای محاسبه class_frequencies
        ✅ FIX: returns both class indices AND one-hot for compatibility
        """
        from core.global_method import get_active_symbol_timeframe, universal_load
        
        try:
            symbol, timeframe = get_active_symbol_timeframe()
            
            X_data, y_data = await universal_load(
                data_type="sequenced",
                symbol=symbol,
                timeframe=timeframe,
                fold=fold,
                split_type="train",
                lookback=200,
                multi_output=True
            )
            
            if X_data is None or y_data is None:
                raise RuntimeError(f"Failed to load sequenced data for train")
            
            n_samples = X_data.shape[0]
            result = {}
            
            # ============================================================
            # 🔥 CRITICAL: Store class frequencies for classification targets
            # ============================================================
            N_CLASSES = dict(N_CLASSES_DEFAULT)
            
            REQUIRED_TARGETS = list(OUTPUT_ORDER)
            
            for target in REQUIRED_TARGETS:
                arr = y_data.get(target)
                if arr is None:
                    # 🔥 FIX: پشتیبانی alias (سازگار با _load_all_targets_from_source)
                    for alias in TARGET_ALIASES.get(target, []):
                        if alias in y_data and y_data[alias] is not None:
                            arr = y_data[alias]
                            logger.info(
                                f"[PREPARE_TRAIN] '{target}' resolved via alias '{alias}'"
                            )
                            break
                if arr is None:
                    raise KeyError(f"Target '{target}' not found in data")
                
                arr = np.array(arr, dtype=np.float32)
                arr = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)
                
                if len(arr) > n_samples:
                    arr = arr[:n_samples]
                
                if target == 'price_return':
                    if arr.ndim == 1:
                        arr = arr.reshape(-1, 1)
                    result[target] = arr  # Keep as is for regression
                    # Also store as one-hot (same for regression)
                    result[f"{target}_onehot"] = arr.copy()
                else:
                    n_classes = N_CLASSES.get(target, 5)
                    
                    # Convert to class indices
                    if arr.ndim == 2 and arr.shape[1] > 1:
                        class_indices = np.argmax(arr, axis=1)
                    else:
                        class_indices = arr.flatten().astype(np.int32)
                    
                    class_indices = np.clip(class_indices, 0, n_classes - 1)
                    
                    # 🔥 CRITICAL: Store as class indices (NOT one-hot) for trainer
                    result[target] = class_indices.astype(np.int32)
                    
                    # 🔥 CRITICAL: Store as one-hot for DynamicHyperparameterFactory
                    result[f"{target}_onehot"] = tf.keras.utils.to_categorical(
                        class_indices, num_classes=n_classes
                    ).astype(np.float32)
                    
                    # 🔥 CRITICAL: Store class frequencies for balancer
                    unique, counts = np.unique(class_indices, return_counts=True)
                    freq_dict = {int(u): int(c) for u, c in zip(unique, counts)}
                    
                    # Store in instance for later use
                    if not hasattr(self, 'class_frequencies'):
                        self.class_frequencies = {}
                    self.class_frequencies[target] = freq_dict
                    
                    if not hasattr(self, 'train_class_counts'):
                        self.train_class_counts = {}
                    self.train_class_counts[target] = freq_dict
                    
                    logger.info(f"[PREPARE_TRAIN] {target}: class distribution {freq_dict}")
            
            logger.info(f"[PREPARE_TRAIN] ✅ Loaded {len(REQUIRED_TARGETS)} targets for training")
            logger.info(f"[PREPARE_TRAIN]    Keys available: {list(result.keys())}")
            
            return result
            
        except Exception as e:
            logger.error(f"❌ Failed to load train targets: {e}")
            raise
            
    async def _prepare_val_targets(self, fold: int) -> Dict[str, np.ndarray]:
        """
        🔥 بارگذاری تارگت‌های VALIDATION از منبع اصلی
        ✅ بدون placeholder - داده واقعی از فایل
        """
        return await self._load_all_targets_from_source(split_type="val", fold=fold)

    async def _prepare_test_targets(self, fold: int) -> Dict[str, np.ndarray]:
        """
        🔥 بارگذاری تارگت‌های TEST از منبع اصلی
        ✅ بدون placeholder - داده واقعی از فایل
        """
        return await self._load_all_targets_from_source(split_type="test", fold=fold)
        
    def _load_latest_checkpoint(
        self, model, checkpoint_dir, model_name, force_start_epoch=None
    ) -> tuple:
        """
        _LOAD_LATEST_CHECKPOINT v18.0 — WEIGHTS + TRAINER STATE + OPTIMIZER.

        🔥 v18.0 (نسبت به v17.0):
          • پس از موفقیت بارگذاری وزن‌ها، `_load_trainer_state_and_optimizer`
            صدا زده می‌شود تا:
              - log_vars, class_weights, task_loss_weights, head_grad_scales
                (SimpleMultiTaskTrainer)
              - Adam/AdamW slots (m, v)
              - paused_heads, focus_frozen
              - task_losses_state (tau, ordinal_weight, prior_match_weight)
            بازیابی شوند.
          • اگر state ناسازگار/قدیمی باشد، فقط WARNING ثبت می‌شود و
            آموزش با momentum صفر ادامه می‌یابد (بدون کرش).

        🔥 حفظ‌شده از v17.0:
          • forced_ep>0 = resume با epoch override
          • forced_ep=0 = fresh start
          • Fresh-run quarantine
          • Strict weights loading (بدون skip_mismatch)
          • صرفاً وقتی OMNI_RESUME=1 یا forced_ep>0 باشد، اسکن/بارگذاری
            انجام می‌شود.
        """
        import re
        import json
        import shutil
        from datetime import datetime as _dt

        phase = "LOAD_LATEST_CHECKPOINT_V18"

        # ── ۰) تشخیص حالت ──
        fresh_env = os.environ.get("OMNI_FRESH_RUN", "").strip() in (
            "1", "true", "yes", "on"
        )
        resume_env = os.environ.get("OMNI_RESUME", "").strip() in (
            "1", "true", "yes", "on"
        )

        forced_ep_override: Optional[int] = None
        if force_start_epoch is not None:
            try:
                forced_ep = int(force_start_epoch)
            except (TypeError, ValueError):
                forced_ep = None

            if forced_ep == 0:
                fresh_env = True
                logger.info(
                    f"[{phase}] 🔧 force_start_epoch=0 → forced FRESH start"
                )
            elif forced_ep is not None and forced_ep > 0:
                forced_ep_override = int(forced_ep)
                resume_env = True
                logger.info(
                    f"[{phase}] 🔧 force_start_epoch={forced_ep} → "
                    f"forces RESUME with epoch override"
                )

        # ── ۱) Fresh-run quarantine ──
        if fresh_env and not resume_env:
            if os.path.isdir(checkpoint_dir):
                ts = _dt.now().strftime("%Y%m%d_%H%M%S")
                qdir = os.path.join(
                    os.path.dirname(checkpoint_dir.rstrip(os.sep)),
                    f"_quarantine_{ts}",
                )
                try:
                    os.makedirs(qdir, exist_ok=True)
                    target = os.path.join(
                        qdir, os.path.basename(checkpoint_dir)
                    )
                    shutil.move(checkpoint_dir, target)
                    logger.warning(
                        f"[{phase}] 🧹 FRESH RUN — checkpoint dir "
                        f"quarantined:\n     {checkpoint_dir}\n  →  {target}"
                    )
                except Exception as qe:
                    logger.error(
                        f"[{phase}] ⚠️ quarantine failed ({qe}); "
                        f"continuing fresh"
                    )
            os.makedirs(checkpoint_dir, exist_ok=True)
            logger.warning(
                f"[{phase}] 🆕 FRESH START — no checkpoint scan, no "
                f"weights load."
            )
            return model, 0

        # ── ۲) اگر نه Fresh و نه Resume → fresh ──
        if not resume_env:
            os.makedirs(checkpoint_dir, exist_ok=True)
            logger.info(
                f"[{phase}] ℹ️ OMNI_RESUME not set → starting fresh "
                f"(no scan)."
            )
            return model, 0

        # ── ۳) Resume صریح ──
        if not os.path.isdir(checkpoint_dir):
            if forced_ep_override is not None:
                logger.warning(
                    f"[{phase}] forced_ep={forced_ep_override} but dir "
                    f"missing — returning fresh weights at forced epoch"
                )
                return model, int(forced_ep_override)
            logger.info(
                f"[{phase}] resume requested but dir missing — fresh."
            )
            return model, 0

        def _target_base():
            t = model
            if hasattr(model, "base_model") and model.base_model is not None:
                t = model.base_model
            if t is None:
                return None
            try:
                dummy = tf.zeros(
                    (
                        1,
                        int(getattr(self.dynamic_params, "lookback", 64)),
                        int(getattr(self.dynamic_params, "n_features", 50)),
                    ),
                    dtype=tf.float32,
                )
                _ = t(dummy, training=False)
            except Exception as e:
                logger.warning(f"[{phase}] could not build: {e}")
            return t

        pattern_w = re.compile(r"^epoch_(\d+)_base_weights\.weights\.h5$")
        pattern_k = re.compile(r"^epoch_(\d+)\.keras$")

        w_cands = []
        k_cands = []
        try:
            for fn in os.listdir(checkpoint_dir):
                mw = pattern_w.match(fn)
                if mw:
                    w_cands.append(
                        (int(mw.group(1)), os.path.join(checkpoint_dir, fn))
                    )
                mk = pattern_k.match(fn)
                if mk:
                    k_cands.append(
                        (int(mk.group(1)), os.path.join(checkpoint_dir, fn))
                    )
        except Exception as e:
            logger.warning(f"[{phase}] dir scan failed: {e}")

        w_cands.sort(key=lambda x: x[0], reverse=True)
        k_cands.sort(key=lambda x: x[0], reverse=True)

        tracker_ep = 0
        tracker_path = os.path.join(checkpoint_dir, "last_epoch.txt")
        if os.path.exists(tracker_path):
            try:
                with open(tracker_path, "r", encoding="utf-8") as f:
                    tracker_ep = int(json.load(f).get("last_epoch", 0))
            except Exception:
                pass

        last_ep = tracker_ep
        if w_cands:
            last_ep = max(last_ep, w_cands[0][0])
        if k_cands:
            last_ep = max(last_ep, k_cands[0][0])

        base = _target_base()
        if base is None:
            if forced_ep_override is not None:
                logger.error(
                    f"[{phase}] forced_ep={forced_ep_override} but target "
                    f"base not resolvable — returning fresh weights at "
                    f"forced epoch"
                )
                return model, int(forced_ep_override)
            logger.error(
                f"[{phase}] target base not resolvable — aborting resume."
            )
            return model, 0

        # STRICT load — بدون skip_mismatch
        loaded = False
        for ep, path in w_cands:
            try:
                base.load_weights(path)
                logger.info(
                    f"[{phase}] ✅ STRICT weights loaded: "
                    f"{os.path.basename(path)} (epoch={ep})"
                )
                loaded = True
                break
            except Exception as le:
                logger.warning(
                    f"[{phase}] strict load rejected "
                    f"{os.path.basename(path)}: {str(le)[:160]} — trying "
                    f"next candidate"
                )

        if not loaded:
            if forced_ep_override is not None:
                logger.warning(
                    f"[{phase}] forced_ep={forced_ep_override} but no "
                    f"compatible weights found — starting with FRESH "
                    f"weights at forced epoch {forced_ep_override}"
                )
                return model, int(forced_ep_override)
            logger.error(
                f"[{phase}] ❌ resume requested but no compatible weights "
                f"found. Starting fresh to avoid silently corrupted state."
            )
            return model, 0

        # 🔥 v18.0: trainer + optimizer state
        try:
            _loaded_state = _load_trainer_state_and_optimizer(
                checkpoint_dir=checkpoint_dir,
                trainer=model,
                force_fresh=False,
            )
            if _loaded_state:
                logger.info(
                    f"[{phase}] ✅ trainer + optimizer state restored "
                    f"(log_vars, class_weights, momentum)"
                )
        except Exception as e:
            logger.warning(
                f"[{phase}] trainer/optimizer state restore failed "
                f"(weights loaded but momentum lost): {e}"
            )

        # ── ۴) تعیین start_epoch نهایی ──
        if forced_ep_override is not None:
            logger.warning(
                f"[{phase}] ▶ RESUMING with EPOCH OVERRIDE: "
                f"weights_epoch={last_ep}, start_epoch={forced_ep_override}"
            )
            return model, int(forced_ep_override)

        logger.info(f"[{phase}] ▶ RESUMING from epoch {last_ep}")
        return model, int(last_ep)
        
    def _save_checkpoint_tracker(self, checkpoint_dir: str, epoch: int, metrics: Dict = None):
        """ذخیره وضعیت epoch جاری برای ادامه بعدی"""
        tracker_path = os.path.join(checkpoint_dir, "last_epoch.txt")
        try:
            tracker_data = {
                'last_epoch': epoch,
                'timestamp': datetime.now().isoformat(),
                'metrics': metrics or {}
            }
            with open(tracker_path, 'w') as f:
                json.dump(tracker_data, f, indent=2)
        except Exception as e:
            logger.warning(f"   ⚠️ Could not save tracker: {e}")


    def _create_multi_output_dataset(
        self,
        X: np.ndarray,
        y_dict: Dict[str, np.ndarray],
        batch_size: int,
        class_weights_dict: Dict[str, Dict[int, float]] = None,
        is_validation: bool = False,
    ) -> tf.data.Dataset:
        """
        CREATE MULTI-OUTPUT DATASET v24.0 - FIXED: Keeps class indices for validation
        ✅ Now consistently returns class indices for classification targets
        """
        phase = "MULTI_OUTPUT_DATASET_v24"

        N_CLASSES = dict(N_CLASSES_DEFAULT) 

        OUTPUT_ORDER = list(OUTPUT_ORDER)    # ← از globals (7 آیتم)

        try:
            if X is None or len(X) == 0:
                raise ValueError(f"[{phase}] X is None or empty")
            if y_dict is None:
                raise ValueError(f"[{phase}] y_dict is None")

            n_samples = X.shape[0]

            logger.info(f"[{phase}] 📊 Creating {'VALIDATION' if is_validation else 'TRAIN'} dataset")
            logger.info(f"[{phase}]    n_samples={n_samples}  batch={batch_size}")

            y_tensors = []
            sw_tensors = []

            for target_name in OUTPUT_ORDER:
                if target_name not in y_dict or y_dict[target_name] is None:
                    logger.warning(f"[{phase}] '{target_name}' missing → using zeros placeholder")
                    if target_name == 'price_return':
                        y_arr = np.zeros((n_samples, 1), dtype=np.float32)
                        sw_arr = np.ones(n_samples, dtype=np.float32)
                    else:
                        # Use class indices for consistency
                        y_arr = np.zeros(n_samples, dtype=np.int32)
                        sw_arr = np.ones(n_samples, dtype=np.float32)
                else:
                    y_arr = y_dict[target_name]
                    if not isinstance(y_arr, np.ndarray):
                        y_arr = np.array(y_arr, dtype=np.float32)
                    
                    y_arr = np.nan_to_num(y_arr.astype(np.float32), nan=0.0, posinf=0.0, neginf=0.0)
                    
                    if len(y_arr) > n_samples:
                        y_arr = y_arr[:n_samples]
                    
                    if target_name == 'price_return':
                        if y_arr.ndim == 1:
                            y_arr = y_arr.reshape(-1, 1)
                        sw_arr = np.ones(n_samples, dtype=np.float32)
                    else:
                        nc = N_CLASSES.get(target_name, 5)
                        
                        # 🔥 FIX: ALWAYS keep as class indices for consistency
                        # The trainer's test_step will handle conversion internally
                        if y_arr.ndim == 2 and y_arr.shape[1] == nc:
                            # Already one-hot → convert to class indices
                            y_arr = np.argmax(y_arr, axis=1).astype(np.int32)
                            logger.debug(f"[{phase}] {target_name}: converted one-hot to class indices for {'validation' if is_validation else 'training'}")
                        elif y_arr.ndim == 1 or (y_arr.ndim == 2 and y_arr.shape[1] == 1):
                            # Already class indices or single column → ensure int
                            y_arr = y_arr.flatten().astype(np.int32)
                        else:
                            # Unexpected shape → fallback
                            logger.warning(f"[{phase}] {target_name}: unexpected shape {y_arr.shape}, fallback to zeros")
                            y_arr = np.zeros(n_samples, dtype=np.int32)
                        
                        y_arr = np.clip(y_arr, 0, nc - 1)
                        
                        # Sample weights for this target
                        if class_weights_dict is None or target_name not in class_weights_dict:
                            sw_arr = np.ones(n_samples, dtype=np.float32)
                        else:
                            cw = class_weights_dict[target_name]
                            sw_arr = np.array([float(cw.get(int(c), 1.0)) for c in y_arr], dtype=np.float32)
                            sw_arr = np.clip(sw_arr, 0.05, 20.0)
                
                y_tensors.append(tf.constant(y_arr, dtype=tf.float32 if target_name == 'price_return' else tf.int32))
                sw_tensors.append(tf.constant(sw_arr, dtype=tf.float32))
                
                logger.debug(f"[{phase}]    {target_name}: y_shape={y_arr.shape}, sw_range=[{np.min(sw_arr):.3f}, {np.max(sw_arr):.3f}]")

            X_tensor = tf.constant(X.astype(np.float32), dtype=tf.float32)
            y_tuple = tuple(y_tensors)
            sw_tuple = tuple(sw_tensors)

            dataset = tf.data.Dataset.from_tensor_slices((X_tensor, y_tuple, sw_tuple))
            dataset = dataset.batch(batch_size, drop_remainder=False)
            dataset = dataset.prefetch(tf.data.AUTOTUNE)

            logger.info(f"[{phase}] ✅ Dataset created: n_batches={int(np.ceil(n_samples / batch_size))}")
            return dataset

        except Exception as e:
            logger.error(f"[{phase}] ❌ FAILED: {e}")
            import traceback
            logger.error(traceback.format_exc())
            raise
            
    def _diagnose_targets(self, y_dict: Dict[str, np.ndarray], stage: str = "BEFORE_AUGMENTATION"):
        """
        🔍 DIAGNOSTIC: لاگ کامل وضعیت تارگت‌ها برای دیباگ کلاپس
        
        Args:
            y_dict: دیکشنری تارگت‌ها
            stage: مرحله اجرا (BEFORE_AUGMENTATION, AFTER_AUGMENTATION, BEFORE_TRAINING)
        """
        logger.info(f"\n{'='*70}")
        logger.info(f"🔍 TARGET DIAGNOSTICS - {stage}")
        logger.info(f"{'='*70}")
        
        CLASS_TARGETS = list(_GM_CLASSIFICATION_TARGETS)   # ← از globals
        REGRESSION_TARGETS = list(_GM_REGRESSION_TARGETS)   # ← از globals
                
        # 1. بررسی regression target
        for target in REGRESSION_TARGETS:
            if target not in y_dict or y_dict[target] is None:
                logger.error(f"   ❌ {target}: NOT FOUND!")
                continue
            
            y = y_dict[target]
            if hasattr(y, 'numpy'):
                y = y.numpy()
            y = np.array(y, dtype=np.float32).flatten()
            
            logger.info(f"\n   📈 {target} (REGRESSION):")
            logger.info(f"      • shape: {y.shape}")
            logger.info(f"      • range: [{y.min():.6f}, {y.max():.6f}]")
            logger.info(f"      • mean: {y.mean():.6f}")
            logger.info(f"      • std: {y.std():.6f}")
            logger.info(f"      • zeros: {(y == 0).sum():,} ({((y == 0).sum()/len(y))*100:.1f}%)")
            logger.info(f"      • nans: {np.isnan(y).sum()}")
            logger.info(f"      • infinities: {np.isinf(y).sum()}")
            
            # تشخیص نرمالایز شده یا خام
            is_normalized = (y.std() < 3.0) and (abs(y.mean()) < 3.0)
            logger.info(f"      • normalized: {'✅ YES' if is_normalized else '❌ NO (RAW DATA)'}")
        
        # 2. بررسی classification targets
        for target in CLASS_TARGETS:
            if target not in y_dict or y_dict[target] is None:
                logger.error(f"   ❌ {target}: NOT FOUND!")
                continue
            
            y_raw = y_dict[target]
            if hasattr(y_raw, 'numpy'):
                y_raw = y_raw.numpy()
            
            # تبدیل به class indices
            if len(y_raw.shape) > 1 and y_raw.shape[1] > 1:
                y = np.argmax(y_raw, axis=1)
            else:
                y = y_raw.flatten()
            
            y = y.astype(np.int32)
            
            unique, counts = np.unique(y, return_counts=True)
            n_classes_observed = len(unique)
            n_classes_expected = int(N_CLASSES_DEFAULT.get(target, 4))
            
            logger.info(f"\n   🎯 {target} (CLASSIFICATION):")
            logger.info(f"      • shape: {y.shape}")
            logger.info(f"      • observed classes: {sorted(unique.tolist())} (expected {n_classes_expected})")
            logger.info(f"      • class distribution:")
            
            for cls, cnt in zip(unique, counts):
                pct = cnt / len(y) * 100
                bar = "█" * int(pct / 2) + "░" * (50 - int(pct / 2))
                status = ""
                if pct < 10:
                    status = "🔴 MINORITY (<10%)"
                elif pct > 40:
                    status = "🟠 MAJORITY (>40%)"
                else:
                    status = "✅ BALANCED"
                logger.info(f"         Class {cls}: {cnt:8,d} ({pct:5.1f}%) {bar} {status}")
            
            # بررسی missing classes
            missing = [c for c in range(n_classes_expected) if c not in unique]
            if missing:
                logger.warning(f"      ⚠️ MISSING CLASSES: {missing} (مدل هرگز این کلاس‌ها را نمی‌بیند!)")
            
            # بررسی entropy (تنوع)
            probs = counts / len(y)
            entropy = -np.sum(probs * np.log(probs + 1e-8))
            max_entropy = np.log(n_classes_observed)
            entropy_ratio = entropy / max_entropy if max_entropy > 0 else 0
            
            logger.info(f"      • entropy: {entropy:.4f} / {max_entropy:.4f} (ratio={entropy_ratio:.2f})")
            if entropy_ratio < 0.5:
                logger.warning(f"      🔴 LOW ENTROPY DETECTED! توزیع کلاس‌ها بسیار نامتعادل است!")
            
            # بررسی sample weights پیشنهادی
            if stage == "BEFORE_TRAINING":
                max_freq = counts.max()
                suggested_weights = {}
                for cls, cnt in zip(unique, counts):
                    raw_weight = np.sqrt(max_freq / max(cnt, 1))
                    suggested_weights[int(cls)] = round(raw_weight, 3)
                logger.info(f"      • suggested class_weights: {suggested_weights}")
        
        # 3. بررسی alignment بین X و y
        if 'X' in locals():
            X_shape = None
        else:
            X_shape = None
        
        # 4. خلاصه نهایی
        logger.info(f"\n{'─'*70}")
        logger.info(f"📊 DIAGNOSTIC SUMMARY - {stage}:")
        
        # تشخیص مشکلات احتمالی
        issues = []
        
        for target in CLASS_TARGETS:
            if target in y_dict and y_dict[target] is not None:
                y_raw = y_dict[target]
                if len(y_raw.shape) > 1 and y_raw.shape[1] > 1:
                    y = np.argmax(y_raw, axis=1)
                else:
                    y = y_raw.flatten()
                unique = np.unique(y)
                n_classes_expected = int(N_CLASSES_DEFAULT.get(target, 4))
                missing = [c for c in range(n_classes_expected) if c not in unique]
                if missing:
                    issues.append(f"{target}: missing classes {missing}")
        
        if issues:
            logger.error(f"   🔴 CRITICAL ISSUES FOUND:")
            for issue in issues:
                logger.error(f"      • {issue}")
            logger.error(f"   ⚠️ این مشکل باعث MODEL COLLAPSE می‌شود!")
        else:
            logger.info(f"   ✅ No critical issues detected")
        
        logger.info(f"{'='*70}\n")

      
    def prepare_targets(self, y_raw: Dict, n_samples: int, name: str,
                        fit_scaler: bool = False,
                        scaler_params: Dict = None,
                        data_is_normalized: bool = True) -> Dict:
        """
        ✅ FIXED: Extracts class_frequencies and train_class_counts correctly
        """
        phase_prep = f"PREPARE_TARGETS_{name}"
        result = {}

        try:
            if y_raw is None:
                logger.error(f"❌ {phase_prep}: y_raw is None")
                return result

            REQUIRED_TARGETS = list(OUTPUT_ORDER)

            N_CLASSES_MAP = dict(N_CLASSES_DEFAULT)

            for target in REQUIRED_TARGETS:
                try:
                    arr = None

                    # Direct lookup
                    if target in y_raw and y_raw[target] is not None:
                        arr = y_raw[target]
                        logger.info(f"   ✅ {name}: Found '{target}' directly")
                    else:

                        for alias in TARGET_ALIASES.get(target, []):
                            if alias in y_raw and y_raw[alias] is not None:
                                arr = y_raw[alias]
                                logger.info(f"   ✅ {name}: Found '{target}' via alias '{alias}'")
                                break

                    if arr is None:
                        error_msg = f"❌ {name}: Target '{target}' not found!"
                        logger.error(error_msg)
                        raise KeyError(error_msg)

                    arr = np.array(arr, dtype=np.float32)
                    arr = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)

                    if len(arr) > n_samples:
                        arr = arr[:n_samples]
                        logger.info(f"   📊 {name}: Trimmed '{target}' to {n_samples} samples")

                    # PRICE RETURN (REGRESSION)
                    if target == 'price_return':
                        if arr.ndim == 1:
                            arr = arr.reshape(-1, 1)
                        arr_norm = np.clip(arr, -5.0, 5.0)
                        result[target] = arr_norm.astype(np.float32)

                    # CLASSIFICATION TARGETS
                    else:
                        n_classes = N_CLASSES_MAP.get(target, 5)

                        if arr.ndim == 2 and arr.shape[1] > 1:
                            # Already one-hot - convert to class indices for frequencies
                            class_indices = np.argmax(arr, axis=1)
                        else:
                            class_indices = arr.flatten().astype(np.int32)

                        class_indices = np.clip(class_indices, 0, n_classes - 1)

                        # 🔥 FIX: Store as class indices (NOT one-hot) for loss function
                        result[target] = class_indices.astype(np.int32)

                        # 🔥 FIX: Compute class frequencies for training (ONLY for TRAIN set)
                        if fit_scaler and name == "TRAIN":
                            unique, counts = np.unique(class_indices, return_counts=True)
                            freq_dict = {int(u): int(c) for u, c in zip(unique, counts)}
                            
                            # Update class_frequencies and train_class_counts
                            if not hasattr(self, 'class_frequencies'):
                                self.class_frequencies = {}
                            if not hasattr(self, 'train_class_counts'):
                                self.train_class_counts = {}
                            
                            self.class_frequencies[target] = freq_dict
                            self.train_class_counts[target] = freq_dict
                            
                            logger.info(f"   📊 {name}: '{target}' class frequencies: {freq_dict}")

                except Exception as target_err:
                    logger.error(f"❌ {phase_prep}: Failed to process target '{target}': {target_err}")
                    logger.error(traceback.format_exc())
                    continue

            logger.info(f"   ✅ {name}: Successfully prepared {len(result)} targets")
            return result

        except Exception as e:
            logger.error(f"❌ {phase_prep}: CRITICAL FAILURE: {e}")
            logger.error(traceback.format_exc())
            return result                        


    def _build_callbacks_for_model_omni(
        self,
        name: str,
        wrapped_model: 'SimpleMultiTaskTrainer',
        checkpoint_dir: str,
        start_epoch: int,
        regime_signal,
        X_test: Optional[np.ndarray],
        y_test: Optional[Dict[str, np.ndarray]],
        X_val: Optional[np.ndarray],
        y_val: Optional[Dict[str, np.ndarray]],
        scaler_params: Dict,
        train_dataset_weighted,
        val_dataset_weighted,
        class_frequencies: Dict[str, Dict[int, float]],
        fold: int,
        symbol: str,
        timeframe: str,
        collapse_detector: 'CollapseDetector' = None,
        workflow_state: Optional[Dict] = None,
        per_target_valid_masks_val: Optional[Dict[str, np.ndarray]] = None,
    ) -> Tuple[List[tf.keras.callbacks.Callback], 'TrainingDiagnostics', 'CollapseDetector']:
        """
        BUILD_CALLBACKS_OMNI v20.0 — CONTROLLER + LADDER PERSISTENCE WIRING.

        The callback order is intentional: validation/metrics first, controller
        next, self-healing next, direction early stopping after that, and full
        workflow persistence last. The adaptive controller receives the same
        ladder-model directory and validity masks used by training, so every
        target (including auxiliary heads) has an independent, resumable ladder.
        """
        phase = "BUILD_CALLBACKS_OMNI_V20"
        callbacks: List[tf.keras.callbacks.Callback] = []

        params = getattr(self, 'dynamic_params', None) or DynamicHyperparameters()
        n_classes_map = dict(N_CLASSES_DEFAULT)
        all_task_names = list(OUTPUT_ORDER)

        orchestrator: Optional['SelfHealingTrainingOrchestrator'] = None
        adaptive_controller: Optional['AdaptiveMultiTaskTrainingController'] = None
        dyn_balancer_instance = None
        scheduler_instance = None

        models_dir = os.path.join(checkpoint_dir, 'ladder_models')
        try:
            os.makedirs(models_dir, exist_ok=True)
        except OSError as exc:
            logger.warning(f"[{phase}] ladder models_dir mkdir failed: {exc}")

        restored_replacement_manager: Optional[TargetReplacementManager] = None
        if workflow_state and isinstance(workflow_state, dict):
            rm_state = None
            ac_state = workflow_state.get('AdaptiveMultiTaskTrainingController')
            if isinstance(ac_state, dict):
                rm_state = ac_state.get('replacement_manager')
            if isinstance(rm_state, dict):
                try:
                    restored_replacement_manager = TargetReplacementManager.from_state(
                        rm_state,
                        models_dir=models_dir,
                    )
                except Exception as rm_err:
                    logger.warning(
                        f"[{phase}] replacement manager restore failed: {rm_err}"
                    )
                    restored_replacement_manager = None

        steps_per_epoch = 0
        try:
            card = int(
                tf.data.experimental.cardinality(train_dataset_weighted).numpy()
            )
            if card > 0:
                steps_per_epoch = card
        except Exception as card_err:
            logger.debug(f"[{phase}] dataset cardinality unavailable: {card_err}")

        if steps_per_epoch <= 0:
            try:
                bs = int(getattr(params, 'batch_size', 64))
                n_tr = int(getattr(params, 'n_samples_train', 0))
                if n_tr > 0 and bs > 0:
                    steps_per_epoch = int(math.ceil(n_tr / bs))
            except Exception as steps_err:
                logger.debug(f"[{phase}] steps_per_epoch fallback failed: {steps_err}")
        if steps_per_epoch <= 0:
            steps_per_epoch = 200

        probe_freq = int(max(50, min(500, steps_per_epoch // 3)))
        logger.info(
            f"[{phase}] 📐 steps_per_epoch={steps_per_epoch} "
            f"(probe_freq={probe_freq})"
        )

        if collapse_detector is None:
            collapse_detector = CollapseDetector(params)

        try:
            if hasattr(wrapped_model, 'set_class_priors') and class_frequencies:
                n_set = wrapped_model.set_class_priors(class_frequencies)
                logger.info(
                    f"[{phase}] ✅ logit-adjustment priors injected into {n_set} heads"
                )
        except Exception as exc:
            logger.error(f"[{phase}] set_class_priors failed: {exc}", exc_info=True)

        try:
            callbacks.append(ResetStepCounterCallback(wrapped_model))
        except Exception as exc:
            logger.error(f"ResetStepCounter failed: {exc}")

        try:
            if (
                X_val is not None
                and y_val is not None
                and len(X_val) > 0
                and len(y_val) > 0
            ):
                fast_val_cb = FastValidationCallback(
                    X_val=X_val,
                    y_val_dict=y_val,
                    n_classes_map=dict(n_classes_map),
                    max_samples=1536,
                    batch_size=256,
                    every_n_epochs=1,
                    seed=1337,
                    log_fn=logger.info,
                    verbose=True,
                    primary_target='price_direction',
                    regression_targets=('price_return',),
                    per_target_valid_masks=per_target_valid_masks_val,
                )
                callbacks.append(fast_val_cb)
                logger.info(
                    f"[{phase}] ✅ FastValidationCallback added directly "
                    f"(produces val_bacc_* keys for controller stall tracking)"
                )
            else:
                logger.warning(
                    f"[{phase}] FastValidation skipped — X_val/y_val missing"
                )
        except Exception as exc:
            logger.error(f"[{phase}] FastValidation failed: {exc}", exc_info=True)

        diagnostics = None
        try:
            diagnostics = TrainingDiagnostics(
                dynamic_params=params,
                X_val=X_val,
                y_val=y_val,
                regime_signal=regime_signal,
                scaler_params=scaler_params,
                evaluate_every=1,
                per_class_recall_every=2,
                collapse_detector=collapse_detector,
                verbose=True,
            )
            if X_val is not None and y_val is not None:
                diagnostics.set_validation_data(X_val, y_val, scaler_params)
            callbacks.append(diagnostics)
        except Exception as exc:
            logger.error(f"TrainingDiagnostics failed: {exc}", exc_info=True)

        try:
            scheduler_instance = OptimizedScheduler(
                dynamic_params=params,
                regime_signal=regime_signal,
                start_epoch=start_epoch,
                verbose=True,
            )
            callbacks.append(scheduler_instance)
        except Exception as exc:
            logger.error(f"OptimizedScheduler failed: {exc}")

        try:
            dyn_balancer_instance = DynamicClassBalancer(
                model=wrapped_model,
                task_names=all_task_names,
                n_classes_per_task=dict(n_classes_map),
                train_class_counts=class_frequencies,
                collapse_detector=collapse_detector,
                dynamic_params=params,
                probe_dataset=val_dataset_weighted,
                probe_freq_batches=probe_freq,
                probe_max_batches=1,
                verbose=1,
            )
            try:
                wrapped_model.dynamic_balancer = dyn_balancer_instance
            except Exception as balancer_assign_err:
                logger.debug(
                    f"[{phase}] dynamic_balancer assignment skipped: "
                    f"{balancer_assign_err}"
                )
        except Exception as exc:
            logger.error(
                f"DynamicClassBalancer construction failed: {exc}",
                exc_info=True,
            )

        try:
            if X_val is not None and hasattr(wrapped_model, 'update_class_weights'):
                adaptive_cw = AdaptiveClassWeightCallback(
                    trainer=wrapped_model,
                    X_val=X_val,
                    train_class_counts=class_frequencies,
                    n_classes_per_task=dict(n_classes_map),
                    every_n_epochs=1,
                    max_samples=1024,
                    uniform_mix=0.6,
                    beta=0.7,
                    ema_momentum=0.3,
                    min_weight=0.4,
                    max_weight=3.0,
                    dead_floor_ratio=0.05,
                    escalate_on_dead=True,
                    verbose=1,
                )
                callbacks.append(adaptive_cw)
        except Exception as exc:
            logger.error(
                f"AdaptiveClassWeightCallback failed: {exc}",
                exc_info=True,
            )

        try:
            if (
                hasattr(wrapped_model, 'relax_log_var_floor')
                and getattr(wrapped_model, '_log_var_lo', None)
            ):
                callbacks.append(
                    LogVarGovernor(
                        trainer=wrapped_model,
                        patience=2,
                        relax_step=0.25,
                        hard_floor=-2.5,
                        pin_tolerance=1e-3,
                        verbose=True,
                    )
                )
        except Exception as exc:
            logger.error(f"LogVarGovernor failed: {exc}", exc_info=True)

        if X_val is not None and y_val is not None:
            try:
                callbacks.append(
                    HeadEntropyMonitor(
                        model=wrapped_model,
                        val_X=X_val,
                        val_y=y_val,
                        task_names=all_task_names,
                        n_classes_per_task=dict(n_classes_map),
                        entropy_collapse_threshold=float(
                            getattr(params, 'collapse_entropy_threshold', 0.15)
                        ),
                        monitor_every_epochs=2,
                        max_samples=4000,
                        batch_size=1024,
                        min_total_samples=300,
                        min_support_per_class=80,
                        verbose=True,
                        collapse_detector=collapse_detector,
                        min_collapse_streak=1,
                        no_edge_collapse_epochs=5,
                    )
                )
            except Exception as exc:
                logger.error(f"HeadEntropyMonitor failed: {exc}", exc_info=True)

        if X_val is not None and y_val is not None:
            try:
                callbacks.append(
                    ArgmaxCollapseMonitor(
                        X_val=X_val,
                        y_val=y_val,
                        n_classes_per_task=dict(n_classes_map),
                        every_n_epochs=2,
                        max_samples=2000,
                        min_share=0.10,
                        minority_streak_required=3,
                        collapse_detector=collapse_detector,
                        verbose=1,
                    )
                )
            except Exception as exc:
                logger.error(f"ArgmaxCollapseMonitor failed: {exc}", exc_info=True)

        try:
            os.makedirs(checkpoint_dir, exist_ok=True)
            best_checkpoint = SafeModelCheckpoint(
                filepath=os.path.join(checkpoint_dir, "best_model.keras"),
                monitor=(
                    'val_base_loss'
                    if val_dataset_weighted is not None
                    else 'base_loss'
                ),
                save_best_only=True,
                mode='min',
                save_weights_only=False,
                verbose=1,
                symbol=symbol,
                timeframe=timeframe,
                fold=fold,
                model_architecture="omni_refactored",
                send_to_telegram=False,
            )
            callbacks.append(best_checkpoint)
            logger.info(
                f"[{phase}] ✅ SafeModelCheckpoint added — "
                f"monitor="
                f"'{'val_base_loss' if val_dataset_weighted is not None else 'base_loss'}'"
            )

            class CollapseAwareEpochCheckpoint(tf.keras.callbacks.Callback):
                def __init__(self, ckpt_dir, detector, _params):
                    super().__init__()
                    self.ckpt_dir = ckpt_dir
                    self.detector = detector
                    self._params = _params
                    self._saved = set()

                def on_epoch_end(self, epoch, logs=None):
                    ep = epoch + 1
                    if ep in self._saved:
                        return
                    try:
                        status = (
                            self.detector.get_collapse_status()
                            if self.detector
                            else {}
                        )
                        if bool(status.get('is_collapsed', False)):
                            return
                        logs = logs if logs is not None else {}
                        path = os.path.join(self.ckpt_dir, f"epoch_{ep:04d}.keras")
                        save_model_with_full_metadata(
                            model=self.model,
                            model_path=path,
                            metadata={
                                'epoch': ep,
                                'loss': logs.get('loss', 0),
                                'val_loss': logs.get('val_loss', 0),
                                'val_base_loss': logs.get('val_base_loss', None),
                                'model_collapsed': False,
                            },
                            include_optimizer=True,
                            dynamic_params=self._params,
                        )
                        self._saved.add(ep)
                    except Exception as save_err:
                        logger.error(f"Epoch save failed: {save_err}")

                def reset_for_healing(self, new_dynamic_params=None):
                    self._saved.clear()

            callbacks.append(
                CollapseAwareEpochCheckpoint(
                    checkpoint_dir,
                    collapse_detector,
                    params,
                )
            )
        except Exception as exc:
            logger.error(f"Checkpoint callbacks failed: {exc}", exc_info=True)

        try:
            callbacks.append(
                AlwaysSendCheckpointCallback(
                    checkpoint_dir=checkpoint_dir,
                    symbol=symbol,
                    timeframe=timeframe,
                    fold=fold,
                    model_architecture="omni_refactored",
                )
            )
        except Exception as exc:
            logger.error(
                f"AlwaysSendCheckpointCallback failed: {exc}",
                exc_info=True,
            )

        balanced_acc_available = False
        if X_val is not None and y_val is not None:
            try:
                callbacks.append(
                    BalancedAccuracyCallback(
                        X_val=X_val,
                        y_val=y_val,
                        every_n_epochs=1,
                        verbose=True,
                    )
                )
                balanced_acc_available = True
            except Exception as exc:
                logger.error(
                    f"BalancedAccuracyCallback failed: {exc}",
                    exc_info=True,
                )

        try:
            adaptive_controller = AdaptiveMultiTaskTrainingController(
                task_names=all_task_names,
                regression_targets=['price_return'],
                X_train=globals().get('_V11_CLEAN_TRAIN_X', None),
                y_train_dict=globals().get('_V11_CLEAN_TRAIN_Y', None),
                X_val=X_val,
                y_val_dict=y_val,
                n_classes_map=dict(n_classes_map),
                min_epochs=max(
                    5,
                    min(20, int(getattr(params, 'base_epochs', 30) * 0.10)),
                ),
                patience=max(
                    8,
                    min(24, int(getattr(params, 'base_epochs', 30) * 0.12)),
                ),
                min_delta=max(1e-6, float(getattr(params, 'min_delta', 1e-4))),
                min_weight=0.25,
                max_weight=3.0,
                enable_replacement=True,
                min_epoch_before_replace=self._USER_MIN_EPOCH_BEFORE_REPLACE,
                replacement_interval_epochs=self._USER_REPLACEMENT_INTERVAL_EPOCHS,
                verbose=1,
                replacement_manager=restored_replacement_manager,
                models_dir=models_dir,
                per_target_valid_masks_train=globals().get(
                    '_V11_PER_TARGET_MASKS_TRAIN', None
                ),
                per_target_valid_masks_val=per_target_valid_masks_val,
            )
            callbacks.append(adaptive_controller)
            try:
                if hasattr(adaptive_controller, 'bind_trainer'):
                    adaptive_controller.bind_trainer(wrapped_model)
            except Exception as bind_err:
                logger.warning(f"[{phase}] bind_trainer failed: {bind_err}")
            logger.info(
                f"[{phase}] ✅ AdaptiveMultiTaskTrainingController added"
            )
        except Exception as exc:
            logger.error(
                f"[{phase}] AdaptiveMultiTaskTrainingController init failed: {exc}",
                exc_info=True,
            )

        try:
            if train_dataset_weighted is not None:
                orchestrator = SelfHealingTrainingOrchestrator(
                    dynamic_params=params,
                    collapse_detector=collapse_detector,
                    checkpoint_dir=checkpoint_dir,
                    train_dataset=train_dataset_weighted,
                    val_dataset=val_dataset_weighted,
                    symbol=symbol,
                    timeframe=timeframe,
                    fold=fold,
                    other_callbacks=list(callbacks),
                    verbose=1,
                )
                if scheduler_instance is not None:
                    orchestrator.register_scheduler(scheduler_instance)
                if dyn_balancer_instance is not None:
                    orchestrator.register_dynamic_balancer(dyn_balancer_instance)
                if adaptive_controller is not None:
                    rm_late = adaptive_controller.get_replacement_manager()
                    if rm_late is not None:
                        try:
                            orchestrator.replacement_manager = rm_late
                        except Exception as rm_late_err:
                            logger.debug(
                                f"[{phase}] orchestrator replacement assignment: "
                                f"{rm_late_err}"
                            )
                callbacks.append(orchestrator)
        except Exception as exc:
            logger.error(f"[{phase}] SelfHealing failed: {exc}", exc_info=True)

        try:
            patience = max(8, int(params.base_epochs * 0.05))
            min_epochs = max(15, int(params.base_epochs * 0.08))
            if balanced_acc_available:
                es_monitor, es_mode = 'val_balanced_acc_pri', 'max'
            else:
                es_monitor = (
                    'val_base_loss'
                    if val_dataset_weighted is not None
                    else 'base_loss'
                )
                es_mode = 'min'

            _suite_self = self

            def _stop_veto_callback(epoch, logs):
                try:
                    _adaptive_ref = getattr(
                        _suite_self,
                        '_adaptive_controller_ref',
                        None,
                    )
                except Exception:
                    _adaptive_ref = None

                if _adaptive_ref is None:
                    return False

                try:
                    blocked, reason = _adaptive_ref.is_early_stopping_blocked()
                    if blocked:
                        logger.info(
                            f"[_stop_veto_callback] VETO epoch {epoch}: {reason}"
                        )
                    return bool(blocked)
                except Exception as cb_err:
                    logger.warning(
                        f"[_stop_veto_callback] check raised: {cb_err} — "
                        f"allow stop only as a defensive fallback"
                    )
                    return False

            callbacks.append(
                DirectionAccuracyEarlyStopping(
                    model=wrapped_model,
                    val_X=X_val,
                    val_y=y_val,
                    head_name='price_direction',
                    patience=patience,
                    min_delta=float(params.min_delta),
                    warmup_epochs=min_epochs,
                    restore_best_weights=True,
                    min_samples=300,
                    min_support_per_class=80,
                    max_samples=4000,
                    batch_size=1024,
                    chance_warn_epochs=6,
                    verbose=True,
                    monitor=es_monitor,
                    mode=es_mode,
                    stop_veto_callback=_stop_veto_callback,
                    controller=adaptive_controller,
                )
            )
            logger.info(
                f"[{phase}] ✅ DirectionAccuracyEarlyStopping added "
                f"(controller="
                f"{'present' if adaptive_controller is not None else 'None'})"
            )
        except Exception as exc:
            logger.error(f"DirAccES failed: {exc}", exc_info=True)

        try:
            callbacks.append(
                EpochFileLoggerCallback(
                    logger=logger,
                    phase="train",
                    log_every_n_batches=100,
                    log_first_n_batches=3,
                    max_console_lines=10000,
                )
            )
        except Exception as exc:
            logger.error(
                f"EpochFileLoggerCallback failed: {exc}",
                exc_info=True,
            )

        if workflow_state and isinstance(workflow_state, dict):
            try:
                n_restored = _inject_workflow_state(callbacks, workflow_state)
                logger.info(
                    f"[{phase}] ✅ workflow_state injected — "
                    f"{n_restored} callbacks restored"
                )
            except Exception as exc:
                logger.error(
                    f"[{phase}] workflow_state injection failed: {exc}",
                    exc_info=True,
                )

        if adaptive_controller is not None:
            try:
                self._adaptive_controller_ref = adaptive_controller
            except Exception as ref_err:
                logger.debug(
                    f"[{phase}] could not set _adaptive_controller_ref: {ref_err}"
                )

        try:
            callbacks.append(
                WorkflowStatePersistenceCallback(
                    checkpoint_dir=checkpoint_dir,
                    stateful_callbacks=list(callbacks),
                    save_every_n_epochs=1,
                    verbose=1,
                )
            )
            logger.info(
                f"[{phase}] ✅ WorkflowStatePersistenceCallback added (LAST)"
            )
        except Exception as exc:
            logger.error(f"[{phase}] WSP failed: {exc}", exc_info=True)

        logger.info(f"[{phase}] Total callbacks: {len(callbacks)}")
        for i, cb in enumerate(callbacks, 1):
            logger.info(f"[{phase}]   {i:2d}. {type(cb).__name__}")

        return callbacks, diagnostics, collapse_detector

       
    async def run_tests(self, data_is_normalized: bool = True) -> Dict[str, Any]:
        """
        RUN_TESTS v19.1 — DYNAMIC LOOKBACK + TUPLE-SAFE UNPACKING.

        🔥 v19.1 (RCA از لاگ اجرای شما):
            نسخهٔ v19.0 مقدار `_lookback = 64` را هاردکد کرده بود. فایل‌های
            موجود lookback=65 داشتند، `_load_sequenced_data` به‌درستی
            fail-fast کرد، `universal_load` مقدار None برگرداند، و caller
            با `TypeError: cannot unpack non-iterable NoneType object`
            کرش کرد.

        🔥 اصلاحات v19.1:
            • STEP 02: lookback از `discover_available_lookback` کشف می‌شود
              (با پشتیبانی از env override OMNI_LOOKBACK). اگر کشف شکست
              خورد، RuntimeError صریح — نه fallback ساکت.
            • STEP 03: هر universal_load در متغیر میانجی ذخیره می‌شود.
              اگر None بود، None-check با پیام روشن. train الزامی است؛
              val/test اختیاری با warning.
            • STEP 11: `_LADDER_MAX_RUNGS` از `len(CLASSIFICATION_LADDER)-1`
              مشتق می‌شود — نه هاردکد 31.
        """
        try:
            import os
            import json
            import traceback
            import time as _time
            from datetime import datetime
            from main import sum_folds as fold
            from core.global_method import (
                get_active_symbol_timeframe,
                universal_load,
                discover_available_lookback,
            )
        except ImportError:
            logger.error("import error")
        t_run_start = _time.time()

        _VERBOSE = os.environ.get("OMNI_VERBOSE", "").strip() in ("1", "true", "yes", "on")
        if not os.environ.get("OMNI_RESUME"):
            os.environ.setdefault("OMNI_FRESH_RUN", "1")
        _FRESH = os.environ.get("OMNI_FRESH_RUN", "").strip() in ("1", "true", "yes", "on")
        _RESUME = os.environ.get("OMNI_RESUME", "").strip() in ("1", "true", "yes", "on")

        phase = "RUN_TESTS_v19"
        results: Dict[str, Any] = {}
        final_model_path: Optional[str] = None
        best_checkpoint_path: Optional[str] = None
        best_epoch = 0
        best_val_loss = float('inf')
        symbol, timeframe = "UNKNOWN", "UNKNOWN"

        callbacks: List[tf.keras.callbacks.Callback] = []
        orchestrator: Optional[SelfHealingTrainingOrchestrator] = None
        main_controller: Optional[AdaptiveMultiTaskTrainingController] = None
        diagnostics = None
        collapse_detector = None
        workflow_state: Optional[Dict] = None

        logger.info("")
        logger.info("╔" + "═" * 78 + "╗")
        logger.info("║" + " RUN_TESTS v19.1 — DYNAMIC LOOKBACK ".center(78) + "║")
        logger.info("╠" + "═" * 78 + "╣")
        logger.info(f"║ FRESH_RUN  = {str(_FRESH):<60} ║")
        logger.info(f"║ RESUME     = {str(_RESUME):<60} ║")
        logger.info(f"║ VERBOSE    = {str(_VERBOSE):<60} ║")
        logger.info(f"║ FORCE_EP   = {str(FORCE_START_EPOCH):<60} ║")
        logger.info(f"║ TIMESTAMP  = {datetime.now().isoformat():<60} ║")
        logger.info("╚" + "═" * 78 + "╝")
        logger.info("")

        try:
            # [STEP 01] symbol/timeframe
            logger.info(f"[{phase}][STEP 01] Resolving active symbol/timeframe...")
            symbol, timeframe = get_active_symbol_timeframe()
            if symbol is None or timeframe is None:
                raise RuntimeError(
                    f"[{phase}][STEP 01] ❌ get_active_symbol_timeframe returned "
                    f"symbol={symbol!r}, timeframe={timeframe!r}. "
                    f"Fix cache/tf_decisions.json."
                )
            logger.info(
                f"[{phase}][STEP 01] ✅ symbol={symbol}, timeframe={timeframe}, "
                f"fold={fold}"
            )

            # [STEP 02] DYNAMIC LOOKBACK DISCOVERY — no hardcoded 64
            logger.info(
                f"[{phase}][STEP 02] Discovering lookback from actual data..."
            )
            _lookback = None
            _lb_env = os.environ.get("OMNI_LOOKBACK", "").strip()
            if _lb_env:
                try:
                    v = int(_lb_env)
                    if 16 <= v <= 512:
                        _lookback = v
                        logger.warning(
                            f"[STEP 02] ⚠️ lookback از env override شد: "
                            f"{_lookback} (parity با CPU ممکن است نقض شود)"
                        )
                except (TypeError, ValueError):
                    logger.warning(
                        f"[STEP 02] OMNI_LOOKBACK={_lb_env!r} invalid int — ignored"
                    )

            if _lookback is None:
                try:
                    _lookback = discover_available_lookback(
                        symbol=symbol,
                        timeframe=timeframe,
                        fold=fold,
                        split_type="train",
                    )
                except Exception as _lb_err:
                    logger.error(
                        f"[STEP 02] ❌ lookback discovery raised: {_lb_err}",
                        exc_info=True,
                    )
                    _lookback = None

            if _lookback is None:
                raise RuntimeError(
                    f"[{phase}][STEP 02] ❌ Cannot determine lookback: "
                    f"no sequenced train file found for "
                    f"{symbol}/{timeframe}/fold{fold}. "
                    f"Set OMNI_LOOKBACK env or ensure sequenced files exist."
                )

            logger.info(
                f"[{phase}][STEP 02] ✅ lookback={_lookback} "
                f"(discovered from data — hardware-independent)"
            )

            # [STEP 03] Load sequenced data — None-check + safe unpack
            logger.info(
                f"[{phase}][STEP 03] Loading sequenced data "
                f"(lookback={_lookback})..."
            )

            _train_result = await universal_load(
                data_type="sequenced",
                symbol=symbol,
                timeframe=timeframe,
                fold=fold,
                split_type="train",
                lookback=_lookback,
                multi_output=True,
            )
            if _train_result is None:
                raise RuntimeError(
                    f"[{phase}][STEP 03] ❌ universal_load returned None for "
                    f"train (symbol={symbol}, timeframe={timeframe}, "
                    f"fold={fold}, lookback={_lookback})"
                )
            try:
                X_train, y_train_raw = _train_result
            except (TypeError, ValueError) as _unpack_err:
                raise RuntimeError(
                    f"[{phase}][STEP 03] ❌ could not unpack train result "
                    f"of type {type(_train_result).__name__}: {_unpack_err}"
                ) from _unpack_err

            if X_train is None or len(X_train) == 0:
                raise ValueError(
                    f"[{phase}][STEP 03] X_train is None or empty"
                )
            if not isinstance(y_train_raw, dict) or not y_train_raw:
                raise ValueError(
                    f"[{phase}][STEP 03] y_train_raw is empty or not a dict: "
                    f"{type(y_train_raw).__name__}"
                )

            _val_result = await universal_load(
                data_type="sequenced",
                symbol=symbol,
                timeframe=timeframe,
                fold=fold,
                split_type="val",
                lookback=_lookback,
                multi_output=True,
            )
            if _val_result is None:
                logger.warning(
                    f"[{phase}][STEP 03] ⚠️ val data is None — proceeding "
                    f"without validation set"
                )
                X_val, y_val_raw = None, None
            else:
                try:
                    X_val, y_val_raw = _val_result
                except (TypeError, ValueError) as _unpack_err:
                    logger.warning(
                        f"[{phase}][STEP 03] ⚠️ could not unpack val result: "
                        f"{_unpack_err} — proceeding without validation"
                    )
                    X_val, y_val_raw = None, None

            _test_result = await universal_load(
                data_type="sequenced",
                symbol=symbol,
                timeframe=timeframe,
                fold=fold,
                split_type="test",
                lookback=_lookback,
                multi_output=True,
            )
            if _test_result is None:
                logger.warning(
                    f"[{phase}][STEP 03] ⚠️ test data is None — proceeding "
                    f"without test set"
                )
                X_test, y_test_raw = None, None
            else:
                try:
                    X_test, y_test_raw = _test_result
                except (TypeError, ValueError) as _unpack_err:
                    logger.warning(
                        f"[{phase}][STEP 03] ⚠️ could not unpack test result: "
                        f"{_unpack_err} — proceeding without test"
                    )
                    X_test, y_test_raw = None, None

            logger.info(
                f"[{phase}][STEP 03] ✅ loaded: "
                f"train={X_train.shape if X_train is not None else 'None'}, "
                f"val={X_val.shape if X_val is not None else 'None'}, "
                f"test={X_test.shape if X_test is not None else 'None'}"
            )

            # [STEP 04] sanitize
            def _sanitize(arr, name):
                if arr is None:
                    return None
                a = np.asarray(arr, dtype=np.float32)
                n_bad = int((~np.isfinite(a)).sum())
                a = np.nan_to_num(a, nan=0.0, posinf=0.0, neginf=0.0)
                a = np.clip(a, -5.0, 5.0)
                logger.info(
                    f"[{phase}][STEP 04] {name}: shape={a.shape}, nan/inf={n_bad}"
                )
                return a

            X_train = _sanitize(X_train, "train")
            X_val = _sanitize(X_val, "val")
            X_test = _sanitize(X_test, "test")

            # [STEP 05] scale audit
            try:
                from core.global_method import get_scale_audit_reports
                audit = get_scale_audit_reports(
                    symbol=symbol, timeframe=timeframe, fold=fold,
                    raise_on_mismatch=False, verbose=False,
                )
                n_ok = sum(
                    1 for v in audit.values()
                    if isinstance(v, dict) and v.get("ok")
                )
                logger.info(f"[{phase}][STEP 05] scale audit: {n_ok} OK")
            except Exception as e:
                logger.warning(f"[{phase}][STEP 05] scale audit failed: {e}")

            # [STEP 06] augmentation
            if self.enable_data_augmentation:
                n_before = X_train.shape[0]
                X_train, y_train_raw = augment_minority_classes(
                    X=X_train, y_dict=y_train_raw,
                    minority_threshold=self.dynamic_params.minority_threshold,
                    augment_factor=self.dynamic_params.augment_factor,
                    noise_scale=self.dynamic_params.noise_scale,
                    add_time_shift=True,
                )
                n_after = X_train.shape[0]
                logger.info(
                    f"[{phase}][STEP 06] ✅ Augmentation: {n_before} → {n_after}"
                )

            # [STEP 07] IPCA
            ipca_reducer = None
            if self.IncrementalPCA:
                ipca_reducer = IncrementalFeatureReducer(
                    n_components=self.ipca_n_components,
                    batch_size=1000,
                    feature_groups=self.ipca_feature_groups,
                    variance_ratio=self.ipca_variance_ratio,
                    use_mi_ranking=False,
                    min_components=self.ipca_min_components,
                )
                X_train = ipca_reducer.fit_transform(X_train, y=None)
                if X_val is not None:
                    X_val = ipca_reducer.transform(X_val)
                if X_test is not None:
                    X_test = ipca_reducer.transform(X_test)

            # [STEP 08] TARGETS — INVALID-AWARE EXTRACTION WITH PER-TARGET MASKS
            N_CLASSES_MAP = dict(N_CLASSES_DEFAULT)
            ALL_TARGETS = list(OUTPUT_ORDER)

            # ── sample_weight موجود (بیرونی) ──
            sample_weight_train = None
            for sw_key in ('sample_weight', 'sample_weights'):
                if sw_key in (y_train_raw or {}):
                    try:
                        sw_arr = np.asarray(
                            y_train_raw[sw_key], dtype=np.float32
                        ).reshape(-1)
                        if sw_arr.shape[0] == X_train.shape[0]:
                            sample_weight_train = sw_arr
                            logger.info(
                                f"[{phase}][STEP 08] ✅ sample_weight loaded "
                                f"from '{sw_key}' | "
                                f"mean={sw_arr.mean():.4f}, "
                                f"std={sw_arr.std():.4f}, "
                                f"range=[{sw_arr.min():.4f}, {sw_arr.max():.4f}]"
                            )
                            break
                        else:
                            logger.warning(
                                f"[{phase}][STEP 08] sample_weight '{sw_key}' "
                                f"length {sw_arr.shape[0]} != X "
                                f"{X_train.shape[0]} — ignored"
                            )
                    except Exception as _sw_err:
                        logger.warning(
                            f"[{phase}][STEP 08] sample_weight '{sw_key}' "
                            f"load failed: {_sw_err}"
                        )

            if sample_weight_train is None:
                logger.info(
                    f"[{phase}][STEP 08] ℹ️ sample_weight not found — using "
                    f"uniform weights (all 1.0)"
                )

            # ═══════════════════════════════════════════════════════════════
            # 🔥 استخراج تارگت‌ها + ماسک INVALID برای هر split
            # ═══════════════════════════════════════════════════════════════
            y_train: Dict[str, np.ndarray] = {}
            y_val: Dict[str, np.ndarray] = {}
            y_test: Dict[str, np.ndarray] = {}
            class_counts: Dict[str, Dict[int, int]] = {}

            per_target_sample_weights_train: Dict[str, np.ndarray] = {}
            per_target_sample_weights_val: Dict[str, np.ndarray] = {}
            per_target_sample_weights_test: Dict[str, np.ndarray] = {}

            # ── TRAIN ──
            for t in ALL_TARGETS:
                if t == 'price_return':
                    arr_t, mask_t, n_inv = extract_target_with_validity_mask(
                        (y_train_raw or {}).get(t),
                        X_train.shape[0],
                        is_cls=False,
                        name=f"train.{t}",
                    )
                    y_train[t] = arr_t
                else:
                    arr_t, mask_t, n_inv = extract_target_with_validity_mask(
                        (y_train_raw or {}).get(t),
                        X_train.shape[0],
                        is_cls=True,
                        n_cls=N_CLASSES_MAP[t],
                        name=f"train.{t}",
                    )
                    y_train[t] = arr_t
                    if arr_t is not None:
                        # 🔥 FIX v19.2: INVALID ها هرگز نباید در class_counts بیایند
                        if mask_t is not None:
                            valid_arr = arr_t[mask_t]
                        else:
                            valid_arr = arr_t
                        if valid_arr.size > 0:
                            u, c = np.unique(valid_arr, return_counts=True)
                            class_counts[t] = {
                                int(a): int(b) for a, b in zip(u, c)
                            }
                            n_inv_in_counts = int(
                                arr_t.size - valid_arr.size
                            )
                            logger.info(
                                f"[RUN_TESTS_v19_2][STEP 08] ✅ "
                                f"class_counts['{t}'] = {class_counts[t]} "
                                f"(excluded {n_inv_in_counts} INVALID)"
                            )
                    if mask_t is not None and not mask_t.all():
                        per_target_sample_weights_train[t] = (
                            mask_t.astype(np.float32)
                        )
                        logger.warning(
                            f"[{phase}][STEP 08] 🎯 train.{t}: "
                            f"{n_inv}/{len(mask_t)} "
                            f"({100.0 * n_inv / len(mask_t):.2f}%) INVALID "
                            f"→ masked with weight=0 in training"
                        )

            # ── VALIDATION ──
            if X_val is not None:
                for t in ALL_TARGETS:
                    if t == 'price_return':
                        arr_t, mask_t, n_inv = extract_target_with_validity_mask(
                            (y_val_raw or {}).get(t),
                            X_val.shape[0],
                            is_cls=False,
                            name=f"val.{t}",
                        )
                        y_val[t] = arr_t
                    else:
                        arr_t, mask_t, n_inv = extract_target_with_validity_mask(
                            (y_val_raw or {}).get(t),
                            X_val.shape[0],
                            is_cls=True,
                            n_cls=N_CLASSES_MAP[t],
                            name=f"val.{t}",
                        )
                        y_val[t] = arr_t
                        if mask_t is not None and not mask_t.all():
                            per_target_sample_weights_val[t] = (
                                mask_t.astype(np.float32)
                            )
                            logger.warning(
                                f"[{phase}][STEP 08] 🎯 val.{t}: "
                                f"{n_inv}/{len(mask_t)} "
                                f"({100.0 * n_inv / len(mask_t):.2f}%) INVALID "
                                f"→ masked with weight=0 in training"
                            )

            # ── TEST ──
            if X_test is not None:
                for t in ALL_TARGETS:
                    if t == 'price_return':
                        arr_t, mask_t, n_inv = extract_target_with_validity_mask(
                            (y_test_raw or {}).get(t),
                            X_test.shape[0],
                            is_cls=False,
                            name=f"test.{t}",
                        )
                        y_test[t] = arr_t
                    else:
                        arr_t, mask_t, n_inv = extract_target_with_validity_mask(
                            (y_test_raw or {}).get(t),
                            X_test.shape[0],
                            is_cls=True,
                            n_cls=N_CLASSES_MAP[t],
                            name=f"test.{t}",
                        )
                        y_test[t] = arr_t
                        if mask_t is not None and not mask_t.all():
                            per_target_sample_weights_test[t] = (
                                mask_t.astype(np.float32)
                            )
                            logger.warning(
                                f"[{phase}][STEP 08] 🎯 test.{t}: "
                                f"{n_inv}/{len(mask_t)} "
                                f"({100.0 * n_inv / len(mask_t):.2f}%) INVALID "
                                f"→ masked with weight=0 in training"
                            )

            # ── strip sample_weight از dict (اگر present بود) ──
            for _d in (y_train, y_val, y_test):
                _d.pop('sample_weight', None)
                _d.pop('sample_weights', None)

            y_train = {k: v for k, v in y_train.items() if v is not None}
            y_val   = {k: v for k, v in y_val.items()   if v is not None}
            y_test  = {k: v for k, v in y_test.items()  if v is not None}

            assert len(y_train) > 0, (
                f"[{phase}][STEP 08] FATAL: y_train empty after extraction. "
                f"y_train_raw_keys="
                f"{list(y_train_raw.keys()) if y_train_raw else None}"
            )
            if X_val is not None:
                assert len(y_val) > 0, (
                    f"[{phase}][STEP 08] FATAL: y_val empty after extraction."
                )
            if X_test is not None:
                assert len(y_test) > 0, (
                    f"[{phase}][STEP 08] FATAL: y_test empty after extraction."
                )

            logger.info(
                f"[{phase}][STEP 08] ✅ targets extracted — "
                f"train={sorted(y_train.keys())}, "
                f"val={sorted(y_val.keys())}, "
                f"test={sorted(y_test.keys())}"
            )
            logger.info(
                f"[{phase}][STEP 08] 🎯 per_target masks "
                f"(train/val/test): "
                f"{sorted(per_target_sample_weights_train.keys())}/"
                f"{sorted(per_target_sample_weights_val.keys())}/"
                f"{sorted(per_target_sample_weights_test.keys())}"
            )

            for _t, _c in class_counts.items():
                _n = sum(_c.values())
                _nz = len(_c)
                _k = N_CLASSES_MAP.get(_t, 0)
                _flag = "✅" if _nz == _k else "⚠️"
                logger.info(
                    f"[{phase}][STEP 08]    {_flag} train.{_t}: "
                    f"classes_seen={sorted(_c.keys())} "
                    f"({_nz}/{_k}), n={_n:,}"
                )

            self.class_frequencies = class_counts
            self.train_class_counts = class_counts
            self._X_train_cache = X_train
            self._y_train_cache = y_train

            globals()["_V11_CLEAN_TRAIN_X"] = X_train
            globals()["_V11_CLEAN_TRAIN_Y"] = y_train
            globals()["_V11_CLEAN_TRAIN_N"] = int(X_train.shape[0])
            globals()["_V11_PER_TARGET_MASKS_TRAIN"] = per_target_sample_weights_train

            logger.info(
                f"[{phase}][STEP 08] ✅ globals set: "
                f"_V11_CLEAN_TRAIN_N={X_train.shape[0]:,}, "
                f"sample_weight="
                f"{'present' if sample_weight_train is not None else 'absent'}, "
                f"per_target_masks_train="
                f"{len(per_target_sample_weights_train)} head(s)"
            )

            # [STEP 09] scalers
            if not self.scalers_loaded:
                self._load_scalers()
            try:
                scaler_params = load_scalers_from_path(
                    scaler_type='target', auto_detect=True, verbose=True
                )
            except Exception as e:
                logger.error(f"[{phase}][STEP 09] scaler load failed: {e}")
                scaler_params = {}

            # [STEP 10] regime
            regime_signal = None
            try:
                from core.regim import get_symbol_regime, MarketRegime, RegimeSignal
                rd = await get_symbol_regime()
                if rd:
                    resolved = MarketRegime.resolve(
                        rd.get('regime', 'undefined')
                    )
                    regime_signal = RegimeSignal(
                        regime=resolved,
                        confidence=rd.get('confidence', 0.5),
                        persistence_score=rd.get('persistence_score', 0.5),
                        volatility_regime=rd.get('volatility_regime', 'MEDIUM'),
                        trend_strength=rd.get('trend_strength', 0.5),
                        liquidity_regime=rd.get('liquidity_regime', 'NORMAL'),
                        detection_timestamp=datetime.now(),
                        lookback_window=200,
                        metadata={},
                    )
            except Exception as e:
                logger.warning(f"[{phase}][STEP 10] regime skipped: {e}")

            # [STEP 11] hyperparams + ladder budget
            y_train_oh = {}
            for t, arr in y_train.items():
                if arr is None:
                    continue
                if t == 'price_return':
                    y_train_oh[t] = arr
                else:
                    y_train_oh[t] = tf.keras.utils.to_categorical(
                        arr, num_classes=N_CLASSES_MAP[t]
                    ).astype(np.float32)

            self.dynamic_params = DynamicHyperparameterFactory.from_data(
                X_train=X_train, y_train=y_train_oh,
                X_val=X_val, X_test=X_test,
                symbol=symbol, timeframe=timeframe, fold=fold,
                scaler_params=scaler_params,
                class_frequencies=class_counts,
                hardware_profile=self.hw_profile,
                regime_signal=regime_signal,
            )

            # 🔥 FIX v19.1: ladder_size از کلاس مشتق می‌شود — نه هاردکد 31
            try:
                _LADDER_MAX_RUNGS = max(
                    1, len(AlternativeModelLadder.CLASSIFICATION_LADDER) - 1
                )
            except Exception as _lad_err:
                logger.warning(
                    f"[{phase}][STEP 11] ladder discovery failed ({_lad_err}); "
                    f"using safe fallback 32"
                )
                _LADDER_MAX_RUNGS = 32

            _STALL_WINDOW = 5
            _EVAL_MARGIN_PER_RUNG = 2
            _WARMUP_EPOCHS = 15
            _FOCUS_MODE_RESERVE = 30
            _desired_base_epochs = compute_logical_epoch_budget(
                ladder_size=_LADDER_MAX_RUNGS,
                stall_window=_STALL_WINDOW,
                eval_margin_per_rung=_EVAL_MARGIN_PER_RUNG,
                warmup_epochs=_WARMUP_EPOCHS,
                focus_reserve=_FOCUS_MODE_RESERVE,
            )

            _env_epochs = os.environ.get("OMNI_BASE_EPOCHS", "").strip()
            if _env_epochs:
                try:
                    _env_val = int(_env_epochs)
                    if 30 <= _env_val <= 2000:
                        _desired_base_epochs = _env_val
                except ValueError:
                    pass

            try:
                _original_base_epochs = int(self.dynamic_params.base_epochs)
                if _original_base_epochs < _desired_base_epochs:
                    self.dynamic_params.base_epochs = int(_desired_base_epochs)
                    self.dynamic_params.min_epochs = max(
                        int(getattr(self.dynamic_params, 'min_epochs', 8)),
                        _WARMUP_EPOCHS,
                    )
                    self.dynamic_params.max_epochs = int(_desired_base_epochs) + 80
            except Exception as e:
                logger.warning(f"[{phase}][STEP 11] epoch-budget: {e}")

            self.epochs = int(self.dynamic_params.base_epochs)
            self.learning_rate = float(self.dynamic_params.base_learning_rate)

            try:
                hp_path = (
                    f"logs/hyperparameters_{symbol}_{timeframe}_fold{fold}_"
                    f"{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
                )
                os.makedirs(os.path.dirname(hp_path), exist_ok=True)
                self.dynamic_params.save(hp_path)
            except Exception as e:
                logger.warning(f"[{phase}][STEP 11] save hyperparams: {e}")

            # [STEP 12] class weights
            class_weights = compute_class_weights_from_counts(
                class_counts, min_weight=0.5, max_weight=3.0
            )

            # [STEP 13] V11 gate
            base_loss_weights = {
                'price_return': 0.50,
                'price_direction': 1.80,
                'trend_strength': 0.60,
                'volatility_regime': 0.60,
                'market_regime': 0.60,
                'magnitude_bucket': 0.60,
            }
            try:
                _orig_count = len(y_train)
                y_train = {k: v for k, v in y_train.items() if v is not None}
                if len(y_train) < _orig_count:
                    logger.warning(
                        f"[{phase}] ⚠️ Dropped None targets from y_train: "
                        f"{[k for k in ALL_TARGETS if k not in y_train]}"
                    )
                _orig_count = len(y_val)
                y_val = {k: v for k, v in y_val.items() if v is not None}
                if len(y_val) < _orig_count:
                    logger.warning(
                        f"[{phase}] ⚠️ Dropped None targets from y_val: "
                        f"{[k for k in ALL_TARGETS if k not in y_val]}"
                    )
                v11 = prepare_v11_training(
                    X_train=X_train, y_train_dict=y_train,
                    X_val=X_val, y_val_dict=y_val,
                    n_classes_map=N_CLASSES_MAP,
                    backbone_config={},
                    base_loss_weights=base_loss_weights,
                    class_counts_map=class_counts,
                    checkpoint_paths=[
                        f"MODELS/checkpoints/{symbol}/{timeframe}/fold_{fold}/"
                        f"omni_refactored/best_model.keras"
                    ],
                    send_fn=lambda path, ctx: True,
                    run_gate=True, gate_permutations=200, min_ratio=4.0,
                    fastval_max_samples=1536, revival_patience=2,
                    max_revivals_per_head=3, lr_floor_ratio=0.30,
                    checkpoint_monitor='val_loss', log_fn=logger.info,
                )
                loss_weights = v11['loss_weights']
            except Exception as e:
                logger.error(f"[{phase}][STEP 13] V11 gate failed: {e}")
                logger.error(traceback.format_exc())
                loss_weights = dict(base_loss_weights)
                v11 = {
                    'callbacks': [], 'dead_targets': [],
                    'loss_weights': loss_weights,
                }

            # [STEP 14] datasets
            batch_size = int(self.dynamic_params.optimal_batch_size)
            train_dataset, train_steps = create_streaming_multi_output_dataset(
                X=X_train, y_dict=y_train, batch_size=batch_size,
                class_weights_map=None,
                shuffle=True, drop_remainder=False, seed=42,
                sample_weight_array=sample_weight_train,
                per_target_sample_weights=per_target_sample_weights_train,   # 🔥 NEW
            )
            val_dataset = None
            if X_val is not None and y_val:
                val_dataset, val_steps = create_streaming_multi_output_dataset(
                    X=X_val, y_dict=y_val, batch_size=batch_size,
                    class_weights_map=None,
                    shuffle=False, drop_remainder=False, seed=42,
                    sample_weight_array=None,
                    per_target_sample_weights=per_target_sample_weights_val,  # 🔥 NEW
                )
                
            # [STEP 15] model factory
            model_factory = DynamicModelFactory(self.dynamic_params)
            model_factory.initialize_from_data(
                X_train=X_train, y_train=y_train,
                X_val=X_val, X_test=X_test,
                symbol=symbol, timeframe=timeframe, fold=fold,
                scaler_params=scaler_params,
                class_frequencies=class_counts,
                regime_signal=regime_signal,
            )
            base_model = model_factory.create_multi_head_model(
                backbone_type='omni', use_dynamic_heads=True,
                use_cross_attention=True, use_softmax=False,
            )

            # [STEP 16] trainer
            task_names = list(OUTPUT_ORDER)
            trainer = SimpleMultiTaskTrainer(
                base_model=base_model,
                task_names=task_names,
                loss_weights=loss_weights,
                clip_norm=1.0,
                from_logits=True,
                focal_gamma=float(self.dynamic_params.focal_gamma),
                focal_alpha=0.25,
                label_smoothing=float(self.dynamic_params.label_smoothing),
            )
            optimizer = tf.keras.optimizers.AdamW(
                learning_rate=float(self.dynamic_params.base_learning_rate),
                weight_decay=5e-4,
                beta_1=0.9, beta_2=0.999, epsilon=1e-7,
            )
            trainer.compile(optimizer=optimizer, run_eagerly=False)

            # [STEP 17] checkpoint + resume
            checkpoint_dir = (
                f"MODELS/checkpoints/{symbol}/{timeframe}/fold_{fold}/omni_refactored"
            )
            os.makedirs(checkpoint_dir, exist_ok=True)

            try:
                trainer, start_epoch = self._load_latest_checkpoint(
                    model=trainer, checkpoint_dir=checkpoint_dir,
                    model_name="omni_refactored",
                    force_start_epoch=FORCE_START_EPOCH,
                )
                if start_epoch < 0:
                    start_epoch = 0
                if start_epoch >= self.epochs:
                    self.epochs = start_epoch + 20
            except Exception as e:
                logger.error(f"[{phase}][STEP 17] checkpoint resolution: {e}")
                start_epoch = 0

            # [STEP 17.5] callbacks + workflow_state injection
            logger.info("")
            logger.info("=" * 78)
            logger.info(f"[{phase}][STEP 17.5] 🔧 Building ALL callbacks...")
            logger.info("=" * 78)

            # [STEP 17.6] workflow state
            logger.info("")
            logger.info("=" * 78)
            logger.info(
                f"[{phase}][STEP 17.6] 🔄 Loading workflow state "
                f"(RESUME={'YES' if _RESUME else 'NO'})..."
            )
            logger.info("=" * 78)

            if _RESUME:
                workflow_state = _load_workflow_state_file(checkpoint_dir)
                if workflow_state is not None:
                    ws_epoch = workflow_state.get('current_epoch')
                    try:
                        ws_epoch_int = int(ws_epoch) if ws_epoch is not None else None
                    except (TypeError, ValueError):
                        ws_epoch_int = None
                    if ws_epoch_int is not None and ws_epoch_int > 0:
                        if ws_epoch_int > start_epoch:
                            logger.warning(
                                f"[{phase}][STEP 17.6] workflow epoch "
                                f"({ws_epoch_int}) > tracker epoch "
                                f"({start_epoch}) → using workflow epoch"
                            )
                            start_epoch = ws_epoch_int
                    logger.info(
                        f"[{phase}][STEP 17.6] ✅ workflow state loaded — "
                        f"epoch={workflow_state.get('current_epoch')}"
                    )
                else:
                    logger.info(
                        f"[{phase}][STEP 17.6] no workflow state file — "
                        f"fresh restart with resume-of-weights only"
                    )
            else:
                logger.info(
                    f"[{phase}][STEP 17.6] RESUME=OFF → skipping workflow state load"
                )

            logger.info(
                f"[{phase}][STEP 17.6] start_epoch={start_epoch}, "
                f"target={self.epochs}"
            )

            try:
                callbacks, diagnostics, collapse_detector = \
                    self._build_callbacks_for_model_omni(
                        name="omni_refactored",
                        wrapped_model=trainer,
                        checkpoint_dir=checkpoint_dir,
                        start_epoch=int(start_epoch),
                        regime_signal=regime_signal,
                        X_test=X_test,
                        y_test=y_test,
                        X_val=X_val,
                        y_val=y_val,
                        scaler_params=scaler_params,
                        train_dataset_weighted=train_dataset,
                        val_dataset_weighted=val_dataset,
                        class_frequencies=class_counts,
                        fold=fold,
                        symbol=symbol,
                        timeframe=timeframe,
                        collapse_detector=None,
                        workflow_state=workflow_state,
                        per_target_valid_masks_val=per_target_sample_weights_val,
                    )
                logger.info(
                    f"[{phase}][STEP 17.5] ✅ callbacks built: "
                    f"{len(callbacks)} total"
                )
            except Exception as _cb_err:
                logger.critical(
                    f"[{phase}][STEP 17.5] ❌ callback build FAILED: {_cb_err}",
                    exc_info=True,
                )
                raise

            for _cb in callbacks:
                if isinstance(_cb, SelfHealingTrainingOrchestrator):
                    orchestrator = _cb
                elif isinstance(_cb, AdaptiveMultiTaskTrainingController):
                    main_controller = _cb

            if main_controller is None:
                logger.critical(
                    f"[{phase}][STEP 17.5] ❌ "
                    f"AdaptiveMultiTaskTrainingController NOT FOUND"
                )
            else:
                logger.info(
                    f"[{phase}][STEP 17.5] ✅ Controller ready — "
                    f"stall="
                    f"{ {t: main_controller._quality_stall.get(t, 0) for t in main_controller.task_names} }, "
                    f"focus={main_controller.is_focus_mode_active()}"
                )

            if orchestrator is None:
                logger.warning(
                    f"[{phase}][STEP 17.5] ⚠️ SelfHealing not constructed"
                )
            else:
                logger.info(
                    f"[{phase}][STEP 17.5] ✅ SelfHealing available "
                    f"(attempts={orchestrator.get_current_attempts()}/"
                    f"{orchestrator.get_max_attempts()})"
                )

            try:
                self._adaptive_controller_ref = main_controller
            except Exception as _ref_err:
                logger.warning(
                    f"[{phase}][STEP 17.5] controller ref set: {_ref_err}"
                )

            # [STEP 18] inventory
            logger.info(
                f"[{phase}][STEP 18] ✅ total callbacks: {len(callbacks)}"
            )
            for i, cb in enumerate(callbacks, 1):
                logger.info(
                    f"[{phase}][STEP 18]   {i:2d}. {type(cb).__name__}"
                )

            # [STEP 19] training
            logger.info("")
            logger.info(f"[{phase}][STEP 19] " + "=" * 60)
            logger.info(
                f"[{phase}][STEP 19] Training from epoch {start_epoch} "
                f"to {self.epochs}"
            )
            if _RESUME and workflow_state is not None:
                logger.info(
                    f"[{phase}][STEP 19] 🔄 RESUMED — workflow state applied"
                )
            logger.info(f"[{phase}][STEP 19] " + "=" * 60)

            t_train_start = _time.time()
            if orchestrator is not None:
                try:
                    loop_result = orchestrator.run_external_healing_loop(
                        trainer=trainer,
                        train_dataset=train_dataset,
                        val_dataset=val_dataset,
                        initial_epochs=int(self.epochs),
                        initial_epoch=int(start_epoch),
                        callbacks=callbacks,
                        verbose=self.verbose,
                        hard_cap_safety_margin=2,
                    )
                    best_epoch = int(loop_result['best_global_epoch'])
                    best_val_loss = float(loop_result['best_val_loss'])
                except Exception as e:
                    logger.error(
                        f"[{phase}][STEP 19] healing loop failed: {e}"
                    )
                    logger.error(traceback.format_exc())
                    raise RuntimeError(
                        "SelfHealingTrainingOrchestrator failed; refusing "
                        "unsafe plain-fit fallback"
                    ) from e
            else:
                hist = trainer.fit(
                    train_dataset, validation_data=val_dataset,
                    epochs=int(self.epochs),
                    initial_epoch=int(start_epoch),
                    callbacks=callbacks, verbose=self.verbose,
                )
                vl = hist.history.get('val_loss', []) or []
                if vl:
                    bi = int(np.argmin(vl))
                    best_epoch = int(start_epoch) + bi + 1
                    best_val_loss = float(vl[bi])
                else:
                    best_epoch = int(start_epoch)
                    best_val_loss = float('inf')

            train_duration = _time.time() - t_train_start
            logger.info(
                f"[{phase}][STEP 19] ✅ training finished in "
                f"{train_duration:.1f}s"
            )

            # [STEP 20] load best
            best_checkpoint_path = os.path.join(
                checkpoint_dir, "best_model.keras"
            )
            best_model = None
            if os.path.exists(best_checkpoint_path):
                try:
                    # 🔥 v19.2: از load_model_with_full_metadata (tuple-safe)
                    # استفاده می‌کنیم، نه tf.keras.models.load_model که
                    # ممکن است wrapper را از .keras بازسازی کند.
                    _loaded = load_model_with_full_metadata(
                        best_checkpoint_path,
                        compile=False,
                        load_replacements=False,
                    )
                    if isinstance(_loaded, tuple):
                        best_model = _loaded[0] if len(_loaded) >= 1 else None
                    else:
                        best_model = _loaded
                    if best_model is not None and not hasattr(best_model, "predict"):
                        logger.warning(
                            f"[{phase}][STEP 20] best_model.keras loaded as "
                            f"{type(best_model).__name__} (no .predict) — "
                            f"discarding, trying epoch fallback."
                        )
                        best_model = None
                except Exception as e:
                    logger.error(f"[{phase}][STEP 20] load failed: {e}")

            if best_model is None:
                try:
                    import re as _re_ep
                    _pat = _re_ep.compile(r"^epoch_(\d+)\.keras$")
                    _cands = []
                    for _fn in os.listdir(checkpoint_dir):
                        _m = _pat.match(_fn)
                        if _m:
                            _cands.append((
                                int(_m.group(1)),
                                os.path.join(checkpoint_dir, _fn),
                            ))
                    _cands.sort(key=lambda x: x[0], reverse=True)
                    for _ep_id, _path in _cands[:3]:
                        try:
                            best_model = tf.keras.models.load_model(
                                _path, compile=False,
                                custom_objects=dict(CUSTOM_OBJECTS),
                            )
                            if best_model is not None:
                                best_epoch = _ep_id
                                break
                        except Exception:
                            pass
                except Exception as _scan_err:
                    logger.error(
                        f"[{phase}][STEP 20] scan failed: {_scan_err}"
                    )

            if best_model is None:
                logger.critical(f"[{phase}][STEP 20] ❌ no usable model")
                return {
                    'error': 'no_usable_model_found',
                    'phase': phase,
                    'symbol': symbol,
                    'timeframe': timeframe,
                    'elapsed_sec': round(_time.time() - t_run_start, 2),
                }

            # [STEP 21] save final
            final_model_path = (
                f"MODELS/final_models/{symbol}/{timeframe}/fold_{fold}/"
                f"OMNI_REFACTORED_FINAL.keras"
            )
            os.makedirs(os.path.dirname(final_model_path), exist_ok=True)

            repl_mgr_for_save = (
                main_controller.get_replacement_manager()
                if main_controller is not None else None
            )
            try:
                save_model_with_full_metadata(
                    model=best_model,
                    model_path=final_model_path,
                    metadata={
                        'model_type': 'OMNI_REFACTORED_V19_1',
                        'input_shape': list(X_train.shape[1:]),
                        'best_epoch': best_epoch,
                        'best_val_loss': best_val_loss,
                        'class_frequencies': class_counts,
                        'dynamic_hyperparameters': self.dynamic_params.to_dict(),
                        'loss_weights_used': loss_weights,
                        'lookback_used': int(_lookback),
                        'healing_attempts': (
                            orchestrator.get_current_attempts()
                            if orchestrator else 0
                        ),
                        'fresh_run': bool(_FRESH),
                        'resume': bool(_RESUME),
                        'timestamp': datetime.now().isoformat(),
                    },
                    include_optimizer=False,
                    dynamic_params=self.dynamic_params,
                    replacement_manager=repl_mgr_for_save,
                )
            except Exception as e:
                logger.error(f"[{phase}][STEP 21] final save failed: {e}")

            # [STEP 22] DIRECTION SIGNAL
            logger.info("")
            logger.info(
                f"[{phase}][STEP 22] 🧭 Extracting direction signal..."
            )

            signal_override = None
            _conf_thr = float(os.environ.get("OMNI_DIR_CONF", "0.55"))
            _cost_mult = float(os.environ.get("OMNI_COST_MULT", "2.0"))
            _tc = float(os.environ.get("OMNI_TX_COST", "0.0005"))
            _slip = float(os.environ.get("OMNI_SLIPPAGE", "0.0002"))
            _vol_win = int(os.environ.get("OMNI_VOL_LOOKBACK", "20"))
            _horizon = int(os.environ.get("OMNI_SIGNAL_HORIZON", "1"))

            if X_test is not None and len(X_test) >= 10:
                try:
                    _raw = best_model.predict(X_test, batch_size=1024, verbose=1)
                    _heads = resolve_head_outputs(best_model, _raw, None)
                    _dir_probs = _heads.get('price_direction')
                    if _dir_probs is None:
                        for k in _heads.keys():
                            if 'direction' in k.lower() or 'dir' in k.lower():
                                _dir_probs = _heads[k]
                                break

                    if _dir_probs is not None:
                        _dir_probs = np.asarray(_dir_probs, dtype=np.float64)
                        row_sums = _dir_probs.sum(axis=-1)
                        if not np.allclose(row_sums, 1.0, atol=1e-3):
                            _shifted = _dir_probs - _dir_probs.max(
                                axis=-1, keepdims=True
                            )
                            _exp = np.exp(_shifted)
                            _dir_probs = _exp / np.maximum(
                                _exp.sum(axis=-1, keepdims=True), 1e-12
                            )

                        n_dir_cols = (
                            int(_dir_probs.shape[-1])
                            if _dir_probs.ndim == 2 else 0
                        )

                        if n_dir_cols == 2:
                            try:
                                _recent_prices = None
                                try:
                                    from core.global_method import (
                                        get_active_symbol_timeframe as _gsf,
                                    )
                                    _s, _tf = _gsf()
                                    _rp_path = (
                                        f"data/raw/mt5/{_s}_{_tf}_close.npy"
                                    )
                                    if os.path.exists(_rp_path):
                                        _recent_prices = np.load(
                                            _rp_path
                                        )[-_vol_win * 3:]
                                    else:
                                        _rawwd = (
                                            f"data/processed/{_s}/{_tf}/"
                                            f"fold_{fold}/raw_close.npy"
                                        )
                                        if os.path.exists(_rawwd):
                                            _recent_prices = np.load(
                                                _rawwd
                                            )[-_vol_win * 3:]
                                except Exception as _rp_err:
                                    logger.debug(
                                        f"[{phase}][STEP 22] recent_prices "
                                        f"lookup failed: {_rp_err}"
                                    )

                                # ═══════════════════════════════════════════════════════
                                # 🔥 v19.3: recent_prices — MT5-live → raw HDF5 → processed
                                # ═══════════════════════════════════════════════════════
                                # قرارداد:
                                #   1) اگر MT5 نصب و متصل است، قیمت زنده گرفته می‌شود
                                #      (اولویت اول — سریع‌ترین و تازه‌ترین منبع).
                                #   2) اگر MT5 در دسترس نیست یا symbol_select ناکام شد،
                                #      از فایل خام HDF5 همان fold استفاده می‌شود.
                                #   3) اگر raw هم نبود، processed به‌عنوان آخرین منبع.
                                #   4) در نبود همه، signal_override=None (بدون جایگزین
                                #      مصنوعی — تصمیم v19.2 حفظ شده).
                                #
                                # ⚠️ نکته: این بلوک داخل متد async است، پس await معتبر است.
                                _recent_prices = None
                                _recent_prices_source = "none"
                                _recent_prices_errors: List[str] = []

                                # ---- 0) resolve symbol/timeframe (once) ----
                                try:
                                    from core.global_method import (
                                        get_active_symbol_timeframe as _gsf,
                                    )
                                    _s, _tf = _gsf()
                                except Exception as _gsf_err:
                                    _s, _tf = symbol, timeframe
                                    _recent_prices_errors.append(
                                        f"gsf: {_gsf_err}"
                                    )

                                _need_bars = max(50, int(_vol_win) * 5)

                                # ═══════════════════════════════════════════════════
                                # Attempt 1: MT5 LIVE (priority #1)
                                # ═══════════════════════════════════════════════════
                                try:
                                    from core.global_method import (
                                        MT5_AVAILABLE as _MT5_AVAIL,
                                        mt5 as _mt5_mod,
                                    )
                                except Exception as _mt5_imp_err:
                                    _MT5_AVAIL = False
                                    _mt5_mod = None
                                    _recent_prices_errors.append(
                                        f"mt5_import: {_mt5_imp_err}"
                                    )

                                if _MT5_AVAIL and _mt5_mod is not None:
                                    try:
                                        _tf_map = {
                                            "1M":  _mt5_mod.TIMEFRAME_M1,
                                            "5M":  _mt5_mod.TIMEFRAME_M5,
                                            "15M": _mt5_mod.TIMEFRAME_M15,
                                            "30M": _mt5_mod.TIMEFRAME_M30,
                                            "1H":  _mt5_mod.TIMEFRAME_H1,
                                            "4H":  _mt5_mod.TIMEFRAME_H4,
                                            "1D":  _mt5_mod.TIMEFRAME_D1,
                                        }
                                        _tf_const = _tf_map.get(
                                            str(_tf).upper()
                                        )

                                        if _tf_const is None:
                                            _recent_prices_errors.append(
                                                f"mt5_tf_unknown: {_tf}"
                                            )
                                        else:
                                            # اطمینان از initialize بودن terminal
                                            # (بدون shutdown در پایان — pipeline اصلی
                                            # مسئول چرخهٔ عمر است)
                                            try:
                                                if _mt5_mod.terminal_info() is None:
                                                    _mt5_mod.initialize()
                                            except Exception as _init_err:
                                                _recent_prices_errors.append(
                                                    f"mt5_init: {_init_err}"
                                                )

                                            # تلاش چند نگارش نماد (بروکرهای suffix-dar)
                                            _sym_candidates = [
                                                _s,
                                                _s.replace("USD", "USD.m"),
                                                _s.replace("USD", ".USD"),
                                                _s.replace(".", ""),
                                            ]
                                            # حذف تکراری‌ها با حفظ ترتیب
                                            _seen_syms = set()
                                            _sym_candidates = [
                                                c for c in _sym_candidates
                                                if not (
                                                    c in _seen_syms
                                                    or _seen_syms.add(c)
                                                )
                                            ]

                                            for _sym_cand in _sym_candidates:
                                                try:
                                                    if not _mt5_mod.symbol_select(
                                                        _sym_cand, True
                                                    ):
                                                        continue

                                                    _rates = (
                                                        _mt5_mod.copy_rates_from_pos(
                                                            _sym_cand,
                                                            _tf_const,
                                                            0,
                                                            _need_bars,
                                                        )
                                                    )
                                                    if (
                                                        _rates is None
                                                        or len(_rates) < 5
                                                    ):
                                                        continue

                                                    _dtype_names = (
                                                        _rates.dtype.names or ()
                                                    )
                                                    if 'close' not in _dtype_names:
                                                        _recent_prices_errors.append(
                                                            f"mt5_no_close_col:{_sym_cand}"
                                                        )
                                                        continue

                                                    _recent_prices = np.asarray(
                                                        _rates['close'],
                                                        dtype=np.float64,
                                                    )
                                                    _recent_prices = _recent_prices[
                                                        np.isfinite(_recent_prices)
                                                    ]
                                                    if _recent_prices.size >= 5:
                                                        _recent_prices_source = (
                                                            f"mt5_live({_sym_cand}/"
                                                            f"{_tf})"
                                                        )
                                                        logger.info(
                                                            f"[{phase}][STEP 22] "
                                                            f"✅ MT5 live prices: "
                                                            f"{_recent_prices.size} bars "
                                                            f"from {_sym_cand}/{_tf}"
                                                        )
                                                        break
                                                    else:
                                                        _recent_prices = None
                                                        _recent_prices_errors.append(
                                                            f"mt5_too_few_finite:{_sym_cand}"
                                                        )
                                                except Exception as _mt5_sym_err:
                                                    _recent_prices_errors.append(
                                                        f"mt5_{_sym_cand}: "
                                                        f"{_mt5_sym_err}"
                                                    )
                                                    continue
                                    except Exception as _mt5_outer_err:
                                        _recent_prices_errors.append(
                                            f"mt5_outer: {_mt5_outer_err}"
                                        )

                                # ═══════════════════════════════════════════════════
                                # Attempt 2: RAW HDF5 (fallback #1)
                                # ═══════════════════════════════════════════════════
                                if (
                                    _recent_prices is None
                                    or _recent_prices.size < 5
                                ):
                                    try:
                                        from core.global_method import (
                                            universal_load as _ul_raw,
                                        )
                                        _raw_df = await _ul_raw(
                                            data_type="raw",
                                            symbol=_s,
                                            timeframe=_tf,
                                            fold=fold,
                                        )

                                        if (
                                            _raw_df is not None
                                            and hasattr(_raw_df, 'columns')
                                            and len(_raw_df) > 0
                                        ):
                                            # case-insensitive close lookup
                                            _close_col = None
                                            for _c in _raw_df.columns:
                                                if str(_c).lower() == 'close':
                                                    _close_col = _c
                                                    break

                                            if _close_col is not None:
                                                _raw_close = np.asarray(
                                                    _raw_df[_close_col],
                                                    dtype=np.float64,
                                                )
                                                _raw_close = _raw_close[
                                                    np.isfinite(_raw_close)
                                                ]
                                                if _raw_close.size >= 5:
                                                    _recent_prices = _raw_close[
                                                        -_need_bars:
                                                    ]
                                                    _recent_prices_source = (
                                                        f"raw_hdf5(fold={fold})"
                                                    )
                                                    logger.info(
                                                        f"[{phase}][STEP 22] "
                                                        f"✅ RAW HDF5 prices: "
                                                        f"{_recent_prices.size} samples "
                                                        f"from fold {fold}"
                                                    )
                                                else:
                                                    _recent_prices_errors.append(
                                                        "raw_too_few_finite"
                                                    )
                                            else:
                                                _recent_prices_errors.append(
                                                    f"raw_no_close_col:"
                                                    f"{list(_raw_df.columns)[:5]}"
                                                )
                                        else:
                                            _recent_prices_errors.append(
                                                "raw_df_empty_or_none"
                                            )
                                    except Exception as _raw_err:
                                        _recent_prices_errors.append(
                                            f"raw: {_raw_err}"
                                        )
                                        logger.debug(
                                            f"[{phase}][STEP 22] raw HDF5 "
                                            f"failed: {_raw_err}"
                                        )

                                # ═══════════════════════════════════════════════════
                                # Attempt 3: PROCESSED (fallback #2)
                                # ═══════════════════════════════════════════════════
                                if (
                                    _recent_prices is None
                                    or _recent_prices.size < 5
                                ):
                                    try:
                                        from core.global_method import (
                                            universal_load as _ul_proc,
                                        )
                                        _proc_df = await _ul_proc(
                                            data_type="processed",
                                            symbol=_s,
                                            timeframe=_tf,
                                            fold=fold,
                                            split_type="train",
                                        )

                                        if (
                                            _proc_df is not None
                                            and hasattr(_proc_df, 'columns')
                                            and len(_proc_df) > 0
                                        ):
                                            _close_col = None
                                            for _c in _proc_df.columns:
                                                if str(_c).lower() == 'close':
                                                    _close_col = _c
                                                    break

                                            if _close_col is not None:
                                                _proc_close = np.asarray(
                                                    _proc_df[_close_col],
                                                    dtype=np.float64,
                                                )
                                                _proc_close = _proc_close[
                                                    np.isfinite(_proc_close)
                                                ]
                                                if _proc_close.size >= 5:
                                                    _recent_prices = _proc_close[
                                                        -_need_bars:
                                                    ]
                                                    _recent_prices_source = (
                                                        f"processed(fold={fold})"
                                                    )
                                                    logger.info(
                                                        f"[{phase}][STEP 22] "
                                                        f"✅ PROCESSED prices: "
                                                        f"{_recent_prices.size} samples"
                                                    )
                                                else:
                                                    _recent_prices_errors.append(
                                                        "processed_too_few_finite"
                                                    )
                                            else:
                                                _recent_prices_errors.append(
                                                    "processed_no_close_col"
                                                )
                                        else:
                                            _recent_prices_errors.append(
                                                "processed_df_empty_or_none"
                                            )
                                    except Exception as _proc_err:
                                        _recent_prices_errors.append(
                                            f"processed: {_proc_err}"
                                        )
                                        logger.debug(
                                            f"[{phase}][STEP 22] processed "
                                            f"failed: {_proc_err}"
                                        )

                                # ═══════════════════════════════════════════════════
                                # Final decision: DirectionSignalBuilder on/off
                                # ═══════════════════════════════════════════════════
                                if (
                                    _recent_prices is None
                                    or _recent_prices.size < 5
                                ):
                                    # 🔥 v19.3: هرگز از np.arange به‌عنوان قیمت
                                    # مصنوعی استفاده نمی‌کنیم — آن σ≈0 می‌سازد و
                                    # همه سیگنال‌ها را FLAT می‌کند.
                                    logger.warning(
                                        f"[{phase}][STEP 22] recent_prices "
                                        f"غیرقابل‌دسترس (MT5/raw/processed همه "
                                        f"ناموفق) — DirectionSignalBuilder "
                                        f"غیرفعال می‌ماند. "
                                        f"errors={_recent_prices_errors[-3:]}"
                                    )
                                    _dsb = None
                                else:
                                    logger.info(
                                        f"[{phase}][STEP 22] recent_prices "
                                        f"source={_recent_prices_source} | "
                                        f"n={_recent_prices.size} | "
                                        f"range=[{_recent_prices.min():.6g}, "
                                        f"{_recent_prices.max():.6g}]"
                                    )
                                    _dsb = DirectionSignalBuilder(
                                        confidence_threshold=_conf_thr,
                                        cost_multiplier=_cost_mult,
                                        transaction_cost=_tc,
                                        slippage=_slip,
                                        volatility_lookback=_vol_win,
                                        horizon=_horizon,
                                        safety_k=1.0,
                                    )

                                if _dsb is not None:
                                    signal_override = _dsb.build_signal(
                                        _dir_probs, _recent_prices
                                    )
                                    _n_sell = int(np.sum(signal_override == -1))
                                    _n_buy = int(np.sum(signal_override == 1))
                                    _n_flat = int(np.sum(signal_override == 0))
                                    logger.info(
                                        f"[{phase}][STEP 22] ✅ 2-class signal "
                                        f"built (N={len(signal_override)}, "
                                        f"SELL={_n_sell}, BUY={_n_buy}, "
                                        f"NEUTRAL={_n_flat})"
                                    )

                            except Exception as _dsb_err:
                                logger.warning(
                                    f"[{phase}][STEP 22] "
                                    f"DirectionSignalBuilder failed "
                                    f"({_dsb_err}); falling back to "
                                    f"simple threshold."
                                )
                                _argmax = _dir_probs.argmax(axis=1)
                                _max_p = _dir_probs.max(axis=1)
                                _sig = np.zeros(
                                    len(_argmax), dtype=np.int64
                                )
                                _sig[(_argmax == 1) & (_max_p >= _conf_thr)] = +1
                                _sig[(_argmax == 0) & (_max_p >= _conf_thr)] = -1
                                signal_override = _sig
                        else:
                            logger.warning(
                                f"[{phase}][STEP 22] direction head has "
                                f"unexpected width={n_dir_cols} — "
                                f"signal_override left None"
                            )
                    else:
                        logger.warning(
                            f"[{phase}][STEP 22] no direction head found in "
                            f"{sorted(_heads.keys())} — signal_override=None"
                        )
                except Exception as e:
                    logger.error(
                        f"[{phase}][STEP 22] signal extraction failed: {e}",
                        exc_info=True,
                    )
            else:
                logger.info(
                    f"[{phase}][STEP 22] skipped — X_test too small or None"
                )

            # [STEP 22.5] REPLACEMENT PREDICTIONS
            replacement_predictions: Dict[str, np.ndarray] = {}
            if (repl_mgr_for_save is not None and X_test is not None
                    and len(X_test) > 0):
                _replaced_targets = []
                try:
                    _replaced_targets = list(
                        repl_mgr_for_save.get_replaced_targets()
                    )
                except Exception as _grt_err:
                    logger.debug(
                        f"[{phase}][STEP 22.5] get_replaced_targets failed: "
                        f"{_grt_err}"
                    )

                for tgt in _replaced_targets:
                    if tgt == 'price_return':
                        continue
                    try:
                        preds_repl = repl_mgr_for_save.predict_from_replacement(
                            tgt, X_test
                        )
                        if preds_repl is not None:
                            replacement_predictions[tgt] = np.asarray(
                                preds_repl
                            )
                            logger.info(
                                f"[{phase}][STEP 22.5] 🔁 replacement "
                                f"predictions for '{tgt}' injected "
                                f"(shape={np.asarray(preds_repl).shape})"
                            )
                    except Exception as _repl_err:
                        logger.warning(
                            f"[{phase}][STEP 22.5] "
                            f"predict_from_replacement('{tgt}') failed: "
                            f"{_repl_err}"
                        )

            # [STEP 23] FINANCIAL EVALUATION
            logger.info("")
            logger.info(
                f"[{phase}][STEP 23] 📊 Financial evaluation on test set..."
            )

            fin_metrics: Dict[str, Any] = {}
            if X_test is not None and y_test is not None and len(X_test) >= 100:
                try:
                    _stop_loss = float(os.environ.get("OMNI_STOP_LOSS", "0.03"))
                    _take_profit = float(
                        os.environ.get("OMNI_TAKE_PROFIT", "0.06")
                    )
                    _trailing = float(
                        os.environ.get("OMNI_TRAILING_STOP", "0.015")
                    )
                    _tc_fee = float(os.environ.get("OMNI_TX_COST", "0.0005"))
                    _slip_fee = float(
                        os.environ.get("OMNI_SLIPPAGE", "0.0002")
                    )

                    fin_metrics = evaluate_model_financial_sync(
                        model=best_model,
                        X_test=X_test,
                        y_test_dict=y_test,
                        scaler_params=scaler_params,
                        data_is_normalized=True,
                        stop_loss=_stop_loss,
                        take_profit=_take_profit,
                        trailing_stop=_trailing,
                        transaction_cost=_tc_fee,
                        slippage=_slip_fee,
                        signal_override=signal_override,
                        replacement_predictions=replacement_predictions,
                        timeframe=timeframe,
                        verbose=True,
                    )

                    logger.info(
                        f"[{phase}][STEP 23] ✅ metrics: "
                        f"Sharpe={fin_metrics.get('sharpe_ratio', 0):.4f} | "
                        f"WR={fin_metrics.get('win_rate', 0):.2%} | "
                        f"PF={fin_metrics.get('profit_factor', 0):.3f} | "
                        f"MaxDD={fin_metrics.get('max_drawdown', 0):.2%} | "
                        f"Trades={fin_metrics.get('total_trades', 0)} | "
                        f"bacc={fin_metrics.get('balanced_directional_accuracy', 0):.2%} | "
                        f"space={fin_metrics.get('return_space', 'unknown')} | "
                        f"ruined={fin_metrics.get('ruined', False)}"
                    )
                    if fin_metrics.get('sharpe_hit_clip_cap'):
                        logger.error(
                            f"[{phase}][STEP 23] 🚨 Sharpe hit clip cap — "
                            f"simulator output is UNTRUSTWORTHY."
                        )
                except Exception as e:
                    logger.error(
                        f"[{phase}][STEP 23] financial evaluation failed: {e}",
                        exc_info=True,
                    )
                    fin_metrics = {}
            else:
                logger.warning(
                    f"[{phase}][STEP 23] skipped — need X_test/y_test with "
                    f"≥100 samples "
                    f"(got {len(X_test) if X_test is not None else 'None'})"
                )

            # [STEP 24] EDGE VALIDATION
            logger.info("")
            logger.info(
                f"[{phase}][STEP 24] 🔬 Anti-Fragile edge validation "
                f"(13 stress tests)..."
            )

            is_true_edge = False
            validation_report = None
            validation_report_dict: Optional[Dict[str, Any]] = None
            per_test_results: List[Dict[str, Any]] = []

            if (X_test is not None and y_test is not None
                    and len(X_test) >= 500):
                try:
                    _original_sharpe = float(
                        fin_metrics.get('sharpe_ratio', 0.0) or 0.0
                    )

                    validator = AntiFragileEdgeValidator(
                        model=best_model,
                        X_test=X_test,
                        y_test_dict=y_test,
                        scaler_params=scaler_params,
                        regime_signal=regime_signal,
                        original_sharpe=_original_sharpe,
                        logger=logger,
                        X_train=X_train,
                        y_train_dict=y_train,
                        original_feature_count=(
                            int(X_train.shape[2])
                            if hasattr(X_train, 'shape') and X_train.ndim == 3
                            else None
                        ),
                        dynamic_params=self.dynamic_params,
                        task_names=ALL_TARGETS,
                        output_order=ALL_TARGETS,
                    )

                    validation_report = await validator.validate_edge()
                    is_true_edge = bool(validation_report.is_true_edge)

                    try:
                        per_test_results = [
                            {
                                'test_name': str(r.test_name),
                                'passed': bool(r.passed),
                                'skipped': bool(getattr(r, 'skipped', False)),
                                'original_sharpe': float(r.original_sharpe),
                                'stress_sharpe': float(r.stress_sharpe),
                                'degradation': float(r.degradation),
                                'confidence': float(r.confidence),
                                'details': str(r.details),
                                'leakage_detected': (
                                    r.leakage_detected.value
                                    if r.leakage_detected is not None else None
                                ),
                            }
                            for r in validation_report.test_results
                        ]

                        validation_report_dict = {
                            'model_name': str(validation_report.model_name),
                            'is_true_edge': bool(validation_report.is_true_edge),
                            'confidence_score': float(
                                validation_report.confidence_score
                            ),
                            'leakage_suspicion': [
                                str(l.value)
                                for l in validation_report.leakage_suspicion
                            ],
                            'recommendation': str(
                                validation_report.recommendation
                            ),
                            'final_sharpe_under_stress': float(
                                validation_report.final_sharpe_under_stress
                            ),
                            'per_test_results': per_test_results,
                            'n_passed': int(sum(
                                1 for r in per_test_results if r['passed']
                            )),
                            'n_failed': int(sum(
                                1 for r in per_test_results
                                if not r['passed'] and not r['skipped']
                            )),
                            'n_skipped': int(sum(
                                1 for r in per_test_results if r['skipped']
                            )),
                        }
                    except Exception as _dict_err:
                        logger.warning(
                            f"[{phase}][STEP 24] could not serialize full "
                            f"validation report: {_dict_err}"
                        )

                    for _tr in per_test_results:
                        _icon = (
                            "⏭" if _tr['skipped']
                            else ("✅" if _tr['passed'] else "❌")
                        )
                        logger.info(
                            f"[{phase}][STEP 24]   {_icon} "
                            f"{_tr['test_name']:<40s} "
                            f"sharpe_orig={_tr['original_sharpe']:+.4f}  "
                            f"sharpe_stress={_tr['stress_sharpe']:+.4f}  "
                            f"degrad={_tr['degradation']:+.2%}  "
                            f"conf={_tr['confidence']:.2f}"
                        )

                    logger.warning(
                        f"[{phase}][STEP 24] ✅ edge validation done — "
                        f"is_true_edge={is_true_edge}, "
                        f"confidence="
                        f"{validation_report.confidence_score:.2%}, "
                        f"passed={validation_report_dict.get('n_passed', 0)}/"
                        f"{len(per_test_results)}"
                    )

                    if validation_report.leakage_suspicion:
                        logger.error(
                            f"[{phase}][STEP 24] 🚨 LEAKAGE DETECTED: "
                            f"{[l.value for l in validation_report.leakage_suspicion]}"
                        )
                except Exception as e:
                    logger.error(
                        f"[{phase}][STEP 24] edge validation failed: {e}",
                        exc_info=True,
                    )
            else:
                logger.warning(
                    f"[{phase}][STEP 24] skipped — need X_test/y_test with "
                    f"≥500 samples"
                )

            # [STEP 25] RESULTS DICT
            logger.info("")
            logger.info(
                f"[{phase}][STEP 25] 📦 Building final results dict..."
            )

            _total_duration = round(_time.time() - t_run_start, 2)
            _train_duration = round(train_duration, 2)

            _signal_stats: Dict[str, int] = {}
            if signal_override is not None:
                _signal_stats = {
                    'n_sell': int(np.sum(signal_override == -1)),
                    'n_buy': int(np.sum(signal_override == 1)),
                    'n_flat': int(np.sum(signal_override == 0)),
                    'n_total': int(signal_override.size),
                }

            _healing_attempts = (
                orchestrator.get_current_attempts() if orchestrator else 0
            )
            _healing_max = (
                orchestrator.get_max_attempts() if orchestrator else 0
            )

            results = {
                'model_name': 'OMNI_REFACTORED_V19_1',
                'symbol': symbol,
                'timeframe': timeframe,
                'fold': fold,
                'lookback': int(_lookback),
                'best_epoch': int(best_epoch),
                'best_val_loss': float(best_val_loss),
                'test_metrics': fin_metrics or {},
                'is_true_edge': bool(is_true_edge),
                'validation_report': validation_report_dict,
                'validation_report_summary': (
                    {
                        'confidence_score': float(
                            validation_report.confidence_score
                        ),
                        'recommendation': str(
                            validation_report.recommendation
                        ),
                        'passed_tests': sum(
                            1 for r in validation_report.test_results
                            if r.passed
                        ),
                        'total_tests': len(validation_report.test_results),
                        'final_sharpe_under_stress': float(
                            validation_report.final_sharpe_under_stress
                        ),
                        'leakage_suspicion': [
                            str(l.value)
                            for l in validation_report.leakage_suspicion
                        ],
                    }
                    if validation_report is not None else None
                ),
                'direction_signal_stats': _signal_stats,
                'replacement_predictions_injected': sorted(
                    list(replacement_predictions.keys())
                ),
                'model_path': final_model_path,
                'best_checkpoint_path': best_checkpoint_path,
                'checkpoint_dir': checkpoint_dir,
                'hyperparameters': self.dynamic_params.to_dict(),
                'loss_weights_used': loss_weights,
                'class_frequencies': class_counts,
                'healing_attempts': int(_healing_attempts),
                'healing_max_attempts': int(_healing_max),
                'fresh_run': bool(_FRESH),
                'resume': bool(_RESUME),
                'total_duration_sec': _total_duration,
                'train_duration_sec': _train_duration,
                'env_overrides': {
                    'OMNI_FRESH_RUN': _FRESH,
                    'OMNI_RESUME': _RESUME,
                    'OMNI_VERBOSE': _VERBOSE,
                    'OMNI_LOOKBACK': _lookback,
                    'OMNI_DIR_CONF': _conf_thr,
                    'OMNI_COST_MULT': _cost_mult,
                    'OMNI_TX_COST': _tc,
                    'OMNI_SLIPPAGE': _slip,
                    'OMNI_VOL_LOOKBACK': _vol_win,
                    'OMNI_SIGNAL_HORIZON': _horizon,
                },
                'timestamp': datetime.now().isoformat(),
            }

            logger.info(
                f"[{phase}][STEP 25] ✅ results dict built "
                f"({len(results)} top-level keys)"
            )

            # [STEP 26] SAVE JSON REPORT
            logger.info("")
            logger.info(f"[{phase}][STEP 26] 💾 Saving report...")

            report_path = (
                f"logs/final_report_{symbol}_{timeframe}_fold{fold}_"
                f"{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
            )
            try:
                os.makedirs(os.path.dirname(report_path), exist_ok=True)
                with open(report_path, 'w', encoding='utf-8') as _f:
                    json.dump(
                        _to_jsonable(results), _f,
                        indent=2, ensure_ascii=False, default=str,
                    )
                logger.info(
                    f"[{phase}][STEP 26] ✅ report saved: {report_path} "
                    f"({os.path.getsize(report_path) / 1024:.1f} KB)"
                )
            except Exception as e:
                logger.error(
                    f"[{phase}][STEP 26] report save failed: {e}",
                    exc_info=True,
                )

            # [STEP 27] TELEGRAM NOTIFICATION
            logger.info("")
            logger.info(
                f"[{phase}][STEP 27] 📨 Sending Telegram notification..."
            )

            try:
                _sharpe_v = float(fin_metrics.get('sharpe_ratio', 0) or 0)
                _sortino_v = float(fin_metrics.get('sortino_ratio', 0) or 0)
                _wr_v = float(fin_metrics.get('win_rate', 0) or 0)
                _pf_v = float(fin_metrics.get('profit_factor', 0) or 0)
                _dd_v = float(fin_metrics.get('max_drawdown', 0) or 0)
                _tr_v = float(fin_metrics.get('total_return', 0) or 0)
                _trades_v = int(fin_metrics.get('total_trades', 0) or 0)
                _dir_v = float(
                    fin_metrics.get('balanced_directional_accuracy', 0) or 0
                )
                _dir_raw_v = float(
                    fin_metrics.get('directional_accuracy', 0) or 0
                )
                _space_v = str(fin_metrics.get('return_space', 'unknown'))
                _ruined_v = bool(fin_metrics.get('ruined', False))
                _suspect_v = bool(fin_metrics.get('sharpe_suspect', False))

                _edge_icon = "✅" if is_true_edge else "❌"
                _ruin_icon = "🚨" if _ruined_v else "✅"
                _suspect_icon = "🚨" if _suspect_v else "✅"

                _sig_line = "—"
                if _signal_stats:
                    _sig_line = (
                        f"SELL=`{_signal_stats['n_sell']}`, "
                        f"BUY=`{_signal_stats['n_buy']}`, "
                        f"FLAT=`{_signal_stats['n_flat']}`"
                    )

                _edge_conf = "—"
                _edge_rec = "—"
                if validation_report is not None:
                    _edge_conf = f"{validation_report.confidence_score:.1%}"
                    _edge_rec = str(validation_report.recommendation)[:120]

                tel_log.trade(
                    f"🏁 *RUN_TESTS v19.1 COMPLETE*\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"*Symbol*   : `{symbol}/{timeframe}` fold=`{fold}`\n"
                    f"*Lookback* : `{_lookback}` (discovered)\n"
                    f"*Best Ep*  : `{best_epoch}`\n"
                    f"*Best Val* : `{best_val_loss:.6f}`\n"
                    f"━━━ 💰 Test Metrics ━━━\n"
                    f"*Sharpe*   : `{_sharpe_v:.4f}` {_suspect_icon}\n"
                    f"*Sortino*  : `{_sortino_v:.4f}`\n"
                    f"*WR*       : `{_wr_v:.2%}`\n"
                    f"*PF*       : `{_pf_v:.3f}`\n"
                    f"*MaxDD*    : `{_dd_v:.2%}`\n"
                    f"*TotRet*   : `{_tr_v:.2%}`\n"
                    f"*Trades*   : `{_trades_v}`\n"
                    f"*DirAcc(bacc)*: `{_dir_v:.2%}`\n"
                    f"*DirAcc(raw)* : `{_dir_raw_v:.2%}`\n"
                    f"*Space*    : `{_space_v}` {_ruin_icon}\n"
                    f"━━━ 🎯 Direction Signal ━━━\n"
                    f"{_sig_line}\n"
                    f"━━━ 🛡 Edge Validation ━━━\n"
                    f"*True Edge*: `{_edge_icon}`\n"
                    f"*Confidence*: `{_edge_conf}`\n"
                    f"*Rec*      : `{_edge_rec}`\n"
                    f"━━━ 🔄 Healing ━━━\n"
                    f"*Attempts* : `{_healing_attempts}/{_healing_max}`\n"
                    f"━━━ 📊 Timing ━━━\n"
                    f"*Train*    : `{_train_duration:.0f}s`\n"
                    f"*Total*    : `{_total_duration:.0f}s`\n"
                    f"*Fresh*    : `{_FRESH}` | *Resume*: `{_RESUME}`\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"📁 `{os.path.basename(report_path)}`"
                )
                logger.info(
                    f"[{phase}][STEP 27] ✅ Telegram notification sent"
                )
            except Exception as e:
                logger.warning(
                    f"[{phase}][STEP 27] Telegram failed: {e}",
                    exc_info=True,
                )

            # [STEP 28] FINAL SUMMARY
            logger.info("")
            logger.info("╔" + "═" * 78 + "╗")
            logger.info("║" + " RUN_TESTS v19.1 — COMPLETE ".center(78) + "║")
            logger.info("╠" + "═" * 78 + "╣")
            logger.info(
                f"║  Symbol/Timeframe    : {symbol}/{timeframe} fold={fold}".ljust(79) + "║"
            )
            logger.info(
                f"║  Lookback (discovered): {_lookback}".ljust(79) + "║"
            )
            logger.info(
                f"║  Best epoch          : {best_epoch}".ljust(79) + "║"
            )
            logger.info(
                f"║  Best val_loss       : {best_val_loss:.6f}".ljust(79) + "║"
            )
            logger.info(
                f"║  Test Sharpe         : {_sharpe_v:.4f}".ljust(79) + "║"
            )
            logger.info(
                f"║  Test Win Rate       : {_wr_v:.2%}".ljust(79) + "║"
            )
            logger.info(
                f"║  Test DirAcc (bacc)  : {_dir_v:.2%}".ljust(79) + "║"
            )
            logger.info(
                f"║  Test Trades         : {_trades_v}".ljust(79) + "║"
            )
            logger.info(
                f"║  Return space        : {_space_v}".ljust(79) + "║"
            )
            logger.info(
                f"║  True Edge           : "
                f"{'YES' if is_true_edge else 'NO'}".ljust(79) + "║"
            )
            logger.info(
                f"║  Healing attempts    : {_healing_attempts}/{_healing_max}".ljust(79) + "║"
            )
            logger.info(
                f"║  Total duration      : {_total_duration:.0f}s".ljust(79) + "║"
            )
            logger.info(
                f"║  Report path         : {os.path.basename(report_path)}".ljust(79) + "║"
            )
            logger.info("╚" + "═" * 78 + "╝")
            logger.info("")

            return results

        except Exception as e:
            logger.error(f"[{phase}] ❌❌❌ CRITICAL FAILURE: {e}")
            logger.error(traceback.format_exc())
            return {
                'error': str(e),
                'traceback': traceback.format_exc(),
                'phase': phase,
                'symbol': symbol,
                'timeframe': timeframe,
                'elapsed_sec': round(_time.time() - t_run_start, 2),
            }
            
async def main():
    logger.info("\n" + "=" * 80)
    logger.info("🏛 DYNAMIC LEARNABILITY SUITE - WALL STREET QUANT EDITION v4.0")
    logger.info("   Features: Leakage-Free HFT Pipeline")
    logger.info("   Targets: Return + Direction + Volatility + Regime")
    logger.info("=" * 80 + "\n")

    suite = DynamicLearnabilitySuite()
    result = await suite.run_tests(data_is_normalized=True)

    try:
        from core.rubika_logger import send_latest_log_to_rubika
        send_latest_log_to_rubika()
    except Exception as e:
        logger.warning(f"⚠️ Could not send log to Rubika: {e}")

    try:
        logger.send_log_file("runtime")
    except Exception as e:
        logger.warning(f"⚠️ Could not send log file: {e}")

    logger.info("\n" + "=" * 80)
    logger.info("📊 FINAL RESULTS SUMMARY")
    logger.info("=" * 80)

    if not isinstance(result, dict):
        logger.error(f"❌ run_tests() returned unexpected type: {type(result)}")
    elif 'error' in result:
        logger.error(f"❌ run_tests() FAILED: {result['error']}")
    else:
        model_name = result.get('model_name', 'Unknown')
        test_metrics = result.get('test_metrics') or {}
        sharpe = test_metrics.get('sharpe_ratio', 0) or 0
        win_rate = test_metrics.get('win_rate', 0) or 0
        dir_acc = test_metrics.get('directional_accuracy', 0) or 0
        is_true_edge = result.get('is_true_edge', False)

        logger.info(f"\n🏆 {model_name}: Sharpe={sharpe:.4f}, WR={win_rate:.2%}, DirAcc={dir_acc:.2%}")
        logger.info(f"   Best epoch    : {result.get('best_epoch', 'N/A')}")
        logger.info(f"   Best val_loss : {result.get('best_val_loss', 'N/A')}")
        logger.info(f"   True edge     : {'✅ YES' if is_true_edge else '❌ NO'}")
        logger.info(f"   Model path    : {result.get('model_path', 'N/A')}")

    logger.info("\n✅ Execution complete!")
    return result


if __name__ == "__main__":
    asyncio.run(main())